INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89757, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "哭泣是难过时流着眼泪，轻轻地哭。", "primary_collocate": null, "pronunciation": "kū qì", "ipa": "kʰu˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "小女孩难过得轻轻哭泣，眼泪流个不停。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影演到最后，观众都在小声哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹考试没考好，坐在桌前哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她流着眼泪，轻轻地哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着那首老歌，他不知不觉哭泣起来。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝不再大哭，只是轻声哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友搬走那天，我在车站哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕吵醒室友，把头靠在枕头上哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他难过地坐在门口哭泣，没有说话。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨中，一个小男孩正哭泣着找妈妈。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哭泣着", "label": "体标"}, {"form": "哭泣过", "label": "体标"}, {"form": "哭泣了", "label": "体标"}], "register": "书面", "sense_fingerprint": "哭泣|动词|难过时流着眼泪轻轻地哭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哭泣", "is_correct": true, "explanation": "哭泣指因难过而轻轻流泪，与“眼泪流个不停”相符。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：大笑表示高兴，与难过的情绪不符。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：欢呼表示兴奋，与难过、流泪的语境相反。"}, {"text": "咆哮", "is_correct": false, "explanation": "搭配：“轻轻”与“咆哮”矛盾，不能搭配。"}], "explanations": {"哭泣": "哭泣指因难过而轻轻流泪，与“眼泪流个不停”相符。", "大笑": "语义：大笑表示高兴，与难过的情绪不符。", "欢呼": "语义：欢呼表示兴奋，与难过、流泪的语境相反。", "咆哮": "搭配：“轻轻”与“咆哮”矛盾，不能搭配。"}, "sentence_index": 0, "correct_answer": "哭泣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在街上哭泣，嗓门大得整条街都听得见。", "explanation": "这里应该用〈哭喊〉。哭泣是轻轻地哭，嗓门大的哭要说哭喊。"}, {"text": "她看见新出的蛋糕，馋得哭泣起来。", "explanation": "这里应该用〈垂涎〉。哭泣表示难过时流泪，见到美食的渴望要说垂涎。"}, {"text": "她切洋葱时哭泣起来。", "explanation": "这里应该用〈流泪〉。哭泣表示难过时流泪，被洋葱辣出的眼泪要说流泪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哭泣", "is_correct": true, "explanation": "哭泣指因离别而流泪，符合朋友搬走、我在车站的语境。"}, {"text": "眼泪", "is_correct": false, "explanation": "词性：眼泪是名词，不能作谓语，不能说“我在车站眼泪”。"}, {"text": "手帕", "is_correct": false, "explanation": "词性：手帕是名词，不能作谓语。"}, {"text": "悲剧", "is_correct": false, "explanation": "词性：悲剧是名词，不能作谓语表示动作。"}], "explanations": {"哭泣": "哭泣指因离别而流泪，符合朋友搬走、我在车站的语境。", "眼泪": "词性：眼泪是名词，不能作谓语，不能说“我在车站眼泪”。", "手帕": "词性：手帕是名词，不能作谓语。", "悲剧": "词性：悲剧是名词，不能作谓语表示动作。"}, "sentence_index": 6, "correct_answer": "哭泣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在会议上哭泣了一番苦衷。", "explanation": "这里应该用〈倾诉〉。哭泣是不及物动词，不能带“苦衷”作宾语；把心里的苦处说出来要说倾诉。"}, {"text": "他在商店里哭泣了一辆新自行车。", "explanation": "这里应该用〈买〉。哭泣是不及物动词，不能带“一辆新自行车”作宾语。"}, {"text": "他打篮球打得很哭泣。", "explanation": "这里应该用〈出色〉。哭泣表示难过时流泪，不能用来评价球技。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子哭泣的一会儿就睡着了。", "corrected_sentence": "孩子哭泣了一会儿就睡着了。", "error_description": "表示动作完成要用“了”，应说“哭泣了一会儿”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天哭泣着很久。", "corrected_sentence": "她昨天哭泣了很久。", "error_description": "动词后接时段“很久”表示动作持续的时长，要用“了”，不能用“着”，应说“哭泣了很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
