INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因悲伤或痛苦而流泪，低声哭。", "primary_collocate": null, "pronunciation": "kū qì", "ipa": "kʰu˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "她想起去世的奶奶，在房间里低声哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，我听见隔壁有人在哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子因为丢了小狗，伤心地哭泣着。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，母亲坐在床边哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躲在角落里哭泣，不想让别人看见。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，很多人在废墟前哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭泣过很多次，但从不告诉别人。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完那封信，他忍不住哭泣起来。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去朋友的痛苦让她整夜哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外下着雨，她一个人默默哭泣。", "target_word": "哭泣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哭泣着", "label": "体标"}, {"form": "哭泣过", "label": "体标"}, {"form": "哭泣了", "label": "体标"}], "register": "书面", "sense_fingerprint": "哭泣|动词|因悲伤痛苦流泪低声哭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哭泣", "is_correct": true, "explanation": "哭泣指因悲伤而低声流泪，符合想起去世奶奶的语境。"}, {"text": "大喊", "is_correct": false, "explanation": "搭配：“低声”与“大喊”意思相反，不能搭配。"}, {"text": "欢笑", "is_correct": false, "explanation": "语义：欢笑表示高兴，与想起去世亲人时的悲伤不符。"}, {"text": "咆哮", "is_correct": false, "explanation": "搭配：“低声”与“咆哮”矛盾，不能搭配。"}], "explanations": {"哭泣": "哭泣指因悲伤而低声流泪，符合想起去世奶奶的语境。", "大喊": "搭配：“低声”与“大喊”意思相反，不能搭配。", "欢笑": "语义：欢笑表示高兴，与想起去世亲人时的悲伤不符。", "咆哮": "搭配：“低声”与“咆哮”矛盾，不能搭配。"}, "sentence_index": 0, "correct_answer": "哭泣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在街上哭泣着，声音大得吓人。", "explanation": "这里应该用〈哭喊〉。哭泣指低声流泪地哭，声音很大的哭要说哭喊。"}, {"text": "她哭泣了一首老歌。", "explanation": "这里应该用〈唱〉。哭泣是不及物动词，不能带“一首老歌”作宾语。"}, {"text": "她看见新出的蛋糕，馋得哭泣起来。", "explanation": "这里应该用〈垂涎〉。哭泣表示因悲伤或痛苦而哭，见到美食的渴望要说垂涎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哭泣", "is_correct": true, "explanation": "哭泣指因悲伤而流泪，与“从不告诉别人”的隐忍语境相符。"}, {"text": "宣布", "is_correct": false, "explanation": "语义：宣布是公开说出，与“从不告诉别人”相反。"}, {"text": "宣扬", "is_correct": false, "explanation": "语义：宣扬是大肆张扬，与“从不告诉别人”的隐忍语境直接相反。"}, {"text": "公开", "is_correct": false, "explanation": "语义：公开就是让别人知道，与“从不告诉别人”相矛盾。"}], "explanations": {"哭泣": "哭泣指因悲伤而流泪，与“从不告诉别人”的隐忍语境相符。", "宣布": "语义：宣布是公开说出，与“从不告诉别人”相反。", "宣扬": "语义：宣扬是大肆张扬，与“从不告诉别人”的隐忍语境直接相反。", "公开": "语义：公开就是让别人知道，与“从不告诉别人”相矛盾。"}, "sentence_index": 6, "correct_answer": "哭泣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在办公室里哭泣了自己的委屈。", "explanation": "这里应该用〈哭诉〉。哭泣是不及物动词，不能带“委屈”作宾语；把委屈说给别人听要说哭诉。"}, {"text": "他弹钢琴弹得很哭泣。", "explanation": "这里应该用〈娴熟〉。哭泣表示因悲伤或痛苦而流泪，不能用来评价技艺。"}, {"text": "他哭泣了一封长信给朋友。", "explanation": "这里应该用〈写〉。哭泣是不及物动词，不能带“一封长信”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子在床上轻轻哭泣的。", "corrected_sentence": "孩子在床上轻轻哭泣着。", "error_description": "表示持续的状态要用“着”，应说“哭泣着”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一个人安静的哭泣。", "corrected_sentence": "她一个人安静地哭泣。", "error_description": "状语修饰动词“哭泣”时要用“地”，应说“安静地哭泣”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
