INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "街是城里两边有房子,人和车走的路。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕje˥", "syllable_count": 1, "sentences": [{"text": "这条街很长,两边都是房子。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街上有很多人和车。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家就在这条街上。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过这条街的时候,请看红绿灯。", "target_word": "街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上街上的车很少。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街没有大树,夏天很热。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在街上走,不要跑。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住的那条街很安静。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了,街上没有什么人。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街不宽,但是人和车都很多。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "街道", "label": "复合"}, {"form": "街头", "label": "复合"}, {"form": "大街", "label": "复合"}], "register": "中性", "sense_fingerprint": "街：城里两边有房子、人和车走的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89759, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：街，jiē，城里两边有房子、人和车走的路。"}, {"text": "节", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是节日。"}, {"text": "姐", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是姐姐。"}, {"text": "家", "is_correct": false, "explanation": "jiā 与 jiē 韵母不同，意思是家庭或家。"}], "explanations": {"街": "正确：街，jiē，城里两边有房子、人和车走的路。", "节": "jié 与 jiē 声调不同，意思是节日。", "姐": "jiě 与 jiē 声调不同，意思是姐姐。", "家": "jiā 与 jiē 韵母不同，意思是家庭或家。"}, "sentence_index": null, "correct_answer": "街"}, "level_3": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：“街”指城里两边有房子的路，与“两边都是房子”相符。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾不能两边都是房子。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子的量词是“张”，不说“这条桌子”。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：裙子不能两边都是房子。"}], "explanations": {"街": "正确：“街”指城里两边有房子的路，与“两边都是房子”相符。", "围巾": "语义：围巾不能两边都是房子。", "桌子": "搭配：桌子的量词是“张”，不说“这条桌子”。", "裙子": "语义：裙子不能两边都是房子。"}, "sentence_index": 0, "correct_answer": "街"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在海边的街上游泳。", "explanation": "这里应该用〈海滩〉。“街”指城里两边有房屋的道路，不能用来游泳；在海边游泳应说〈海滩〉。"}, {"text": "这条街上住着很多鱼。", "explanation": "这里应该用〈池塘〉。“街”是城里的道路，不是水域，鱼应住在〈池塘〉里，不能住在街上。"}, {"text": "这间屋子里有一条街，很暖和。", "explanation": "这里应该用〈房间〉。“街”是室外供车辆和行人通行的道路，不能指室内空间；屋子里的空间应说〈房间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89759, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：街，jiē，城里两边有房子、人和车走的路。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是界限。"}, {"text": "结", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是结合或打结。"}, {"text": "解", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是解开或理解。"}], "explanations": {"街": "正确：街，jiē，城里两边有房子、人和车走的路。", "界": "jiè 与 jiē 声调不同，意思是界限。", "结": "jié 与 jiē 声调不同，意思是结合或打结。", "解": "jiě 与 jiē 声调不同，意思是解开或理解。"}, "sentence_index": null, "correct_answer": "街"}, "level_3": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：“街”是孩子们走路的地方，与“在……上走”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不能在天空上走。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：人不能在墨水上走。"}, {"text": "字", "is_correct": false, "explanation": "配价：“走”要求能走的场所，字不是可以行走的地方。"}], "explanations": {"街": "正确：“街”是孩子们走路的地方，与“在……上走”相符。", "天空": "语义：人不能在天空上走。", "墨水": "语义：人不能在墨水上走。", "字": "配价：“走”要求能走的场所，字不是可以行走的地方。"}, "sentence_index": 6, "correct_answer": "街"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街的水很深，可以划船。", "explanation": "这里应该用〈河〉。“街”是城里两边有房屋的道路，不是河流，水深、能划船的地方应说〈河〉。"}, {"text": "这条街的泥土里长满了庄稼。", "explanation": "“街”是城里的路，不是耕地，不长庄稼。"}, {"text": "我是一条街，每天去上学。", "explanation": "这里应该用〈学生〉。“街”是城里的道路，不能指人；每天去上学的人应是〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家门口有一个街，很热闹。", "corrected_sentence": "我们家门口有一条街，很热闹。", "error_description": "量词错误：“街”的量词应为“条”，不能用“个”。正确说法是“一条街”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一座很宽的街。", "corrected_sentence": "这是一条很宽的街。", "error_description": "量词错误：“街”的量词应为“条”，“座”用于山、楼等。正确说法是“一条很宽的街”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
