INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城镇中两旁有房屋或商店的比较宽的道路。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕje˥", "syllable_count": 1, "sentences": [{"text": "这条街上有很多商店。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街两旁都是饭馆和商店。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们周末去那条街买衣服。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街的商店晚上十点才关门。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街上新开了一家咖啡店。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在街上的书店工作。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街的东西比商场便宜。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街的两边种着大树,还有很多小店。", "target_word": "街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条街很宽,两旁有不少店。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我常常和朋友在这条街吃饭。", "target_word": "街", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "街道", "label": "复合"}, {"form": "街头", "label": "复合"}, {"form": "大街", "label": "复合"}], "register": "中性", "sense_fingerprint": "街：城镇中两旁有商店的较宽道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：街，jiē，城镇中两旁有商店的比较宽的道路。"}, {"text": "节", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是节日。"}, {"text": "家", "is_correct": false, "explanation": "jiā 与 jiē 韵母不同，意思是家庭或商店的量词。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是界限。"}], "explanations": {"街": "正确：街，jiē，城镇中两旁有商店的比较宽的道路。", "节": "jié 与 jiē 声调不同，意思是节日。", "家": "jiā 与 jiē 韵母不同，意思是家庭或商店的量词。", "界": "jiè 与 jiē 声调不同，意思是界限。"}, "sentence_index": null, "correct_answer": "街"}, "level_3": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：“街”是有很多商店的道路，与“上有很多商店”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上不会有商店。"}, {"text": "树林", "is_correct": false, "explanation": "搭配：“树林”的量词是“片”或“座”，不说“这条树林”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”的量词是“本”，不说“这条书”。"}], "explanations": {"街": "正确：“街”是有很多商店的道路，与“上有很多商店”相符。", "天空": "语义：天空上不会有商店。", "树林": "搭配：“树林”的量词是“片”或“座”，不说“这条树林”。", "书": "搭配：“书”的量词是“本”，不说“这条书”。"}, "sentence_index": 0, "correct_answer": "街"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋大楼是一条街，有三十层。", "explanation": "这里应该用〈建筑〉。“街”指城镇中两旁有房屋或商店的道路，不能指楼房；大楼是〈建筑〉，不是道路。"}, {"text": "这条街是我家的房间，很大。", "explanation": "这里应该用〈屋子〉。“街”是城镇中两旁有商店的道路，不是室内空间；家里的空间应说〈屋子〉。"}, {"text": "这只猫的家是一条街，很小。", "explanation": "“街”是道路，不是猫的住所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89760, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：街，jiē，城镇中两旁有商店的比较宽的道路。"}, {"text": "姐", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是姐姐。"}, {"text": "解", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是解开或理解。"}, {"text": "结", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是结合或打结。"}], "explanations": {"街": "正确：街，jiē，城镇中两旁有商店的比较宽的道路。", "姐": "jiě 与 jiē 声调不同，意思是姐姐。", "解": "jiě 与 jiē 声调不同，意思是解开或理解。", "结": "jié 与 jiē 声调不同，意思是结合或打结。"}, "sentence_index": null, "correct_answer": "街"}, "level_3": {"options": [{"text": "街", "is_correct": true, "explanation": "正确：“街”指有商店的道路，与“东西比商场便宜”相符。"}, {"text": "河", "is_correct": false, "explanation": "语义：河里不会卖东西，河不能有“东西”比商场便宜。"}, {"text": "海", "is_correct": false, "explanation": "搭配：“海”的量词是“片”，不说“这条海”。"}, {"text": "山", "is_correct": false, "explanation": "搭配：“山”的量词是“座”，不说“这条山”。"}], "explanations": {"街": "正确：“街”指有商店的道路，与“东西比商场便宜”相符。", "河": "语义：河里不会卖东西，河不能有“东西”比商场便宜。", "海": "搭配：“海”的量词是“片”，不说“这条海”。", "山": "搭配：“山”的量词是“座”，不说“这条山”。"}, "sentence_index": 6, "correct_answer": "街"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街的作业很多。", "explanation": "这里应该用〈学校〉。“街”是城镇中两旁有商店的道路，不能有作业；作业多应指〈学校〉里的学习任务。"}, {"text": "我昨天在这条街的桌子上睡着了。", "explanation": "这里应该用〈房间〉。“街”是城镇中的道路，不是室内空间；人睡觉应在〈房间〉里，不能在街上的桌子上睡着。"}, {"text": "我的书包是一条街，很重。", "explanation": "“街”是城镇中的道路，不能指书包这样随身带的东西，所以不能说“我的书包是一条街”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个街的东西很便宜。", "corrected_sentence": "这条街的东西很便宜。", "error_description": "量词错误：“街”的量词应为“条”，不能用“个”。正确说法是“这条街”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那里有一个街，街上有很多商店。", "corrected_sentence": "那里有一条街，街上有很多商店。", "error_description": "量词错误：“街”的量词应为“条”，不能用“个”。正确说法是“一条街”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
