INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某项技艺或运动中全国水平最高的人。", "primary_collocate": null, "pronunciation": "guó shǒu", "ipa": "kuo˧˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是中国乒乓球队的国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位国手已经下了四十年围棋。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年轻时是有名的象棋国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国手也会输棋，所以每天还要练习。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小练游泳，后来成了国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者请那位国手谈谈比赛的经验。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位国手的球打得又快又准。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多孩子想像国手一样站在领奖台上。", "target_word": "国手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们市第一位进国家队的国手。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老国手每天教年轻人练发球。", "target_word": "国手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位国手", "label": "量词"}, {"form": "國手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国手：某项技艺或运动中全国水平最高的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国手", "is_correct": true, "explanation": "正确。国手指全国水平最高的运动员，与“中国乒乓球队”的身份相符。"}, {"text": "国王", "is_correct": false, "explanation": "语义：“国王”是君主，与“乒乓球队”的成员身份不符。"}, {"text": "球拍", "is_correct": false, "explanation": "搭配：“球拍”是器材，不能用“他是……的”指称一个人。"}, {"text": "宰相", "is_correct": false, "explanation": "语义：“宰相”是古代的官职，与现代乒乓球队无关。"}], "explanations": {"国手": "正确。国手指全国水平最高的运动员，与“中国乒乓球队”的身份相符。", "国王": "语义：“国王”是君主，与“乒乓球队”的成员身份不符。", "球拍": "搭配：“球拍”是器材，不能用“他是……的”指称一个人。", "宰相": "语义：“宰相”是古代的官职，与现代乒乓球队无关。"}, "sentence_index": 0, "correct_answer": "国手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是个国手，上个月才第一次拿起球拍。", "explanation": "这里应该用〈新手〉。国手指全国水平最高的人，上个月才第一次拿球拍的人应说“新手”。"}, {"text": "这个国手很贵，我们买不起。", "explanation": "这里应该用〈名牌〉。国手指人，不能用来指商品；形容名贵的东西应说“名牌”。"}, {"text": "他是这场比赛的国手，负责吹哨判罚。", "explanation": "这里应该用〈裁判〉。国手指全国水平最高的运动员，负责吹哨判罚的人是裁判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国手", "is_correct": true, "explanation": "正确。国手是全国水平的运动员，与“球打得又快又准”的描述相符。"}, {"text": "画家", "is_correct": false, "explanation": "语义：“画家”以画画为业，与“打球”的技能不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”以做饭为业，与“球打得又快又准”毫不相干。"}, {"text": "球拍", "is_correct": false, "explanation": "搭配：“球拍”是器材，不能用量词“位”，也不能说“球拍的球打得又快又准”。"}], "explanations": {"国手": "正确。国手是全国水平的运动员，与“球打得又快又准”的描述相符。", "画家": "语义：“画家”以画画为业，与“打球”的技能不符。", "厨师": "语义：“厨师”以做饭为业，与“球打得又快又准”毫不相干。", "球拍": "搭配：“球拍”是器材，不能用量词“位”，也不能说“球拍的球打得又快又准”。"}, "sentence_index": 6, "correct_answer": "国手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个国手，每天给病人看病。", "explanation": "这里应该用〈医生〉。国手指全国水平最高的运动员或技艺高手，给病人看病是医生的工作。"}, {"text": "他是这场比赛的国手，买票进场，坐在看台上。", "explanation": "这里应该用〈观众〉。国手指参赛的顶尖高手，买票坐在看台上的是观众。"}, {"text": "他是个国手，才学了三天的棋。", "explanation": "这里应该用〈新手〉。国手指全国水平最高的人，学了三天的棋应说“新手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只国手今天要参加决赛。", "corrected_sentence": "这位国手今天要参加决赛。", "error_description": "错误：量词“只”。“国手”指人，应用量词“位”（或“名”），说“这位国手”；“只”通常用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张老国手每天都来训练场。", "corrected_sentence": "这位老国手每天都来训练场。", "error_description": "错误：量词“张”。“国手”指人，应用量词“位”，说“这位老国手”；“张”用于平面的东西，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
