INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89763, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里最重要的人。", "primary_collocate": null, "pronunciation": "zhǔ jué", "ipa": "tʂu˨˩ tɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书的主角是一个老人。", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事的主角叫小明，他很爱读书。", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个故事里，谁是主角？", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "童话里的主角常常是小动物。", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说的主角最后回到了家乡。", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我读的故事里，主角总是很聪明。", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己想成故事里的主角。", "target_word": "主角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者把一只猫写成了故事的主角。", "target_word": "主角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的主角不是人，是一棵树。", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事的主角后来怎么样了？", "target_word": "主角", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个主角", "label": "量词"}, {"form": "男主角", "label": "复合"}, {"form": "女主角", "label": "复合"}], "register": "中性", "sense_fingerprint": "小说、童话、故事里最重要的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89763, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主角", "is_correct": true, "explanation": "主角指故事中最重要的人物，符合句意。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价指买票的钱，不能是书里的人。"}, {"text": "片长", "is_correct": false, "explanation": "语义：片长指影片的时长，不能说“是一个老人”。"}, {"text": "镜头", "is_correct": false, "explanation": "搭配：镜头可以“拍”，但不能说“是一个老人”。"}], "explanations": {"主角": "主角指故事中最重要的人物，符合句意。", "票价": "语义：票价指买票的钱，不能是书里的人。", "片长": "语义：片长指影片的时长，不能说“是一个老人”。", "镜头": "搭配：镜头可以“拍”，但不能说“是一个老人”。"}, "sentence_index": 0, "correct_answer": "主角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个故事里他只是个主角，出场很少。", "explanation": "这里应该用〈配角〉。主角是故事里最重要的人物，出场很少的人不能叫主角。"}, {"text": "那个主角只在故事里出现了一次。", "explanation": "这里应该用〈龙套〉。主角是故事中最重要的人物，不会只出现一次。"}, {"text": "这个故事的主角是一次意外的旅行。", "explanation": "这里应该用〈情节〉。主角指故事中的人物，“一次意外的旅行”是情节，不能说主角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主角", "is_correct": true, "explanation": "主角指故事中最重要的人物，与“想成”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能被“想成”。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“想成”后接人物或身份，“座位”不能这样用。"}, {"text": "台词", "is_correct": false, "explanation": "语义：台词是角色说的话，不是角色本身。"}], "explanations": {"主角": "主角指故事中最重要的人物，与“想成”搭配，符合句意。", "天气": "语义：天气不是人，不能被“想成”。", "座位": "搭配：“想成”后接人物或身份，“座位”不能这样用。", "台词": "语义：台词是角色说的话，不是角色本身。"}, "sentence_index": 6, "correct_answer": "主角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的主角是三十块钱。", "explanation": "这里应该用〈价格〉。主角是故事里最重要的人物，书卖多少钱是价格，不是主角。"}, {"text": "这个故事的主角是：做人要诚实。", "explanation": "这里应该用〈主题〉。主角是故事里的人物，“做人要诚实”是故事想说的道理，是主题。"}, {"text": "这个故事的主角在一个小山村里。", "explanation": "这里应该用〈地方〉。主角是故事里的人物，小山村是故事发生的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "故事里有一只主角，是个聪明的小男孩。", "corrected_sentence": "故事里有一个主角，是个聪明的小男孩。", "error_description": "“主角”指人时，量词要用“个”，不能用“只”。错误：一只主角；正确：一个主角。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作者写过一个勇敢地主角，他救了很多人。", "corrected_sentence": "作者写过一个勇敢的主角，他救了很多人。", "error_description": "修饰名词要用“的”，不用“地”（“地”多用于动词、形容词作状语）。错误：勇敢地主角；正确：勇敢的主角。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
