INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89765, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身边是紧靠着自己的地方。", "primary_collocate": null, "pronunciation": "shēn biān", "ipa": "ʂən˥ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "她总把药带在身边。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门时，我身边只有一个包。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的身边总有孙子陪着。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就在父母身边长大。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我身边坐着一位年轻的老师。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围在老师身边唱歌。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在你身边，我觉得很安心。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把伞放在身边，下雨就能用。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都站在新娘身边照相。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在床边坐着，身边放着一杯热水。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "紧靠着自己的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身边", "is_correct": true, "explanation": "身边：紧靠自己身体的旁边，与“带在……”的语境相符。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天上不是可以把药随身带着的地方，句子读来不通。"}, {"text": "嘴里", "is_correct": false, "explanation": "搭配：“带在嘴里”指含在口中，不搭配“随身带着药”的意思。"}, {"text": "年底", "is_correct": false, "explanation": "语义：年底是时间，不是处所，不能用“带在……”来说。"}], "explanations": {"身边": "身边：紧靠自己身体的旁边，与“带在……”的语境相符。", "天上": "语义：天上不是可以把药随身带着的地方，句子读来不通。", "嘴里": "搭配：“带在嘴里”指含在口中，不搭配“随身带着药”的意思。", "年底": "语义：年底是时间，不是处所，不能用“带在……”来说。"}, "sentence_index": 0, "correct_answer": "身边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车站身边有一家饭店。", "explanation": "这里应该用〈附近〉。身边指身体或人身旁的近处，不指车站这类场所，应说“车站附近”。"}, {"text": "银行身边有一个公园。", "explanation": "这里应该用〈旁边〉。身边指人身旁或随身物品的近处，不用来指银行这类建筑旁的位置，应说“银行旁边”。"}, {"text": "河的身边种着一排柳树。", "explanation": "这里应该用〈岸边〉。身边指紧靠人身或随身物品的近处，不用来指河这类大片地方，应说“河岸边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身边", "is_correct": true, "explanation": "身边：紧靠自己身旁，与“在你……，我觉得很安心”的语境相符。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码不是处所，“在你页码”读来不通。"}, {"text": "纸上", "is_correct": false, "explanation": "语义：纸是平面，人不能让人安心地待在纸上，句子读来不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是处所，“在你课本，我觉得很安心”读来不通。"}], "explanations": {"身边": "身边：紧靠自己身旁，与“在你……，我觉得很安心”的语境相符。", "页码": "语义：页码不是处所，“在你页码”读来不通。", "纸上": "语义：纸是平面，人不能让人安心地待在纸上，句子读来不通。", "课本": "语义：课本是书，不是处所，“在你课本，我觉得很安心”读来不通。"}, "sentence_index": 6, "correct_answer": "身边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "操场身边有一圈树。", "explanation": "这里应该用〈周围〉。身边只指人或随身物品的周围，不指操场这样的大范围地方，应说“操场周围”。"}, {"text": "这个城市的身边都是山。", "explanation": "这里应该用〈四周〉。身边指紧靠人或物的近处，不用来指城市这样的大范围地方，应说“城市的四周”。"}, {"text": "教室身边有一块黑板。", "explanation": "这里应该用〈前面〉。身边指人身旁的近处，不指教室这类场所的方位，应说“教室前面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫跑了妈妈身边。", "corrected_sentence": "小猫跑到了妈妈身边。", "error_description": "“跑”后要用补语“到”引出处所，应为“跑到了妈妈身边”；漏掉“到”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候住奶奶身边。", "corrected_sentence": "他小时候住在奶奶身边。", "error_description": "“住”表示居住，要用介词“在”引出处所，应为“住在奶奶身边”；漏掉“在”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
