INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体的旁边;自己周围。", "primary_collocate": null, "pronunciation": "shēn biān", "ipa": "ʂən˥ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "妈妈坐在我身边看电视。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子跑到爸爸身边，抱住了他。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身边没有一个朋友。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的身边有很多好人。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把手机放在身边。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一直躺在老人身边。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你留在我身边，好吗？", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身边的同学都在认真写字。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过来，坐到了我身边。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小鸟飞到了我身边。", "target_word": "身边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己身体的旁边或周围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身边", "is_correct": true, "explanation": "身边：紧靠自己身体的旁边，与“坐在我……看电视”相符。"}, {"text": "水里", "is_correct": false, "explanation": "语义：水里不是可以坐着看电视的地方，句子读来不通。"}, {"text": "膝下", "is_correct": false, "explanation": "语域：膝下偏书面，多见于“承欢膝下”，在这句日常口语中显得生硬，且不指坐的位置。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是可以让人坐在旁边的处所，与“坐在……看电视”不合。"}], "explanations": {"身边": "身边：紧靠自己身体的旁边，与“坐在我……看电视”相符。", "水里": "语义：水里不是可以坐着看电视的地方，句子读来不通。", "膝下": "语域：膝下偏书面，多见于“承欢膝下”，在这句日常口语中显得生硬，且不指坐的位置。", "名字": "语义：名字不是可以让人坐在旁边的处所，与“坐在……看电视”不合。"}, "sentence_index": 0, "correct_answer": "身边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校身边有一家书店。", "explanation": "这里应该用〈旁边〉。身边指人身旁或随身物品的周围，不用来指学校这类地点，应说“学校旁边”。"}, {"text": "我家身边有一个公园。", "explanation": "这里应该用〈附近〉。身边只指身体或人身旁的近处，不指较大范围，应说“我家附近”。"}, {"text": "昨天身边下了一场大雨。", "explanation": "这里不能用“身边”。身边指空间位置，不能修饰时间，应说“昨天下了一场大雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身边", "is_correct": true, "explanation": "身边：紧靠自己身旁，符合“请你留在我……”的陪伴语境。"}, {"text": "体内", "is_correct": false, "explanation": "语义：体内指身体里面，“留在我体内”与请人陪伴的语境不合。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的东西，“请你留在我钱包”与请人陪伴的语境不合。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本不是可以让人停留陪伴的地方，句子读来不通。"}], "explanations": {"身边": "身边：紧靠自己身旁，符合“请你留在我……”的陪伴语境。", "体内": "语义：体内指身体里面，“留在我体内”与请人陪伴的语境不合。", "钱包": "语义：钱包是装钱的东西，“请你留在我钱包”与请人陪伴的语境不合。", "账本": "语义：账本不是可以让人停留陪伴的地方，句子读来不通。"}, "sentence_index": 6, "correct_answer": "身边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村子身边有很多大树。", "explanation": "这里应该用〈周围〉。身边只指人或随身物品的周围，不指村子这样的大范围地方，应说“村子周围”。"}, {"text": "路的身边种着一排树。", "explanation": "这里应该用〈一边〉。身边不用来指路的一侧，应说“路的一边”。"}, {"text": "湖的身边有很多树。", "explanation": "这里应该用〈四周〉。身边指人身旁的近处，不指湖这样的大片区域，应说“湖的四周”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他慢慢走了我身边。", "corrected_sentence": "他慢慢走到了我身边。", "error_description": "“走”后要用补语“到”引出处所，应为“走到了我身边”；漏掉“到”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候住奶奶身边。", "corrected_sentence": "他小时候住在奶奶身边。", "error_description": "“住”表示居住，要用介词“在”引出处所，应为“住在奶奶身边”；漏掉“在”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
