INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地黄是一种草，它的根可以做药。", "primary_collocate": null, "pronunciation": "dì huáng", "ipa": "ti˥˩ xwɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "地黄是一种草。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这棵地黄开花了。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地黄的根可以做药。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶在山边找到了地黄。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用地黄给他治病。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地黄的花是红紫色的，很好看。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在院子里种了一些地黄。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药店里卖的地黄是干的。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天，地黄的叶子长得很快。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，这种草叫地黄，根可以做药。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "生地黄", "label": "复合"}, {"form": "熟地黄", "label": "复合"}], "register": "中性", "sense_fingerprint": "一种草，根可以做药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地黄", "is_correct": true, "explanation": "正确：地黄是一种草，与句中“一种草”一致。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是草。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是草。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高度，不能说是一种草。"}], "explanations": {"地黄": "正确：地黄是一种草，与句中“一种草”一致。", "老虎": "语义：老虎是动物，不是草。", "桌子": "语义：桌子是家具，不是草。", "身高": "体貌：“身高”指人的高度，不能说是一种草。"}, "sentence_index": 0, "correct_answer": "地黄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭后我常吃些地黄，当作水果。", "explanation": "这里应该用〈苹果〉。地黄是药材，不是水果，不能当作水果来吃。"}, {"text": "妈妈用地黄炒了一盘菜。", "explanation": "这里应该用〈白菜〉。地黄是药材，不是蔬菜，不能用来炒菜。"}, {"text": "妈妈用地黄给我做了一件新衣服。", "explanation": "这里应该用〈布〉。地黄是一种草药，不是布料，不能用来做衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地黄", "is_correct": true, "explanation": "正确：“种”用于植物，地黄是可以种的草药，句意合理。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能种，不能说“种了一些石头”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是植物，不能种。"}, {"text": "鸡", "is_correct": false, "explanation": "搭配：“种”用于植物，养鸡应说“养”，不说“种”。"}], "explanations": {"地黄": "正确：“种”用于植物，地黄是可以种的草药，句意合理。", "石头": "语义：石头不能种，不能说“种了一些石头”。", "电脑": "语义：电脑不是植物，不能种。", "鸡": "搭配：“种”用于植物，养鸡应说“养”，不说“种”。"}, "sentence_index": 6, "correct_answer": "地黄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在音乐会上弹起了地黄，大家都很惊讶。", "explanation": "这里应该用〈琵琶〉。地黄是草药，不是乐器，不能用“弹”来演奏。"}, {"text": "他用地黄把门钉牢了。", "explanation": "这里应该用〈钉子〉。地黄是草药，不是工具，不能用来钉门。"}, {"text": "我们在地黄的树荫下吃了午饭。", "explanation": "这里应该用〈大树〉。地黄是草本植物，长不成高大的树，不能用来遮阴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶年轻时过种地黄。", "corrected_sentence": "奶奶年轻时种过地黄。", "error_description": "体标位置错误：“过”应紧跟动词，应说“种过地黄”，不能说“过种地黄”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落里有一只地黄，叶子很绿。", "corrected_sentence": "院子角落里有一棵地黄，叶子很绿。", "error_description": "量词错误：地黄是植物，应用量词“棵”，“只”多用于动物，不能用来数植物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
