INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "多年生草本植物，根茎可入药。", "primary_collocate": null, "pronunciation": "dì huáng", "ipa": "ti˥˩ xwɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "地黄是多年生的草。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地黄的根茎可以入药。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山坡上长着很多地黄。", "target_word": "地黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在地里种地黄。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地黄的叶子上有很多小毛。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老中医常用地黄来配药。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每年秋天，农民都会挖地黄的根。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地黄开出的花像小铃铛。", "target_word": "地黄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在书里看过地黄的图片。", "target_word": "地黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物叫地黄，春天开花。", "target_word": "地黄", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "生地黄", "label": "复合"}, {"form": "熟地黄", "label": "复合"}], "register": "中性", "sense_fingerprint": "多年生草本植物，根茎可入药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地黄", "is_correct": true, "explanation": "正确：地黄是多年生草本植物，符合句意。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不是草。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是草。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：“面孔”指人的脸，不能说是草。"}], "explanations": {"地黄": "正确：地黄是多年生草本植物，符合句意。", "小猫": "语义：小猫是动物，不是草。", "冰箱": "语义：冰箱是家电，不是草。", "面孔": "体貌：“面孔”指人的脸，不能说是草。"}, "sentence_index": 0, "correct_answer": "地黄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天我喜欢吃地黄，很爽口。", "explanation": "这里应该用〈黄瓜〉。地黄是药材，不能生吃当蔬菜，也不爽口。"}, {"text": "妈妈用地黄炒肉，很好吃。", "explanation": "这里应该用〈芹菜〉。地黄是药材，不是蔬菜，不能用来炒肉。"}, {"text": "他骑着地黄去上班。", "explanation": "这里应该用〈自行车〉。地黄是草药，不是交通工具，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地黄", "is_correct": true, "explanation": "正确：地黄有根，可以挖出根来入药，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流没有根，不能挖它的根。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋没有根，不能说挖鸡蛋的根。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“挖”多用于挖土里的东西，鱼应说“捕”或“钓”。"}], "explanations": {"地黄": "正确：地黄有根，可以挖出根来入药，符合句意。", "河流": "语义：河流没有根，不能挖它的根。", "鸡蛋": "语义：鸡蛋没有根，不能说挖鸡蛋的根。", "鱼": "搭配：“挖”多用于挖土里的东西，鱼应说“捕”或“钓”。"}, "sentence_index": 6, "correct_answer": "地黄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们用地黄盖了一间小房子。", "explanation": "这里应该用〈木头〉。地黄是草药，不能用来盖房子。"}, {"text": "他从钱包里拿出一张地黄，买了一瓶水。", "explanation": "这里应该用〈钞票〉。地黄是草药，不是钱，不能用来买东西。"}, {"text": "他每天对着地黄打电话，聊得很开心。", "explanation": "这里应该用〈手机〉。地黄是草药，不能当电话用来打电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上长着一头地黄，开着紫红色的花。", "corrected_sentence": "山坡上长着一片地黄，开着紫红色的花。", "error_description": "量词错误：成片生长的地黄应用量词“片”，“头”多用于牛、猪等大牲畜，不能用来数植物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时过挖地黄。", "corrected_sentence": "他年轻时挖过地黄。", "error_description": "体标位置错误：“过”应紧跟动词，应说“挖过地黄”，不能说“过挖地黄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
