INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89769, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人好，不让人受苦。", "primary_collocate": null, "pronunciation": "rén dào", "ipa": "ʐən˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这样对待病人很不人道。", "target_word": "人道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生用人道的方法照顾老人。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把小动物关在小笼子里不人道。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂让工人每天干十六个小时，太不人道了。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这样处理问题很人道。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律要求人道地对待每一个犯人。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法既安全又人道。", "target_word": "人道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "给病人用药，减少他们的痛苦，这很人道。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，那家医院的做法很人道。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对待动物，我们也应该人道一点儿。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人道主义", "label": "复合"}], "register": "书面", "sense_fingerprint": "人道：对人好，不让人受苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人道", "is_correct": true, "explanation": "正确。“人道”形容对待方式不让人受苦，与“很不”搭配，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌，不能形容“对待病人”的方式。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”形容排列或整洁，与“对待病人”不相干。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或气氛，不能说“对待病人很不甜蜜”。"}], "explanations": {"人道": "正确。“人道”形容对待方式不让人受苦，与“很不”搭配，符合句意。", "漂亮": "语义：“漂亮”形容外貌，不能形容“对待病人”的方式。", "整齐": "语义：“整齐”形容排列或整洁，与“对待病人”不相干。", "甜蜜": "搭配：“甜蜜”形容感情或气氛，不能说“对待病人很不甜蜜”。"}, "sentence_index": 0, "correct_answer": "人道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张沙发很人道，坐上去特别软。", "explanation": "这里应该用〈舒服〉。人道不用于形容家具，形容沙发的坐感应说“舒服”。"}, {"text": "这份考卷很人道，题目一点儿也不难。", "explanation": "这里应该用〈简单〉。人道不用于形容考卷，形容题目的难易应说“简单”。"}, {"text": "今天的天气很人道，不冷也不热。", "explanation": "这里应该用〈宜人〉。人道不用于形容天气，形容天气舒适应说“宜人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人道", "is_correct": true, "explanation": "正确。“既安全又人道”表示办法既不伤害人，又不让人受苦。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能形容办法。"}, {"text": "暖", "is_correct": false, "explanation": "语义：“暖”形容温度，不能形容办法。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容质地，不与“办法”搭配。"}], "explanations": {"人道": "正确。“既安全又人道”表示办法既不伤害人，又不让人受苦。", "甜": "语义：“甜”形容味道，不能形容办法。", "暖": "语义：“暖”形容温度，不能形容办法。", "脆": "搭配：“脆”形容质地，不与“办法”搭配。"}, "sentence_index": 6, "correct_answer": "人道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很人道，从不炫耀自己的成绩。", "explanation": "这里应该用〈谦虚〉。人道指对待别人不让人受苦，不炫耀应说“谦虚”。"}, {"text": "孩子们见了长辈很人道，都会问好。", "explanation": "这里应该用〈礼貌〉。人道形容对待别人的态度，见长辈问好应说“礼貌”。"}, {"text": "他做事很人道，从不浪费电。", "explanation": "这里应该用〈节约〉。人道不用于形容节省资源，应说“节约”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样对待病人太不人道地了。", "corrected_sentence": "这样对待病人太不人道了。", "error_description": "错误：多了“地”。“人道”在这里作谓语，“地”只用在修饰动词的状语后，应去掉“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法很人道地，大家都愿意试一试。", "corrected_sentence": "这个办法很人道，大家都愿意试一试。", "error_description": "错误：“很人道”已作谓语，“地”只能用在动词前，不能加在这里。应去掉“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
