INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89770, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "尊重人的生命与尊严；富有同情心的。", "primary_collocate": null, "pronunciation": "rén dào", "ipa": "ʐən˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他是一个很人道的老板，从不骂工人。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "尊重每个人是一种人道的态度。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院人道地对待每一位病人，不管穷人还是富人。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的法律很人道，不会伤害无辜的人。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在战争中，也要人道地照顾受伤的人。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把人当成人来看，这才是人道的做法。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很人道，总是先想到别人的难处。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的做法很人道，没有批评那个哭了的孩子。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管犯了什么错，都应该得到人道的对待。", "target_word": "人道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不人道的做法让大家很生气。", "target_word": "人道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人道主义", "label": "复合"}], "register": "书面", "sense_fingerprint": "人道：尊重人的生命与尊严，富有同情心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人道", "is_correct": true, "explanation": "正确。“人道”形容老板待人有同情心，与“从不骂工人”相符。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”指凶狠、不讲理，与“从不骂工人”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材，不用来形容老板的性格，句意不通。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容环境或声音，不用来形容老板的性格。"}], "explanations": {"人道": "正确。“人道”形容老板待人有同情心，与“从不骂工人”相符。", "粗暴": "语义：“粗暴”指凶狠、不讲理，与“从不骂工人”矛盾。", "高大": "语义：“高大”形容身材，不用来形容老板的性格，句意不通。", "吵闹": "搭配：“吵闹”形容环境或声音，不用来形容老板的性格。"}, "sentence_index": 0, "correct_answer": "人道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做饭很人道，每道菜都要尝一尝。", "explanation": "这里应该用〈细心〉。人道指对人不残忍、不让人受苦，形容做饭的认真应说“细心”。"}, {"text": "这台机器很人道，每天都运转二十四小时。", "explanation": "这里应该用〈高效〉。人道不用于形容机器，形容机器的效率应说“高效”。"}, {"text": "他很人道，每天都练习到深夜。", "explanation": "这里应该用〈勤奋〉。人道不用于描写学习的刻苦，应说“勤奋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人道", "is_correct": true, "explanation": "正确。“人道”形容性格有同情心，与“先想到别人的难处”相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指对人漠不关心，与“先想到别人的难处”矛盾。"}, {"text": "自私", "is_correct": false, "explanation": "语义：“自私”指只顾自己，与“先想到别人的难处”矛盾。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”形容身体，一般不用来形容性格。"}], "explanations": {"人道": "正确。“人道”形容性格有同情心，与“先想到别人的难处”相符。", "冷淡": "语义：“冷淡”指对人漠不关心，与“先想到别人的难处”矛盾。", "自私": "语义：“自私”指只顾自己，与“先想到别人的难处”矛盾。", "健康": "搭配：“健康”形容身体，一般不用来形容性格。"}, "sentence_index": 6, "correct_answer": "人道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人讲故事很人道，孩子们都笑了。", "explanation": "这里应该用〈幽默〉。人道指对待别人有同情心，讲故事使人发笑应说“幽默”。"}, {"text": "他做人很人道，从不说谎。", "explanation": "这里应该用〈诚实〉。人道形容对待他人不让人受苦，不说谎应说“诚实”。"}, {"text": "这件衣服很人道，颜色也很淡。", "explanation": "这里应该用〈朴素〉。人道不用于形容衣服，衣着简单、颜色素淡应说“朴素”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察应该人道的对待每位市民。", "corrected_sentence": "警察应该人道地对待每位市民。", "error_description": "错误：“的”误用。“人道”修饰动词“对待”作状语，应用“地”，说“人道地对待”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们这样做太不人道地了，大家都不满意。", "corrected_sentence": "他们这样做太不人道了，大家都不满意。", "error_description": "错误：多了“地”。“人道”在这里作谓语，不能加“地”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
