INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89771, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到是在路上或做事时碰上了。", "primary_collocate": null, "pronunciation": "yù dào", "ipa": "y˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在路上遇到了老同学。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在超市遇到一个朋友。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班时在电梯里遇到了邻居。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在车站遇到她了吗？", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天在门口遇到王老师。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走路时遇到熟人，要打招呼。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在公园里遇到了一只小狗。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少在这里遇到中国人。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车回家，在加油站遇到了老朋友。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在饭店门口遇到了经理。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇到了", "label": "体标"}, {"form": "遇到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "在路上或做事时碰上人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遇到", "is_correct": true, "explanation": "正确。「遇到」表示在路上碰上人，这里说在路上碰上老同学。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」的对象是饮品，「在路上喝了老同学」句意不通。"}, {"text": "投诉", "is_correct": false, "explanation": "语义：「投诉」是向有关部门反映问题，与「在路上」遇见老同学不合。"}, {"text": "修", "is_correct": false, "explanation": "搭配：「修」一般不带「老同学」这样的人作宾语，「修了老同学」搭配不通。"}], "explanations": {"遇到": "正确。「遇到」表示在路上碰上人，这里说在路上碰上老同学。", "喝": "语义：「喝」的对象是饮品，「在路上喝了老同学」句意不通。", "投诉": "语义：「投诉」是向有关部门反映问题，与「在路上」遇见老同学不合。", "修": "搭配：「修」一般不带「老同学」这样的人作宾语，「修了老同学」搭配不通。"}, "sentence_index": 0, "correct_answer": "遇到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和她约好明天在车站遇到。", "explanation": "这里应该用〈见面〉。「遇到」强调偶然碰上，事先约好的会面要用「见面」。"}, {"text": "我这学期终于遇到了奖学金。", "explanation": "这里应该用〈拿到〉。「遇到」指偶然碰上人或事，取得奖学金要说「拿到」。"}, {"text": "我在这家公司终于遇到了一份工作。", "explanation": "这里应该用〈找到〉。「遇到」指偶然碰上人或事，经过努力得到工作要说「找到」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遇到", "is_correct": true, "explanation": "正确。「遇到」表示偶然碰上，这里说孩子在公园里碰上一只小狗。"}, {"text": "制造", "is_correct": false, "explanation": "语义：「制造」是人为做出某物，「孩子在公园里制造了一只小狗」与句意不符。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」的对象一般是文字，不能用于动物，「写了一只小狗」句意不通。"}, {"text": "读", "is_correct": false, "explanation": "语义：「读」的对象是文字或书，「读了一只小狗」句意不通。"}], "explanations": {"遇到": "正确。「遇到」表示偶然碰上，这里说孩子在公园里碰上一只小狗。", "制造": "语义：「制造」是人为做出某物，「孩子在公园里制造了一只小狗」与句意不符。", "写": "语义：「写」的对象一般是文字，不能用于动物，「写了一只小狗」句意不通。", "读": "语义：「读」的对象是文字或书，「读了一只小狗」句意不通。"}, "sentence_index": 6, "correct_answer": "遇到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理每天在饭店门口遇到计划。", "explanation": "这里应该用〈制定〉。「遇到」指偶然碰上人或事，计划要说「制定」或「执行」。"}, {"text": "我们在饭店门口遇到了一顿饭。", "explanation": "语义错误：「遇到」不能指吃饭，这里应说「吃了一顿饭」。"}, {"text": "我们在饭店门口遇到了一个星期。", "explanation": "这里应该用〈待〉。「遇到」指碰上人或事，不能表示停留的时长，停留一个星期要说「待了一个星期」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前在路上遇到了过老同学。", "corrected_sentence": "我以前在路上遇到过老同学。", "error_description": "「了」和「过」不能同时用在「遇到」后面。表示经历要说「遇到过」，不能加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天在路上遇到着老同学。", "corrected_sentence": "我今天在路上遇到了老同学。", "error_description": "「着」用错了。「遇到」表示已经发生的事要用「了」，不能用「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
