INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "碰上;遭遇。", "primary_collocate": null, "pronunciation": "yù dào", "ipa": "y˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "做事难免遇到问题。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作中遇到了很多困难。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难，要先想办法。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学汉语时遇到过不少麻烦。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里遇到了危险。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司最近遇到了大问题。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你遇到什么问题，可以问我。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次做饭就遇到了麻烦。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到事情，不要太着急。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城遇到过一次大水。", "target_word": "遇到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇到了", "label": "体标"}, {"form": "遇到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "碰上困难、问题等，遭遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遇到", "is_correct": true, "explanation": "正确。「遇到」表示碰上问题或困难，这里说做事难免碰上问题。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」的对象是饮品，「做事难免喝问题」句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能与「问题」搭配，「做事难免吃问题」句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」一般用于物品，「修理问题」搭配不通。"}], "explanations": {"遇到": "正确。「遇到」表示碰上问题或困难，这里说做事难免碰上问题。", "喝": "语义：「喝」的对象是饮品，「做事难免喝问题」句意不通。", "吃": "搭配：「吃」不能与「问题」搭配，「做事难免吃问题」句意不通。", "修理": "搭配：「修理」一般用于物品，「修理问题」搭配不通。"}, "sentence_index": 0, "correct_answer": "遇到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我学汉语时遇到了不少快乐。", "explanation": "这里应该用〈感到〉。「遇到」指碰上问题或困难，感受到的情绪要说「感到」。"}, {"text": "我学汉语时遇到过很多证书。", "explanation": "这里应该用〈拿到〉。「遇到」指碰上问题或麻烦，取得证书要说「拿到」。"}, {"text": "我学汉语时遇到过不少学习。", "explanation": "这里应该用〈进行〉。「遇到」指碰上问题或麻烦，学习要说「进行」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遇到", "is_correct": true, "explanation": "正确。「遇到」表示碰上问题，这里说你碰上什么问题可以问我。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」是创造新事物，「发明什么问题」句意不通。"}, {"text": "创造", "is_correct": false, "explanation": "语义：「创造」指制造出新的事物，与「问题」这种已经存在的情况不合。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：「打扮」用于人或物的外表，「打扮什么问题」搭配不通。"}], "explanations": {"遇到": "正确。「遇到」表示碰上问题，这里说你碰上什么问题可以问我。", "发明": "语义：「发明」是创造新事物，「发明什么问题」句意不通。", "创造": "语义：「创造」指制造出新的事物，与「问题」这种已经存在的情况不合。", "打扮": "搭配：「打扮」用于人或物的外表，「打扮什么问题」搭配不通。"}, "sentence_index": 6, "correct_answer": "遇到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小城遇到过一次热闹的庆祝。", "explanation": "这里应该用〈举行〉。「遇到」指碰上问题或事情，庆祝活动一般要说「举行」。"}, {"text": "这个小城遇到过一双大眼睛。", "explanation": "这里应该用〈有〉。「遇到」指碰上人或事，说事物具有某种特征要用「有」。"}, {"text": "这个小城遇到过一次很大的笑。", "explanation": "这里应该用〈发出〉。「遇到」指碰上人或事，发出笑声要说「发出」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作中难免遇到着问题。", "corrected_sentence": "工作中难免遇到问题。", "error_description": "「着」用错了。「遇到」表示碰上问题时不能加「着」，应说「难免遇到问题」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚学汉语时不遇到过麻烦。", "corrected_sentence": "我刚学汉语时没遇到过麻烦。", "error_description": "否定「过」表示的经历要用「没」，应说「没遇到过」，不能说「不遇到过」。错误形式：「不遇到过」；正确形式：「没遇到过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
