INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89773, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "就是，说明这个人或东西是什么。", "primary_collocate": null, "pronunciation": "biàn shì", "ipa": "pjɛn˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "站在门口的那位便是我的老师。", "target_word": "便是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面那座白色的楼便是我们学校。", "target_word": "便是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这便是我住了五年的家。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要找的人便是他。", "target_word": "便是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌上那本红色封面的书便是我的。", "target_word": "便是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个穿蓝衣服的便是新来的同学。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河对面那片绿色便是我们的果园。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他手里拿的便是昨天丢的手机。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最左边那个孩子便是我弟弟。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外传来的声音便是雨声。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "便是：书面的“就是”，用来指出某个人或东西到底是什么，常见于“……的便是……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89773, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "便是", "is_correct": true, "explanation": "便是（biàn shì）：正确答案，书面语中指“就是”。"}, {"text": "面试", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是面试。"}, {"text": "办事", "is_correct": false, "explanation": "bàn 与 biàn 相比少了介音 i，意思是办事。"}, {"text": "辨识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是辨识。"}], "explanations": {"便是": "便是（biàn shì）：正确答案，书面语中指“就是”。", "面试": "miàn 与 biàn 声母不同（m 与 b），意思是面试。", "办事": "bàn 与 biàn 相比少了介音 i，意思是办事。", "辨识": "shí（第二声）与 shì（第四声）声调不同，意思是辨识。"}, "sentence_index": null, "correct_answer": "便是"}, "level_3": {"options": [{"text": "便是", "is_correct": true, "explanation": "便是：就是，指出站在门口的那位就是我的老师。"}, {"text": "在", "is_correct": false, "explanation": "配价：“在”后面要接处所，不能直接接“我的老师”。"}, {"text": "叫", "is_correct": false, "explanation": "语义：“叫”表示称呼，不能用来判定“那位就是我的老师”。"}, {"text": "来", "is_correct": false, "explanation": "语义：“来”表示到来，“那位来我的老师”说不通。"}], "explanations": {"便是": "便是：就是，指出站在门口的那位就是我的老师。", "在": "配价：“在”后面要接处所，不能直接接“我的老师”。", "叫": "语义：“叫”表示称呼，不能用来判定“那位就是我的老师”。", "来": "语义：“来”表示到来，“那位来我的老师”说不通。"}, "sentence_index": 0, "correct_answer": "便是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一到家便是开始做饭。", "explanation": "这里应该用〈就〉。“一…就…”表示先后紧接，“便是”用于判断是什么，不能用在这种先后关系里。"}, {"text": "我吃完饭，便是出门。", "explanation": "这里应该用〈然后〉。表示动作的先后要用“然后”，“便是”用于判断是什么，不能表示先后。"}, {"text": "下课铃一响，学生们便是跑出了教室。", "explanation": "这里应该用〈就〉。“一…就…”表示动作紧接着发生，“便是”用于判断是什么，不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便是", "is_correct": true, "explanation": "便是：就是，指出这片绿色就是我们的果园。"}, {"text": "围", "is_correct": false, "explanation": "语义：“围”指四周环绕，“绿色”不能用来“围”果园。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能收割“果园”这个地方。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅，此处说不通。"}], "explanations": {"便是": "便是：就是，指出这片绿色就是我们的果园。", "围": "语义：“围”指四周环绕，“绿色”不能用来“围”果园。", "收割": "搭配：“收割”的对象是庄稼，不能收割“果园”这个地方。", "闻": "语义：“闻”指用鼻子嗅，此处说不通。"}, "sentence_index": 6, "correct_answer": "便是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一看到我便是笑了起来。", "explanation": "这里应该用〈就〉。“一…就…”表示紧接着发生，“便是”用于判断是什么，不能表示先后。"}, {"text": "天一黑，路灯便是亮了。", "explanation": "这里应该用〈就〉。表示条件出现后马上发生要用“就”，“便是”用于判断，不能这样用。"}, {"text": "只要努力，便是能成功。", "explanation": "这里应该用〈就〉。“只要…就…”表示条件关系，“便是”用于判断是什么，不能用在条件句里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个穿红衣服的人便是是我的哥哥。", "corrected_sentence": "那个穿红衣服的人便是我的哥哥。", "error_description": "错误：“便是”已经含有“是”，后面不能再加“是”。正确：“便是我的哥哥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手里拿的很便是我的书。", "corrected_sentence": "他手里拿的便是我的书。", "error_description": "错误：“便是”是判断词，前面不能加程度副词“很”。正确：去掉“很”，写作“他手里拿的便是我的书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
