INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "就是；表示肯定的判断。", "primary_collocate": null, "pronunciation": "biàn shì", "ipa": "pjɛn˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他说的便是实话。", "target_word": "便是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要的便是这种红色。", "target_word": "便是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对孩子来说，最好的礼物便是时间。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做人最重要的便是诚实。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛，我们的目标便是第一名。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人最大的快乐便是看着孩子长大。", "target_word": "便是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，答案便是不去。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好中文的办法便是每天多说。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的规矩便是早睡早起。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唯一的爱好便是在家看书。", "target_word": "便是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "便是：书面的“就是”，对前面的话作出肯定、确定的判断，常见于“最……的便是……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89774, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "便是", "is_correct": true, "explanation": "便是（biàn shì）：正确答案，表示肯定的判断，即“就是”。"}, {"text": "面试", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是面试。"}, {"text": "办事", "is_correct": false, "explanation": "bàn 与 biàn 相比少了介音 i，意思是办事。"}, {"text": "辨识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是辨识。"}], "explanations": {"便是": "便是（biàn shì）：正确答案，表示肯定的判断，即“就是”。", "面试": "miàn 与 biàn 声母不同（m 与 b），意思是面试。", "办事": "bàn 与 biàn 相比少了介音 i，意思是办事。", "辨识": "shí（第二声）与 shì（第四声）声调不同，意思是辨识。"}, "sentence_index": null, "correct_answer": "便是"}, "level_3": {"options": [{"text": "便是", "is_correct": true, "explanation": "便是：就是，对“他说的”作出肯定的判断，指出就是实话。"}, {"text": "带", "is_correct": false, "explanation": "语义：“带”指随身携带，“实话”不能被带。"}, {"text": "撒", "is_correct": false, "explanation": "搭配：“撒”的对象是谎话或种子，不说“撒实话”。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”指用文火久煮，“实话”不能被熬。"}], "explanations": {"便是": "便是：就是，对“他说的”作出肯定的判断，指出就是实话。", "带": "语义：“带”指随身携带，“实话”不能被带。", "撒": "搭配：“撒”的对象是谎话或种子，不说“撒实话”。", "熬": "语义：“熬”指用文火久煮，“实话”不能被熬。"}, "sentence_index": 0, "correct_answer": "便是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想了想，便是同意了。", "explanation": "这里应该用〈于是〉。表示接着做出的结果要用“于是”，“便是”用于判断是什么，不能用在这里。"}, {"text": "我们吃完晚饭，便是看电视。", "explanation": "这里应该用〈然后〉。表示动作的先后要用“然后”，“便是”用于判断是什么，不能表示先后。"}, {"text": "他写完作业，便是睡觉。", "explanation": "这里应该用〈再〉。表示接下来做某事要用“再”，“便是”用于判断，不表示先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便是", "is_correct": true, "explanation": "便是：就是，指出答案就是“不去”。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”要带接受的人和给出的事物，此处“答案给不去”说不通。"}, {"text": "成", "is_correct": false, "explanation": "搭配：“成”表示变成，“答案”不能变成“不去”。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅，此处说不通。"}], "explanations": {"便是": "便是：就是，指出答案就是“不去”。", "给": "配价：“给”要带接受的人和给出的事物，此处“答案给不去”说不通。", "成": "搭配：“成”表示变成，“答案”不能变成“不去”。", "闻": "语义：“闻”指用鼻子嗅，此处说不通。"}, "sentence_index": 6, "correct_answer": "便是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一进门，小狗便是跑了过来。", "explanation": "这里应该用〈就〉。“一…就…”表示紧接着发生，“便是”用于判断，不能表示先后。"}, {"text": "雨一停，孩子们便是出去玩了。", "explanation": "这里应该用〈就〉。表示一件事发生后马上做另一件事要用“就”，“便是”不能这样用。"}, {"text": "如果你有空，便是来我家吧。", "explanation": "这里应该用〈就〉。“如果…就…”表示条件关系，“便是”用于判断是什么，不能用在条件句里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买便是这本书。", "corrected_sentence": "我买的便是这本书。", "error_description": "错误：“我买”后面漏了“的”，应构成名词性短语作主语。正确：“我买的便是这本书。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学习的目标很便是提高成绩。", "corrected_sentence": "学习的目标便是提高成绩。", "error_description": "错误：“便是”是判断词，前面不能加程度副词“很”。正确：去掉“很”，写作“学习的目标便是提高成绩。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低档", "is_correct": true, "explanation": "反义：「低档」与「高档」相对，表示档次低，与「高级」指档次高的意思相反。"}, {"text": "干净", "is_correct": false, "explanation": "无关：「干净」说卫生状况，与档次高低没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：「安静」说声音或环境，不是「高级」的反义词。"}, {"text": "结实", "is_correct": false, "explanation": "无关：「结实」说质地牢固，与档次高低没有反义关系。"}], "correct_answer": "低档", "explanations": {"低档": "反义：「低档」与「高档」相对，表示档次低，与「高级」指档次高的意思相反。", "干净": "无关：「干净」说卫生状况，与档次高低没有反义关系。", "安静": "无关：「安静」说声音或环境，不是「高级」的反义词。", "结实": "无关：「结实」说质地牢固，与档次高低没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低级", "is_correct": true, "explanation": "反义：「低级」与「高级」相对，指档次或质量低，与「高级」的意思相反。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：「清楚」形容明白或清晰，与档次高低没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：「热闹」形容场面或气氛，与「高级」没有反义关系。"}, {"text": "饱满", "is_correct": false, "explanation": "无关：「饱满」形容充足或充实，与「高级」不构成反义。"}], "correct_answer": "低级", "explanations": {"低级": "反义：「低级」与「高级」相对，指档次或质量低，与「高级」的意思相反。", "清楚": "无关：「清楚」形容明白或清晰，与档次高低没有反义关系。", "热闹": "无关：「热闹」形容场面或气氛，与「高级」没有反义关系。", "饱满": "无关：「饱满」形容充足或充实，与「高级」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高级是等级高,比一般的好。", "primary_collocate": null, "pronunciation": "gāo jí", "ipa": "kɑʊ tɕi", "syllable_count": 2, "sentences": [{"text": "这家饭店很高级，菜也很贵。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个高级的手表。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的衣服都是用高级面料做的。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去了一家高级餐厅吃饭。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在高级酒店里。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车看起来很高级。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用高级的茶招待客人。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的家具非常高级。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种高级咖啡一杯要五十块。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天穿的衣服看起来很高级。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高級", "label": "繁体"}, {"form": "高级的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "指东西或场所档次高、质量好，比一般的好，如高级饭店、高级手表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便宜", "is_correct": false, "explanation": "语义：「便宜」说价格低，与后句「菜也很贵」相矛盾。"}, {"text": "高级", "is_correct": true, "explanation": "正确：「高级」说饭店的档次高，与「菜也很贵」相呼应。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：「厚」说物体的厚度，不用来形容饭店的档次。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：「幼稚」形容行为或想法不成熟，不用来描述饭店。"}], "explanations": {"便宜": "语义：「便宜」说价格低，与后句「菜也很贵」相矛盾。", "高级": "正确：「高级」说饭店的档次高，与「菜也很贵」相呼应。", "厚": "搭配：「厚」说物体的厚度，不用来形容饭店的档次。", "幼稚": "语义：「幼稚」形容行为或想法不成熟，不用来描述饭店。"}, "sentence_index": 0, "correct_answer": "高级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很高级，适合去公园散步。", "explanation": "这里是把「高级」当作「很好、很不错」来形容天气，「高级」只用于说东西或场所的档次，不能形容天气。"}, {"text": "我们班的人数很高级，有四十个人。", "explanation": "这里应该用〈多〉。「高级」说等级或质量高，不用来说人数，人数多要用〈多〉。"}, {"text": "他的脚很高级，穿四十五码的鞋。", "explanation": "这里应该用〈大〉。「高级」说等级或质量高，不用来形容脚，脚大要用〈大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陈旧", "is_correct": false, "explanation": "语义：「陈旧」说东西不新，与「招待客人」的礼节不相符。"}, {"text": "高级", "is_correct": true, "explanation": "正确：「高级」说茶的档次高，符合招待客人的语境。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：「粗糙」多形容质地，不用来说茶的档次。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」形容场所或气氛，不能修饰茶。"}], "explanations": {"陈旧": "语义：「陈旧」说东西不新，与「招待客人」的礼节不相符。", "高级": "正确：「高级」说茶的档次高，符合招待客人的语境。", "粗糙": "搭配：「粗糙」多形容质地，不用来说茶的档次。", "冷清": "语义：「冷清」形容场所或气氛，不能修饰茶。"}, "sentence_index": 6, "correct_answer": "高级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的品德很高级，大家都很佩服他。", "explanation": "这里应该用〈高尚〉。「高级」说东西或场所的档次，形容人的品德要用〈高尚〉。"}, {"text": "这个孩子的脾气很高级，从不发火。", "explanation": "这里应该用〈温和〉。「高级」说东西或场所的档次，形容脾气要用〈温和〉。"}, {"text": "他的声音很高级，在很远的地方都能听见。", "explanation": "这里应该用〈高〉。「高级」说档次，声音高要用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一件很高级衣服。", "corrected_sentence": "我买了一件很高级的衣服。", "error_description": "「的」遗漏：「很高级」修饰「衣服」时，中间要加「的」，应为「很高级的衣服」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天买了一件很高级大衣。", "corrected_sentence": "我昨天买了一件很高级的大衣。", "error_description": "「的」遗漏：「很高级」修饰「大衣」时中间要加「的」，应为「很高级的大衣」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "初级", "is_correct": true, "explanation": "反义：「初级」与「高级」在等级上相对，是《现代汉语词典》收录的反义词。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：「复杂」说事物的构成繁多，与等级高低没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "无关：「轻松」说心情或难度不费力，与等级没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：「清晰」形容明白或分明，与等级高低没有反义关系。"}], "correct_answer": "初级", "explanations": {"初级": "反义：「初级」与「高级」在等级上相对，是《现代汉语词典》收录的反义词。", "复杂": "无关：「复杂」说事物的构成繁多，与等级高低没有反义关系。", "轻松": "无关：「轻松」说心情或难度不费力，与等级没有反义关系。", "清晰": "无关：「清晰」形容明白或分明，与等级高低没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": false, "explanation": "无关：「聪明」形容人的智力，与等级高低没有反义关系。"}, {"text": "初级", "is_correct": true, "explanation": "反义：「初级」与「高级」在等级上相对，是《现代汉语词典》收录的反义词。"}, {"text": "热情", "is_correct": false, "explanation": "无关：「热情」形容态度，与等级没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "无关：「陌生」形容不熟悉，与等级高低没有反义关系。"}], "correct_answer": "初级", "explanations": {"聪明": "无关：「聪明」形容人的智力，与等级高低没有反义关系。", "初级": "反义：「初级」与「高级」在等级上相对，是《现代汉语词典》收录的反义词。", "热情": "无关：「热情」形容态度，与等级没有反义关系。", "陌生": "无关：「陌生」形容不熟悉，与等级高低没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级、程度或质量较高的。", "primary_collocate": null, "pronunciation": "gāo jí", "ipa": "kɑʊ tɕi", "syllable_count": 2, "sentences": [{"text": "他在高级班学习汉语。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是学校的高级教师。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个汉语课是高级的，不太容易。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经是高级工程师了。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想从中级升到高级。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高级班的同学说得很流利。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是给高级学生看的。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平已经到了高级。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸是公司的高级经理。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高级课比中级课难多了。", "target_word": "高级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高級", "label": "繁体"}, {"form": "高级班", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指等级、程度较高，如高级班、高级工程师，与初级、中级相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "体貌：「漂亮」描述外貌，不用来说班级的等级。"}, {"text": "高级", "is_correct": true, "explanation": "正确：「高级」表示等级高，与「班」搭配，指水平高的班级。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：「高兴」是情绪，班级没有高兴与否的属性，不能修饰「班」来说等级。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：「甜美」形容声音或容貌，不用来修饰班级。"}], "explanations": {"漂亮": "体貌：「漂亮」描述外貌，不用来说班级的等级。", "高级": "正确：「高级」表示等级高，与「班」搭配，指水平高的班级。", "高兴": "语义：「高兴」是情绪，班级没有高兴与否的属性，不能修饰「班」来说等级。", "甜美": "语义：「甜美」形容声音或容貌，不用来修饰班级。"}, "sentence_index": 0, "correct_answer": "高级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们公司的高级，负责管理所有员工。", "explanation": "这里应该用〈上级〉。「高级」说等级高，不用来指领导的层级，指领导要用〈上级〉。"}, {"text": "这壶水很高级，已经烧开了。", "explanation": "这里是把「高级」当作温度高来用，「高级」只说等级或质量高，形容水热要用〈热〉。"}, {"text": "他的力气很高级，一个人能扛起一百斤。", "explanation": "这里应该用〈强〉。「高级」说等级或质量高，不用来形容力气，力气大要用〈强〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柔软", "is_correct": false, "explanation": "语义：「柔软」形容物体的质地，不能修饰「学生」。"}, {"text": "高级", "is_correct": true, "explanation": "正确：「高级」表示程度或水平高，与「学生」搭配，指水平高的学生。"}, {"text": "透明", "is_correct": false, "explanation": "语义：「透明」形容物体能透光，不能用来形容学生的水平。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：「甜」说味道，不修饰人群。"}], "explanations": {"柔软": "语义：「柔软」形容物体的质地，不能修饰「学生」。", "高级": "正确：「高级」表示程度或水平高，与「学生」搭配，指水平高的学生。", "透明": "语义：「透明」形容物体能透光，不能用来形容学生的水平。", "甜": "搭配：「甜」说味道，不修饰人群。"}, "sentence_index": 6, "correct_answer": "高级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的道德很高级，从不说谎，大家都很信任他。", "explanation": "这里应该用〈高尚〉。「高级」说等级或质量高，形容道德要用〈高尚〉。"}, {"text": "这条河很高级，有三千公里长。", "explanation": "这里应该用〈长〉。「高级」说等级或质量高，不用来形容河的长度，河长要用〈长〉。"}, {"text": "这件衣服的价格很高级，所以很贵。", "explanation": "这里应该用〈高〉。「高级」说档次，价格高要用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹在很高级班学习日语。", "corrected_sentence": "我妹妹在高级班学习日语。", "error_description": "错误在「很高级班」：「高级」在「高级班」里表示等级，是区别性的定语，前面不能加「很」，应删去「很」，说「高级班」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典是给很高级学生用的。", "corrected_sentence": "这本词典是给高级学生用的。", "error_description": "错误在「很高级学生」：「高级」直接修饰「学生」，表示等级，前面不能加「很」，应删去「很」，说「高级学生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
