INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89777, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有告诉别人，悄悄把别人的东西拿走。", "primary_collocate": null, "pronunciation": "tōu", "ipa": "tʰoʊ̯˥", "syllable_count": 1, "sentences": [{"text": "昨天有人偷了我的自行车。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在商店里偷东西，警察来了。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要偷别人的东西，这是不对的。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人偷走了我的钱包。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人偷过邻居的鸡。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饿极了，偷了一个面包。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上有人想偷我家的车，狗叫了起来。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候他偷过爷爷的糖。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子偷了同学的笔，老师很生气。", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁偷了我桌上的苹果？", "target_word": "偷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偷了", "label": "体标"}, {"form": "偷过", "label": "体标"}, {"form": "偷走", "label": "复合"}, {"form": "小偷", "label": "复合"}], "register": "口语", "sense_fingerprint": "未经允许，悄悄拿走别人的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89777, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "偷", "is_correct": true, "explanation": "偷（tōu，第一声）：没有告诉别人，悄悄拿走别人的东西，即本词。"}, {"text": "头", "is_correct": false, "explanation": "头（tóu，第二声）与 tōu（第一声）声调不同，意思是脑袋、头部。"}, {"text": "透", "is_correct": false, "explanation": "透（tòu，第四声）与 tōu（第一声）声调不同，意思是穿过、透明。"}, {"text": "都", "is_correct": false, "explanation": "都（dōu）与 tōu 声母不同（d 与 t），声调相同，意思是全部、都。"}], "explanations": {"偷": "偷（tōu，第一声）：没有告诉别人，悄悄拿走别人的东西，即本词。", "头": "头（tóu，第二声）与 tōu（第一声）声调不同，意思是脑袋、头部。", "透": "透（tòu，第四声）与 tōu（第一声）声调不同，意思是穿过、透明。", "都": "都（dōu）与 tōu 声母不同（d 与 t），声调相同，意思是全部、都。"}, "sentence_index": null, "correct_answer": "偷"}, "level_3": {"options": [{"text": "偷", "is_correct": true, "explanation": "偷：表示悄悄拿走别人的东西，与“有人”和“自行车”相符，是本句唯一合适的词。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说吃自行车。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能直接带“自行车”作宾语。"}, {"text": "吻", "is_correct": false, "explanation": "语义：“吻”的对象应是人或有生命的事物，用来指自行车语义上不通。"}], "explanations": {"偷": "偷：表示悄悄拿走别人的东西，与“有人”和“自行车”相符，是本句唯一合适的词。", "吃": "搭配：“吃”的对象应是食物，不能说吃自行车。", "哭": "配价：“哭”是不及物动词，后面不能直接带“自行车”作宾语。", "吻": "语义：“吻”的对象应是人或有生命的事物，用来指自行车语义上不通。"}, "sentence_index": 0, "correct_answer": "偷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大街上用力从她手里偷走了包，还推了她一下。", "explanation": "这里应该用〈抢走〉。偷是悄悄拿走；当面用力从人手里夺走是“抢”。"}, {"text": "他大大方方地偷走了桌上的一支笔。", "explanation": "这里应该用〈拿走〉。偷是暗中拿走，与“大大方方”矛盾；光明正大地拿走要说“拿走”。"}, {"text": "妈妈让我把垃圾偷出去。", "explanation": "这里应该用〈拿〉。偷是暗中拿走别人的东西，把垃圾拿出去是正常的家务，不是偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89777, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "偷", "is_correct": true, "explanation": "偷（tōu，第一声）：没有告诉别人，悄悄拿走别人的东西，即本词。"}, {"text": "投", "is_correct": false, "explanation": "投（tóu，第二声）与 tōu（第一声）声调不同，意思是投掷、投入。"}, {"text": "掏", "is_correct": false, "explanation": "掏（tāo，第一声）与 tōu 韵母不同（ao 与 ou），意思是把手伸进去取出，如掏钱。"}, {"text": "抠", "is_correct": false, "explanation": "抠（kōu，第一声）与 tōu 声母不同（k 与 t），意思是用指尖挖、抠。"}], "explanations": {"偷": "偷（tōu，第一声）：没有告诉别人，悄悄拿走别人的东西，即本词。", "投": "投（tóu，第二声）与 tōu（第一声）声调不同，意思是投掷、投入。", "掏": "掏（tāo，第一声）与 tōu 韵母不同（ao 与 ou），意思是把手伸进去取出，如掏钱。", "抠": "抠（kōu，第一声）与 tōu 声母不同（k 与 t），意思是用指尖挖、抠。"}, "sentence_index": null, "correct_answer": "偷"}, "level_3": {"options": [{"text": "偷", "is_correct": true, "explanation": "偷：表示悄悄拿走别人的东西，与“晚上有人”和“我家的车”相符，是本句唯一合适的词。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象应是液体或饮料，不能说喝车。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的动作对象一般是食物或生物，车不能被咬，句子语义不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象应是歌曲，不能说唱车。"}], "explanations": {"偷": "偷：表示悄悄拿走别人的东西，与“晚上有人”和“我家的车”相符，是本句唯一合适的词。", "喝": "搭配：“喝”的对象应是液体或饮料，不能说喝车。", "咬": "语义：“咬”的动作对象一般是食物或生物，车不能被咬，句子语义不通。", "唱": "搭配：“唱”的对象应是歌曲，不能说唱车。"}, "sentence_index": 6, "correct_answer": "偷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用合法手续从银行偷出了存款。", "explanation": "这里应该用〈取出〉。偷是非法的暗中拿走，与“合法手续”矛盾；正当取钱要说“取出”。"}, {"text": "他经过主人同意，偷走了那本书。", "explanation": "这里应该用〈借走〉。偷是未经允许拿走，与“经过主人同意”矛盾；经过同意拿走要说“借走”。"}, {"text": "请把我的书偷过来。", "explanation": "这里应该用〈拿〉。偷的对象必须是别人的东西，自己的书拿过来不能说偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前偷了过我的钱包。", "corrected_sentence": "他以前偷过我的钱包。", "error_description": "体标错误：“偷”后面不能同时用“了”和“过”。表示曾经做过要说“偷过”，应改为“他以前偷过我的钱包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把我的手套偷了走了。", "corrected_sentence": "他把我的手套偷走了。", "error_description": "结构错误：复合动词“偷走”中间不能插入“了”。错误：偷了走了；正确：偷走了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
