INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "享受是得到好东西,心里很快乐。", "primary_collocate": null, "pronunciation": "xiǎng shòu", "ipa": "ɕjɑŋ˨˩˦ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他坐在新沙发上，享受着舒服的感觉。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在冰淇淋店里享受甜甜的美味。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一家人享受着丰盛的晚餐。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚拿到奖金，想享受一顿好饭。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在海边的别墅里，她享受着舒适的生活。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车开起来真舒服，他很享受。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次坐头等舱，好好享受了一下。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕又香又甜，孩子们享受着每一口。", "target_word": "享受", "complexity_tier": "T3", "furigana": "dàngāo yòu xiāng yòu tián, háizimen xiǎngshòuzhe měi yì kǒu。", "sentence_source": "generated"}, {"text": "周末去酒店住一晚，享受服务员的照顾。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喝着新茶，一脸享受的样子。", "target_word": "享受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "享受着", "label": "体标"}, {"form": "享受了", "label": "体标"}, {"form": "享受过", "label": "体标"}], "register": "中性", "sense_fingerprint": "享受|动词|得到好东西，心里很快乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“舒服的感觉”所描述的享受语境相反。"}, {"text": "享受", "is_correct": true, "explanation": "正确：“享受”表示得到好东西后心里快乐，与“舒服的感觉”搭配。"}, {"text": "打扰", "is_correct": false, "explanation": "搭配：“打扰”的对象是人或活动，不能说“打扰舒服的感觉”。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：“厌恶”是讨厌，与“舒服”的感受相冲突。"}], "explanations": {"拒绝": "语义：“拒绝”表示不接受，与“舒服的感觉”所描述的享受语境相反。", "享受": "正确：“享受”表示得到好东西后心里快乐，与“舒服的感觉”搭配。", "打扰": "搭配：“打扰”的对象是人或活动，不能说“打扰舒服的感觉”。", "厌恶": "语义：“厌恶”是讨厌，与“舒服”的感受相冲突。"}, "sentence_index": 0, "correct_answer": "享受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次当老师，享受着学生的哭闹。", "explanation": "这里应该用〈忍受〉。享受指得到快乐，学生的哭闹不能享受，要用“忍受”。"}, {"text": "他认真享受了老师的批评。", "explanation": "这里应该用〈接受〉。享受指得到快乐，“批评”不是能享受的东西。"}, {"text": "他每天都在享受着工作的巨大压力。", "explanation": "这里应该用〈承受〉。享受指得到快乐，压力是负担，要用“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”是毁坏，与“坐头等舱”的舒适语境相反。"}, {"text": "享受", "is_correct": true, "explanation": "正确：“享受了一下”表示得到舒适后的快乐，与“好好”搭配。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”的感情色彩与“好好”和舒适的语境相冲突。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：“咒骂”是用恶毒的话骂人，与坐头等舱的舒适、愉快语境冲突。"}], "explanations": {"破坏": "语义：“破坏”是毁坏，与“坐头等舱”的舒适语境相反。", "享受": "正确：“享受了一下”表示得到舒适后的快乐，与“好好”搭配。", "讨厌": "语义：“讨厌”的感情色彩与“好好”和舒适的语境相冲突。", "咒骂": "语义：“咒骂”是用恶毒的话骂人，与坐头等舱的舒适、愉快语境冲突。"}, "sentence_index": 6, "correct_answer": "享受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在路上，他享受了一场大雨，衣服全湿了。", "explanation": "这里应该用〈遭遇〉。享受表示得到快乐，大雨使衣服湿透，不能说享受。"}, {"text": "他一直享受着这场病，没有说一句话。", "explanation": "这里应该用〈忍受〉。享受指得到快乐，生病不能享受，要用“忍受”。"}, {"text": "他在地震中享受了巨大的损失，全家都很难过。", "explanation": "这里应该用〈遭受〉。享受指得到快乐，“损失”是不好的事，要用“遭受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她躺在床上，享受了着温暖的被子。", "corrected_sentence": "她躺在床上，享受着温暖的被子。", "error_description": "“享受”后面的“着”表示动作正在进行，不能再加“了”。应说“享受着”，不说“享受了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在树下享受了着冰凉的西瓜。", "corrected_sentence": "孩子们在树下享受着冰凉的西瓜。", "error_description": "“享受”后面的“着”表示动作正在进行，不能再加“了”。应说“享受着”，不说“享受了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
