INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不聪明，做事让人觉得好笑。", "primary_collocate": null, "pronunciation": "shǎ", "ipa": "ʂa˨˩˦", "syllable_count": 1, "sentences": [{"text": "他穿着拖鞋去爬山，样子真傻。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做了一件很傻的事，大家都笑我。", "target_word": "傻", "complexity_tier": "T3", "furigana": "wǒ zuò le yí jiàn hěn shǎ de shì, dà jiā dōu xiào wǒ", "sentence_source": "generated"}, {"text": "别问这么傻的问题，大家会笑你的。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张照片拍得很傻，我看了笑个不停。", "target_word": "傻", "complexity_tier": "T3", "furigana": "nà zhāng zhào piàn pāi de hěn shǎ, wǒ kàn le xiào gè bù tíng", "sentence_source": "generated"}, {"text": "他给小狗穿西装，样子又傻又可爱。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我当时说了一句很傻的话，现在想起来还脸红。", "target_word": "傻", "complexity_tier": "T3", "furigana": "wǒ dāng shí shuō le yí jù hěn shǎ de huà, xiàn zài xiǎng qǐ lái hái liǎn hóng", "sentence_source": "generated"}, {"text": "弟弟把鞋穿反了还不知道，样子很傻。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把帽子戴反了，看起来很傻。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我笑自己傻，竟然把手机放进了冰箱。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的动作很傻，孩子们看了都哈哈大笑。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傻傻", "label": "重叠"}, {"form": "傻话", "label": "复合"}, {"form": "傻事", "label": "复合"}], "register": "口语", "sense_fingerprint": "言行滑稽可笑、让人觉得傻气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指言行滑稽、让人觉得好笑。"}, {"text": "沙", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。"}, {"text": "啥", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。"}, {"text": "少", "is_correct": false, "explanation": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。"}, {"text": "洒", "is_correct": false, "explanation": "sǎ 与 shǎ 声母不同（s 与 sh），sǎ 意思是洒（水）。"}, {"text": "厦", "is_correct": false, "explanation": "shà（第四声）与 shǎ（第三声）声调不同，意思是大厦。"}], "explanations": {"傻": "正确答案。傻指言行滑稽、让人觉得好笑。", "沙": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。", "啥": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。", "少": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。", "洒": "sǎ 与 shǎ 声母不同（s 与 sh），sǎ 意思是洒（水）。", "厦": "shà（第四声）与 shǎ（第三声）声调不同，意思是大厦。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示言行滑稽可笑，穿拖鞋爬山正合此意。"}, {"text": "得体", "is_correct": false, "explanation": "语义：穿拖鞋爬山谈不上得体，与句中的滑稽形象矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多形容心情或负担，与穿拖鞋爬山的滑稽样子不搭。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：穿拖鞋爬山的样子很难显得严肃，与句意的滑稽相矛盾。"}], "explanations": {"傻": "正确。傻表示言行滑稽可笑，穿拖鞋爬山正合此意。", "得体": "语义：穿拖鞋爬山谈不上得体，与句中的滑稽形象矛盾。", "沉重": "搭配：“沉重”多形容心情或负担，与穿拖鞋爬山的滑稽样子不搭。", "严肃": "语义：穿拖鞋爬山的样子很难显得严肃，与句意的滑稽相矛盾。"}, "sentence_index": 0, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很傻，怎么也敲不碎。", "explanation": "这里应该用〈坚硬〉。坚硬指质地硬，傻指头脑不灵或做事可笑，不能用来形容石头。"}, {"text": "这间屋子很傻，墙角都长了霉。", "explanation": "这里应该用〈潮湿〉。潮湿指含水分多，傻不能用来形容屋子的湿度。"}, {"text": "这块布的颜色很傻，看着很刺眼。", "explanation": "这里应该用〈鲜艳〉。鲜艳形容颜色明亮，傻不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指言行滑稽、让人觉得好笑。"}, {"text": "纱", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。"}, {"text": "煞", "is_correct": false, "explanation": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}], "explanations": {"傻": "正确答案。傻指言行滑稽、让人觉得好笑。", "纱": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。", "煞": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。", "闪": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。", "耍": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。", "赏": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示头脑不灵、显得可笑，把鞋穿反了还不知道正合此意。"}, {"text": "威风", "is_correct": false, "explanation": "语义：把鞋穿反了还不知道，样子谈不上威风，句意是可笑的。"}, {"text": "威严", "is_correct": false, "explanation": "语义：威严的样子与把鞋穿反、还不知道的糊涂形象矛盾。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说物体的厚薄，不用来形容人的样子。"}], "explanations": {"傻": "正确。傻表示头脑不灵、显得可笑，把鞋穿反了还不知道正合此意。", "威风": "语义：把鞋穿反了还不知道，样子谈不上威风，句意是可笑的。", "威严": "语义：威严的样子与把鞋穿反、还不知道的糊涂形象矛盾。", "厚": "搭配：“厚”说物体的厚薄，不用来形容人的样子。"}, "sentence_index": 6, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的表面很傻，摸上去很光滑。", "explanation": "这里应该用〈光滑〉。光滑形容表面平整，傻不能用来形容木板的表面。"}, {"text": "今年的天气很傻，一连几个月都没下雨。", "explanation": "这里应该用〈干燥〉。干燥指缺少水分，傻不能用来形容天气。"}, {"text": "今年的雨水很傻，河水涨了好几次。", "explanation": "这里应该用〈充足〉。充足指数量多、够用，傻不能用来形容雨水的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他唱歌的样子傻很，大家都笑了。", "corrected_sentence": "他唱歌的样子很傻，大家都笑了。", "error_description": "错误：“傻很”，程度副词“很”应放在“傻”前面。正确：“很傻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做了一件很傻事，后来一直后悔。", "corrected_sentence": "他做了一件很傻的事，后来一直后悔。", "error_description": "错误：“很傻事”漏了定语后的“的”。正确：“很傻的事”，形容词修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "正确。“聪明”与“傻”在“头脑不灵活”的意思上构成反义。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”描写心情，与“傻”（头脑不灵）没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描写做事态度，与“傻”的头脑义没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”构成反义，与“傻”没有反义关系。"}], "correct_answer": "聪明", "explanations": {"聪明": "正确。“聪明”与“傻”在“头脑不灵活”的意思上构成反义。", "高兴": "“高兴”描写心情，与“傻”（头脑不灵）没有反义关系。", "认真": "“认真”描写做事态度，与“傻”的头脑义没有反义关系。", "安静": "“安静”与“吵闹”构成反义，与“傻”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "正确。“聪明”与“傻”在“头脑不灵活”的意思上构成反义。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”描写待人的态度，与“傻”（头脑不灵）没有反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "“大方”指不吝啬，与“傻”的头脑义没有反义关系。"}, {"text": "仔细", "is_correct": false, "explanation": "“仔细”指做事周到，与“傻”没有反义关系。"}], "correct_answer": "聪明", "explanations": {"聪明": "正确。“聪明”与“傻”在“头脑不灵活”的意思上构成反义。", "热情": "“热情”描写待人的态度，与“傻”（头脑不灵）没有反义关系。", "大方": "“大方”指不吝啬，与“傻”的头脑义没有反义关系。", "仔细": "“仔细”指做事周到，与“傻”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "头脑不灵活；糊涂。", "primary_collocate": null, "pronunciation": "shǎ", "ipa": "ʂa˨˩˦", "syllable_count": 1, "sentences": [{"text": "这孩子太傻，别人说什么他都信。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是傻，只是反应有点慢。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你真傻，他明明在骗你，你还信。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我傻得连这么简单的题都不会。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来傻，其实心里很明白。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太傻了，被骗了五次还不知道。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有点傻，听不懂别人的玩笑。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是不傻，就不会把钱借给陌生人。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前很聪明，现在老了，脑子有点傻了。", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么傻，连钱都数不清？", "target_word": "傻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傻傻", "label": "重叠"}, {"form": "傻瓜", "label": "复合"}, {"form": "傻子", "label": "复合"}], "register": "口语", "sense_fingerprint": "头脑不灵、不明事理，容易被骗或反应迟钝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指头脑不灵活、糊涂。"}, {"text": "沙", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。"}, {"text": "啥", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。"}, {"text": "少", "is_correct": false, "explanation": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。"}, {"text": "洒", "is_correct": false, "explanation": "sǎ 与 shǎ 声母不同（s 与 sh），sǎ 意思是洒（水）。"}], "explanations": {"傻": "正确答案。傻指头脑不灵活、糊涂。", "沙": "shǎ（第三声）与 shā（第一声）声调不同，意思是沙子。", "啥": "shǎ（第三声）与 shá（第二声）声调不同，意思是什么。", "少": "shǎ 与 shǎo 韵母不同，shǎo 意思是少。", "耍": "shuǎ 比 shǎ 多介音 u，shuǎ 意思是玩耍。", "洒": "sǎ 与 shǎ 声母不同（s 与 sh），sǎ 意思是洒（水）。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示头脑不灵活，句中“别人说什么他都信”正说明这一点。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”与后句“别人说什么他都信”相矛盾，聪明的孩子不会什么都信。"}, {"text": "精明", "is_correct": false, "explanation": "语义：“精明”与“什么都信”相矛盾，精明的人不会轻易相信别人。"}, {"text": "沧桑", "is_correct": false, "explanation": "搭配：“沧桑”形容阅历，多用于人，不用来形容孩子，“太沧桑”说不通。"}], "explanations": {"傻": "正确。傻表示头脑不灵活，句中“别人说什么他都信”正说明这一点。", "聪明": "语义：“聪明”与后句“别人说什么他都信”相矛盾，聪明的孩子不会什么都信。", "精明": "语义：“精明”与“什么都信”相矛盾，精明的人不会轻易相信别人。", "沧桑": "搭配：“沧桑”形容阅历，多用于人，不用来形容孩子，“太沧桑”说不通。"}, "sentence_index": 0, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的味道很傻，大家都抢着喝。", "explanation": "这里应该用〈鲜美〉。鲜美形容味道好，傻不能用来形容汤的味道。"}, {"text": "这幅画的构图太傻，缺少变化。", "explanation": "这里应该用〈呆板〉。呆板形容死板、缺少变化，傻指头脑不灵，不能用来评价构图。"}, {"text": "这份数据的统计很傻，每个数字都对不上。", "explanation": "这里应该用〈精确〉。精确指准确无误，傻指头脑不灵，不能用来形容统计的准确程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确答案。傻指头脑不灵活、糊涂。"}, {"text": "纱", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。"}, {"text": "煞", "is_correct": false, "explanation": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}], "explanations": {"傻": "正确答案。傻指头脑不灵活、糊涂。", "纱": "shǎ（第三声）与 shā（第一声）声调不同，意思是纱布。", "煞": "shà（第四声）与 shǎ（第三声）声调不同，shà 意思是止住、勒住，如“煞住”。", "闪": "shǎn 比 shǎ 多了韵尾 n，意思是闪电。", "赏": "shǎng 比 shǎ 多了韵尾 ng，意思是欣赏。"}, "sentence_index": null, "correct_answer": "傻"}, "level_3": {"options": [{"text": "傻", "is_correct": true, "explanation": "正确。傻表示头脑不灵，听不懂玩笑正是这种表现。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”的人通常听得懂玩笑，与“听不懂别人的玩笑”相矛盾。"}, {"text": "机灵", "is_correct": false, "explanation": "语义：“机灵”的人反应快，不会听不懂玩笑，与句意矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，人不说“有点亮”，句中不能这样用。"}], "explanations": {"傻": "正确。傻表示头脑不灵，听不懂玩笑正是这种表现。", "幽默": "语义：“幽默”的人通常听得懂玩笑，与“听不懂别人的玩笑”相矛盾。", "机灵": "语义：“机灵”的人反应快，不会听不懂玩笑，与句意矛盾。", "亮": "搭配：“亮”形容光线，人不说“有点亮”，句中不能这样用。"}, "sentence_index": 6, "correct_answer": "傻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的坡度很傻，车子开上去总是熄火。", "explanation": "这里应该用〈陡〉。陡形容坡度大，傻不能用来形容坡度。"}, {"text": "他的观察力很傻，一眼就看出了破绽。", "explanation": "这里应该用〈敏锐〉。敏锐形容观察、感觉灵敏，傻指头脑不灵，不能用来形容观察力。"}, {"text": "这份报告的格式很傻，看着让人头疼。", "explanation": "这里应该用〈规范〉。规范指符合标准，傻指头脑不灵，不能用来形容报告的格式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他傻太了，连这个都看不出来。", "corrected_sentence": "他太傻了，连这个都看不出来。", "error_description": "错误：“傻太了”语序颠倒。正确：“太傻了”，程度副词“太”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他得傻连门都找不到。", "corrected_sentence": "他傻得连门都找不到。", "error_description": "错误：“得”位置颠倒，补语标记应放在形容词“傻”之后。正确：“傻得连门都找不到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
