INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89783, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人才是有本领的人。", "primary_collocate": null, "pronunciation": "rén cái", "ipa": "ɻən tsʰaɪ", "syllable_count": 2, "sentences": [{"text": "他有真本事，是个人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子很聪明，将来一定是人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有不少体育人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说她是唱歌的人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的工作需要懂电脑的人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队正在找踢得好的人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做饭很好，真是个人才！", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年招了五个新人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城市也有很多人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去大城市找机会，因为那里人才多。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "人才库", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指在某方面有本领、有特长的人，如体育人才、真是个人才", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废物", "is_correct": false, "explanation": "语义：「废物」指没有用的人，与「有真本事」的评价相反。"}, {"text": "人才", "is_correct": true, "explanation": "正确：「人才」指有本领的人，与「有真本事」的评价一致。"}, {"text": "笨蛋", "is_correct": false, "explanation": "语义：「笨蛋」是骂人的话，与「有真本事」的评价矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：「病人」指生病的人，与「有真本事」说的能力无关。"}], "explanations": {"废物": "语义：「废物」指没有用的人，与「有真本事」的评价相反。", "人才": "正确：「人才」指有本领的人，与「有真本事」的评价一致。", "笨蛋": "语义：「笨蛋」是骂人的话，与「有真本事」的评价矛盾。", "病人": "语义：「病人」指生病的人，与「有真本事」说的能力无关。"}, "sentence_index": 0, "correct_answer": "人才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班今年来了一只体育人才。", "explanation": "这里应该用〈位〉。量词「只」用于动物，指人的「人才」要用「位」或「批」。"}, {"text": "这辆新汽车是公司的重要人才。", "explanation": "这里是把「人才」当作有价值的物品来说，这个意思是错的：「人才」只指有本领的人，不指汽车这样的物品。"}, {"text": "这家商店今天一共来了五十个人才，都在门口排队。", "explanation": "这里应该用〈顾客〉。「人才」只指有本领的人，不用来数来店里买东西的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能做饭，与前句「做饭很好」矛盾。"}, {"text": "人才", "is_correct": true, "explanation": "正确：「人才」指有本事的人，与「做饭很好」的评价相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会做饭，句子评价的是做饭的本事，不能用「石头」。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：「胖子」描述身材，与句中评价做饭本事的语境无关。"}], "explanations": {"椅子": "语义：椅子不能做饭，与前句「做饭很好」矛盾。", "人才": "正确：「人才」指有本事的人，与「做饭很好」的评价相符。", "石头": "语义：石头不会做饭，句子评价的是做饭的本事，不能用「石头」。", "胖子": "体貌：「胖子」描述身材，与句中评价做饭本事的语境无关。"}, "sentence_index": 6, "correct_answer": "人才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院每天都要接待很多生病的人才。", "explanation": "这里应该用〈病人〉。「人才」指有本领的人，来医院看病的人要用〈病人〉。"}, {"text": "公园里有很多散步的人才。", "explanation": "这里应该用〈人〉。「人才」指有本领的人，在公园散步的普通人不用「人才」。"}, {"text": "我们今天要装修房子，需要五个人才来搬东西。", "explanation": "这里应该用〈人手〉。「人手」指能干活的人，搬东西不需要有才能的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里来了两只唱歌的人才。", "corrected_sentence": "班里来了两位唱歌的人才。", "error_description": "量词错误：「只」用于动物，指人的「人才」要用「位」，应改为「两位唱歌的人才」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是很有潜力人才，将来会成功。", "corrected_sentence": "他是很有潜力的人才，将来会成功。", "error_description": "「的」遗漏：修饰「人才」的「很有潜力」是短语，修饰语和中心语之间要加「的」，应为「很有潜力的人才」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
