INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有才能、有学问、能做好事的人。", "primary_collocate": null, "pronunciation": "rén cái", "ipa": "ɻən tsʰaɪ", "syllable_count": 2, "sentences": [{"text": "这家公司很需要年轻的人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校培养了很多科技人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位难得的人才，大家都想请他。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的人才不容易找到。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要更多的医学人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用高工资吸引人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市留不住人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很重视人才，经常给他们机会。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们公司的重要人才。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学是培养人才的地方。", "target_word": "人才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "批", "label": "量词"}, {"form": "人才市场", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指有才能、有学问、能做好事的人，常说培养人才、吸引人才", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：“年轻”只修饰人，工资是钱，不能说「年轻的工资」。"}, {"text": "人才", "is_correct": true, "explanation": "正确：「人才」指有才能的人，可以被「年轻的」修饰，也能作「需要」的宾语。"}, {"text": "机器", "is_correct": false, "explanation": "语义：「年轻」说的是人的年龄，机器不能年轻，与「年轻的」搭配不通。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：「年轻的」不修饰饮料，「年轻」不与饮料搭配。"}], "explanations": {"工资": "语义：“年轻”只修饰人，工资是钱，不能说「年轻的工资」。", "人才": "正确：「人才」指有才能的人，可以被「年轻的」修饰，也能作「需要」的宾语。", "机器": "语义：「年轻」说的是人的年龄，机器不能年轻，与「年轻的」搭配不通。", "饮料": "搭配：「年轻的」不修饰饮料，「年轻」不与饮料搭配。"}, "sentence_index": 0, "correct_answer": "人才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司新来了三只人才，都很能干。", "explanation": "这里应该用〈位〉。量词「只」用于动物，指人的「人才」要用「位」或「批」。"}, {"text": "这台新电脑是公司的重要人才。", "explanation": "这里是把「人才」当作有价值的物品来说，这个意思是错的：「人才」只指有本领的人，不指电脑这样的物品。"}, {"text": "我们班一共有三十个人才，都在教室里。", "explanation": "这里是把「人才」当作一般的人来数，「人才」只指有才能、有学问的人，数班里的人要用〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：「留不住」说的是人才或资源外流，「桌子」不是可以被城市留住的对象。"}, {"text": "人才", "is_correct": true, "explanation": "正确：「人才」是可以被城市留住或留不住的对象，与「留不住」搭配自然。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被城市留住，句子说的是人才流失。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：「留」一般搭配人、钱或资源，饭菜吃完就没了，不说「留不住饭菜」。"}], "explanations": {"桌子": "语义：「留不住」说的是人才或资源外流，「桌子」不是可以被城市留住的对象。", "人才": "正确：「人才」是可以被城市留住或留不住的对象，与「留不住」搭配自然。", "空气": "语义：空气无法被城市留住，句子说的是人才流失。", "饭菜": "搭配：「留」一般搭配人、钱或资源，饭菜吃完就没了，不说「留不住饭菜」。"}, "sentence_index": 6, "correct_answer": "人才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本小说一共写了三个主要人才。", "explanation": "这里应该用〈人物〉。「人物」指小说、故事里的角色，「人才」指有才能的人，不用来指书中的角色。"}, {"text": "医院门口站满了排队挂号的人才。", "explanation": "这里应该用〈病人〉。「人才」指有才能的人，排队挂号的是病人，不用「人才」。"}, {"text": "我们明天搬家，需要三个人才来帮忙。", "explanation": "这里应该用〈人手〉。「人手」指能干活的人，搬家只需要能帮忙的人，不强调才能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司今年招到了两只优秀的人才。", "corrected_sentence": "我们公司今年招到了两位优秀的人才。", "error_description": "量词错误：「只」用于动物，指人的「人才」要用「位」，应改为「两位优秀的人才」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司为了留住很有能力人才，提高了工资。", "corrected_sentence": "公司为了留住很有能力的人才，提高了工资。", "error_description": "「的」遗漏：修饰「人才」的「很有能力」是短语，修饰语和中心语之间要加「的」，应为「很有能力的人才」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
