INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89787, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "个把是一两个,不多。", "primary_collocate": null, "pronunciation": "gè bǎ", "ipa": "kɤ˥˩ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "桌子上只有个把苹果,不够吃。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里就剩个把学生了。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个把月才给家里打一次电话。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小病,休息个把天就好了。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加会的只有个把朋友。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说个把小时就能做完作业。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上偶尔能看到个把游客。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们再等个把分钟,好吗?", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只买了个把面包当早饭。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上冷清,只有个把行人。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个把月", "label": "复合"}, {"form": "个把人", "label": "复合"}, {"form": "个把钟头", "label": "复合"}], "register": "口语", "sense_fingerprint": "个把:数量很少,只有一两个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个把", "is_correct": true, "explanation": "正确：个把表示一两个，符合「只有…不够吃」的语境。"}, {"text": "一大堆", "is_correct": false, "explanation": "语义：「一大堆」表示数量很多，与「不够吃」的少量语境矛盾。"}, {"text": "成百上千个", "is_correct": false, "explanation": "语义：成百上千个苹果与「只有」和「不够吃」的少量语境矛盾。"}, {"text": "一大筐", "is_correct": false, "explanation": "语义：一大筐苹果与“只有”和“不够吃”的少量语境矛盾。"}], "explanations": {"个把": "正确：个把表示一两个，符合「只有…不够吃」的语境。", "一大堆": "语义：「一大堆」表示数量很多，与「不够吃」的少量语境矛盾。", "成百上千个": "语义：成百上千个苹果与「只有」和「不够吃」的少量语境矛盾。", "一大筐": "语义：一大筐苹果与“只有”和“不够吃”的少量语境矛盾。"}, "sentence_index": 0, "correct_answer": "个把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我正好花了个把块钱买了一本书。", "explanation": "这里应该用〈一块钱〉。「正好」表示确定的数目，个把只表示大约一两个，两者不能搭配。"}, {"text": "这个班的学生个把都考了第一名。", "explanation": "这里应该用〈全部〉。个把只表示一两个，不能表示全体，所以不能说「个把都」。"}, {"text": "这次一共买了个把苹果，够全班吃。", "explanation": "这里应该用〈很多〉。个把只表示一两个，不能与「够全班吃」这样的大量需求搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个把", "is_correct": true, "explanation": "正确：个把表示一两个，与「偶尔」的少量语境一致。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”指全部，与“偶尔能看到”矛盾。"}, {"text": "每一个", "is_correct": false, "explanation": "语义：“每一个”指全体中的每个，与“偶尔能看到”矛盾。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全体，与“偶尔能看到”矛盾。"}], "explanations": {"个把": "正确：个把表示一两个，与「偶尔」的少量语境一致。", "所有": "语义：“所有”指全部，与“偶尔能看到”矛盾。", "每一个": "语义：“每一个”指全体中的每个，与“偶尔能看到”矛盾。", "全部": "语义：“全部”指全体，与“偶尔能看到”矛盾。"}, "sentence_index": 6, "correct_answer": "个把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上挤满了个把行人。", "explanation": "这里应该用〈很多〉。个把只表示一两个，不能用来形容「挤满」的大量行人。"}, {"text": "这个月他正好去了个把次医院。", "explanation": "这里应该用〈一次〉。「正好」表示确定的次数，个把是大约一两次，两者不能搭配。"}, {"text": "这个箱子里装满了个把苹果。", "explanation": "这里应该用〈很多〉。个把只表示一两个，不能与「装满」所说的大量苹果搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个会议室只有个把的人，很安静。", "corrected_sentence": "这个会议室只有个把人，很安静。", "error_description": "错误形式「个把的人」多加了「的」。「个把」是数量词，直接修饰名词，中间不加「的」，正确形式是「个把人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街上只剩个把个行人了。", "corrected_sentence": "街上只剩个把行人了。", "error_description": "错误形式「个把个」多加了一个「个」。「个把」本身已经是量词，后面直接接名词，不能再加「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
