INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89788, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一两个;大约一个。", "primary_collocate": null, "pronunciation": "gè bǎ", "ipa": "kɤ˥˩ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想在家休息个把星期。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个把小时以后,他就回来了。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小事,个把人就能做完。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一年只来个把次。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了个把钟头,他才来。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每天只来个把客人。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里只剩个把鸡蛋。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个把月没见,你变瘦了。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出差了个把星期,今天回来。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去个把天就回来。", "target_word": "个把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个把月", "label": "复合"}, {"form": "个把人", "label": "复合"}, {"form": "个把星期", "label": "复合"}], "register": "口语", "sense_fingerprint": "个把:一两个,大约一个,用在量词或名词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个把", "is_correct": true, "explanation": "正确：个把表示一两个，符合休息一两个星期的语境。"}, {"text": "几万个", "is_correct": false, "explanation": "语义：几万个星期长达数百年以上，远超正常的休假时长。"}, {"text": "几百个", "is_correct": false, "explanation": "语义：几百个星期长达数年，远超正常的休息时长。"}, {"text": "上千个", "is_correct": false, "explanation": "语义：上千个星期与合理的休息时长相差太远。"}], "explanations": {"个把": "正确：个把表示一两个，符合休息一两个星期的语境。", "几万个": "语义：几万个星期长达数百年以上，远超正常的休假时长。", "几百个": "语义：几百个星期长达数年，远超正常的休息时长。", "上千个": "语义：上千个星期与合理的休息时长相差太远。"}, "sentence_index": 0, "correct_answer": "个把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我整整等了个把小时。", "explanation": "这里应该用〈一个小时〉。「整整」表示确定的时长，个把只表示大约一两个，两者不能搭配。"}, {"text": "地铁站里挤满了个把人。", "explanation": "这里应该用〈很多〉。个把只表示一两个，不能用来形容「挤满」的大量人群。"}, {"text": "这段路我正好走了个把公里。", "explanation": "这里应该用〈一公里〉。「正好」表示确定的距离，个把表示大约一两个，不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个把", "is_correct": true, "explanation": "正确：个把表示一两个，与「只剩」的少量语境一致。"}, {"text": "满满一箱", "is_correct": false, "explanation": "语义：「满满一箱」数量很多，与「只剩」的少量语境矛盾。"}, {"text": "上百个", "is_correct": false, "explanation": "语义：上百个鸡蛋与「只剩」的少量语境矛盾。"}, {"text": "一大堆", "is_correct": false, "explanation": "语义：「一大堆」数量很多，与「只剩」的少量语境矛盾。"}], "explanations": {"个把": "正确：个把表示一两个，与「只剩」的少量语境一致。", "满满一箱": "语义：「满满一箱」数量很多，与「只剩」的少量语境矛盾。", "上百个": "语义：上百个鸡蛋与「只剩」的少量语境矛盾。", "一大堆": "语义：「一大堆」数量很多，与「只剩」的少量语境矛盾。"}, "sentence_index": 6, "correct_answer": "个把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班个把都到了。", "explanation": "这里应该用〈全部〉。个把只表示一两个，不能表示全体，所以不能与「全班」「都」搭配。"}, {"text": "书架上摆满了个把本书。", "explanation": "这里应该用〈很多〉。个把只表示一两个，不能与「摆满」所说的大量书搭配。"}, {"text": "山上种满了个把树。", "explanation": "这里应该用〈很多〉。个把只表示一两个，不能与「种满」所说的大量树木搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他出去一个把小时就回来了。", "corrected_sentence": "他出去个把小时就回来了。", "error_description": "错误形式「一个把小时」多加了「一个」。「个把」本身就是固定的数量词，前面不能再加「一个」，正确形式是「个把小时」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下班后还要等个把的人，才能走。", "corrected_sentence": "他下班后还要等个把人，才能走。", "error_description": "错误形式「个把的人」多加了「的」。「个把」是数量词，直接修饰名词，中间不加「的」，正确形式是「个把人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
