INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事从开始到结束的那一段时间。", "primary_collocate": null, "pronunciation": "qián hòu", "ipa": "tɕʰjɛn˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "这本书他前后写了三年。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这座桥，前后用了两年。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题前后讨论了三天。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他前后学了三年中文。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事前后拖了半年。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前后进行了三天。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我前后去了四次北京。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病前后治了一个月。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司前后换了三个经理。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议前后开了两天。", "target_word": "前后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事从头到尾共花的时间或次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻，与“写了三年”的长时段相矛盾。"}, {"text": "前后", "is_correct": true, "explanation": "前后：指一件事从开始到结束的整段时间，与“写了三年”搭配，符合句意。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，不能与持续“三年”的时段搭配。"}, {"text": "一下子", "is_correct": false, "explanation": "语义：“一下子”表示短时间内完成，与“写了三年”的长时段相矛盾。"}], "explanations": {"马上": "语义：“马上”表示立刻，与“写了三年”的长时段相矛盾。", "前后": "前后：指一件事从开始到结束的整段时间，与“写了三年”搭配，符合句意。", "忽然": "语义：“忽然”表示突然，不能与持续“三年”的时段搭配。", "一下子": "语义：“一下子”表示短时间内完成，与“写了三年”的长时段相矛盾。"}, "sentence_index": 0, "correct_answer": "前后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家前后都有一棵大树。", "explanation": "这里的“前后”指前面和后面两处的位置，属于另一个义项，不表示一件事从头到尾的时间。"}, {"text": "教室前后各有一扇窗。", "explanation": "这里的“前后”指位置上的前后两侧，属于另一个义项，与时长无关。"}, {"text": "他三十岁前后结了婚。", "explanation": "这里的“前后”表示某个时间点的前后，属于另一个义项，不表示一件事的整段时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“去了四次”的累计次数相矛盾。"}, {"text": "前后", "is_correct": true, "explanation": "前后：一件事从头到尾的时间或次数，与“去了四次”搭配，符合句意。"}, {"text": "通常", "is_correct": false, "explanation": "搭配：“通常”表示一般情况，不与“去了四次”这种具体的累计次数搭配。"}, {"text": "猛然", "is_correct": false, "explanation": "语域：“猛然”书面色彩较重且强调突发，与“去了四次北京”的累计叙述不协调。"}], "explanations": {"立刻": "语义：“立刻”表示马上，与“去了四次”的累计次数相矛盾。", "前后": "前后：一件事从头到尾的时间或次数，与“去了四次”搭配，符合句意。", "通常": "搭配：“通常”表示一般情况，不与“去了四次”这种具体的累计次数搭配。", "猛然": "语域：“猛然”书面色彩较重且强调突发，与“去了四次北京”的累计叙述不协调。"}, "sentence_index": 6, "correct_answer": "前后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们前后排成一列。", "explanation": "这里的“前后”指位置上的前后排列，属于另一个义项，不表示一件事的时长。"}, {"text": "春节前后，火车票很难买。", "explanation": "这里的“前后”指某个节日时间点的前后，属于另一个义项，不表示一件事从头到尾的时长。"}, {"text": "这栋楼前后有一个广场。", "explanation": "这里的“前后”指位置上的两侧，属于另一个义项，与时长无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他前后的找了三次房子。", "corrected_sentence": "他前后找了三次房子。", "error_description": "助词错误：表示总次数的“前后”直接修饰动词，后面不能加“的”；正确说法是“他前后找了三次房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她前后的做了两年翻译。", "corrected_sentence": "她前后做了两年翻译。", "error_description": "助词错误：“前后”后不能加“的”，“前后的做了”不通，正确说法是“她前后做了两年翻译”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
