INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89792, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "质量单位,一千克的千分之一。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "一克是一千克的千分之一。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一千克糖可以分成一千份，每份一克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片药很轻,才零点五克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一袋盐是五百克，两袋就是一千克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房秤可以称出几克的小东西。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一枚一元硬币大约六克重。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天只吃三十克坚果。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一百多克，拿着很轻。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小金戒指只有两克。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一克水大约是一毫升。", "target_word": "克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "千克", "label": "复合"}, {"form": "毫克", "label": "复合"}], "register": "中性", "sense_fingerprint": "质量单位,等于一千克的千分之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fca3150-b75d-419f-a155-8fc7061e16d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "克", "is_correct": true, "explanation": "正确答案：克，质量单位，等于一千克的千分之一。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是口渴。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，意思是科目、科室。"}, {"text": "咳", "is_correct": false, "explanation": "ké（第二声）与 kè（第四声）声调不同，意思是咳嗽。"}, {"text": "个", "is_correct": false, "explanation": "gè 与 kè 声母不同（g 与 k），意思是个，量词。"}], "explanations": {"克": "正确答案：克，质量单位，等于一千克的千分之一。", "渴": "kě（第三声）与 kè（第四声）声调不同，意思是口渴。", "科": "kē（第一声）与 kè（第四声）声调不同，意思是科目、科室。", "咳": "ké（第二声）与 kè（第四声）声调不同，意思是咳嗽。", "个": "gè 与 kè 声母不同（g 与 k），意思是个，量词。"}, "sentence_index": null, "correct_answer": "克"}, "level_3": {"options": [{"text": "克", "is_correct": true, "explanation": "正确。“一克是一千克的千分之一”，“克”是这个单位。"}, {"text": "毫克", "is_correct": false, "explanation": "语义：毫克是千克的百万分之一，“一毫克是一千克的千分之一”数量不对。"}, {"text": "斤", "is_correct": false, "explanation": "语义：斤是五百克，“一斤是一千克的千分之一”不成立。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”不是度量单位，不能用来计量重量。"}], "explanations": {"克": "正确。“一克是一千克的千分之一”，“克”是这个单位。", "毫克": "语义：毫克是千克的百万分之一，“一毫克是一千克的千分之一”数量不对。", "斤": "语义：斤是五百克，“一斤是一千克的千分之一”不成立。", "个": "搭配：“个”不是度量单位，不能用来计量重量。"}, "sentence_index": 0, "correct_answer": "克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山上盖了一克房子。", "explanation": "这里应该用〈栋〉。克只用于称重，房子要用“栋”计量。"}, {"text": "我买了三克书。", "explanation": "这里应该用〈本〉。克是质量单位，书要用“本”来计量。"}, {"text": "她买了一克鞋。", "explanation": "这里应该用〈双〉。克只用于称重，鞋要用“双”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89792, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "克", "is_correct": true, "explanation": "正确答案：克，质量单位，等于一千克的千分之一。"}, {"text": "颗", "is_correct": false, "explanation": "kē（第一声）与 kè（第四声）声调不同，意思是颗粒，量词。"}, {"text": "各", "is_correct": false, "explanation": "gè 与 kè 声母不同（g 与 k），意思是各自、每个。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是可以。"}], "explanations": {"克": "正确答案：克，质量单位，等于一千克的千分之一。", "颗": "kē（第一声）与 kè（第四声）声调不同，意思是颗粒，量词。", "各": "gè 与 kè 声母不同（g 与 k），意思是各自、每个。", "可": "kě（第三声）与 kè（第四声）声调不同，意思是可以。"}, "sentence_index": null, "correct_answer": "克"}, "level_3": {"options": [{"text": "克", "is_correct": true, "explanation": "正确。“三十克坚果”是按重量计算的正常说法。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是容积单位，坚果按重量计，“三十升坚果”说不通。"}, {"text": "吨", "is_correct": false, "explanation": "语义：吨太大，“每天只吃三十吨”与日常饮食的语义矛盾。"}, {"text": "秒", "is_correct": false, "explanation": "语义：秒是时间单位，“每天只吃三十秒坚果”说不通。"}], "explanations": {"克": "正确。“三十克坚果”是按重量计算的正常说法。", "升": "语义：升是容积单位，坚果按重量计，“三十升坚果”说不通。", "吨": "语义：吨太大，“每天只吃三十吨”与日常饮食的语义矛盾。", "秒": "语义：秒是时间单位，“每天只吃三十秒坚果”说不通。"}, "sentence_index": 6, "correct_answer": "克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市新建了两克公园。", "explanation": "这里应该用〈座〉。克只用于称重，公园要用“座”或“个”。"}, {"text": "屋里摆着一克桌子。", "explanation": "这里应该用〈张〉。克只用于称重，桌子要用“张”计量。"}, {"text": "他买了一克电脑。", "explanation": "这里应该用〈台〉。克是质量单位，电脑要用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这枚硬币大约克六重。", "corrected_sentence": "这枚硬币大约六克重。", "error_description": "语序错误：数词要放在量词“克”前面，应说“六克重”，不能说“克六重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这袋药粉重两个克。", "corrected_sentence": "这袋药粉重两克。", "error_description": "量词错误：“克”本身是量词，前面不能再加“个”，应说“两克”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
