INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89793, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "就是，用来说一个东西是什么。", "primary_collocate": null, "pronunciation": "jí wéi", "ipa": "tɕi˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这条路的终点即为海边。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图中红色的部分即为我们学校。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“希望”即为她名字的含义。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本次会议的主题即为环境保护。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个数相加，结果即为十。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上蓝色的线即为河流。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找的人即为这位老师。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的意思即为“很高兴”。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里往东走，第一座桥即为目的地。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，考试内容即为上周学的课文。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "即为：书面的判断词，说明某物是什么，相当于“就是”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即为", "is_correct": true, "explanation": "正确：「即为」是书面判断词，说明终点就是海边，符合语境。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：「烹饪」的对象是食物，不能用来指地点。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」多跟问题、方案搭配，不能说「讨论海边」。"}, {"text": "统计", "is_correct": false, "explanation": "语义：「统计」的对象是数字、数据，不能用来描述道路的终点。"}], "explanations": {"即为": "正确：「即为」是书面判断词，说明终点就是海边，符合语境。", "烹饪": "语义：「烹饪」的对象是食物，不能用来指地点。", "讨论": "搭配：「讨论」多跟问题、方案搭配，不能说「讨论海边」。", "统计": "语义：「统计」的对象是数字、数据，不能用来描述道路的终点。"}, "sentence_index": 0, "correct_answer": "即为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从学生即为老师，十分努力。", "explanation": "这里应该用〈成为〉。「即为」表示「是」，说明身份或判断，不表示由一种状态变成另一种状态。"}, {"text": "咱俩即为在学校门口见面。", "explanation": "这里应该用〈在〉。「即为」表示判断（就是），不能表示位于某处，应说「咱俩在学校门口见面」。"}, {"text": "哇，这本书即为好看！", "explanation": "这里应该用〈真〉。「即为」是书面判断词，口语感叹不能直接接形容词，应说「这本书真好看」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即为", "is_correct": true, "explanation": "正确：「即为」说明「我们要找的人」就是「他」，符合语境。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：「清洗」的对象是物品，不能用来指我们要找的人。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」多跟车辆、船只搭配，不能说「驾驶这位老师」。"}, {"text": "修建", "is_correct": false, "explanation": "语义：「修建」的对象是房屋、道路，不能用来指人。"}], "explanations": {"即为": "正确：「即为」说明「我们要找的人」就是「他」，符合语境。", "清洗": "语义：「清洗」的对象是物品，不能用来指我们要找的人。", "驾驶": "搭配：「驾驶」多跟车辆、船只搭配，不能说「驾驶这位老师」。", "修建": "语义：「修建」的对象是房屋、道路，不能用来指人。"}, "sentence_index": 6, "correct_answer": "即为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们不即为朋友，只是同事。", "explanation": "这里应该用〈不是〉。「即为」是肯定的判断词，不能直接否定，应说「我们不是朋友，只是同事」。"}, {"text": "哎，我们迟到了，即为堵车啦！", "explanation": "这里应该用〈因为〉。「即为」是书面判断词，口语中引出原因应说「因为堵车，我们迟到了」。"}, {"text": "嘿，他每天跑步，即为健康嘛！", "explanation": "这里应该用〈为了〉。「即为」是书面判断词，不能表示目的，口语应说「他每天跑步，为了健康」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动的主题很即为友谊。", "corrected_sentence": "这次活动的主题即为友谊。", "error_description": "程度副词位置错误：「即为」是判断词，前面不能加「很」，应说「这次活动的主题即为友谊」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的目标即为是胜利。", "corrected_sentence": "我们的目标即为胜利。", "error_description": "重复判断：「即为」与「是」意思重复，只用其中一个，应说「我们的目标即为胜利」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
