INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "（书面）就是；正是。", "primary_collocate": null, "pronunciation": "jí wéi", "ipa": "tɕi˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他即为我们要找的那位医生。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这即为问题的关键所在。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天即为春节，大家都回家了。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书即为他十年前的著作。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阅读即为他最大的爱好。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年的努力即为成功的原因。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地即为当年的老车站。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事即为一切麻烦的开始。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来的客人即为我的大学老师。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国即为每个人应有的责任。", "target_word": "即为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "即为：书面语，强调“正是”，指出关键或确认身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即为", "is_correct": true, "explanation": "正确：「即为」用于确认身份，说明「他」正是我们要找的那位医生，符合语境。"}, {"text": "修建", "is_correct": false, "explanation": "语义：「修建」的对象是房屋、道路，不能用来指人。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」多跟车辆、船只搭配，不能说「驾驶那位医生」。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：「烹饪」的对象是食物，不能用来指人。"}], "explanations": {"即为": "正确：「即为」用于确认身份，说明「他」正是我们要找的那位医生，符合语境。", "修建": "语义：「修建」的对象是房屋、道路，不能用来指人。", "驾驶": "搭配：「驾驶」多跟车辆、船只搭配，不能说「驾驶那位医生」。", "烹饪": "语义：「烹饪」的对象是食物，不能用来指人。"}, "sentence_index": 0, "correct_answer": "即为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他即为在操场上跑步。", "explanation": "这里应该用〈在〉。「即为」表示判断（就是），不能表示正在进行的动作或所在位置，应说「他在操场上跑步」。"}, {"text": "他终于即为医生。", "explanation": "这里应该用〈成为〉。「即为」表示「是」，不能表示由一种状态变为另一种状态。"}, {"text": "他每天跑步，即为身体健康。", "explanation": "这里应该用〈为了〉。「即为」表示判断（就是），不能表示目的，应说「他每天跑步，为了身体健康」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即为", "is_correct": true, "explanation": "正确：「即为」说明「此地」正是当年的老车站，符合语境。"}, {"text": "研发", "is_correct": false, "explanation": "语义：「研发」的对象是产品、技术，不能用于地点。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：「编写」多跟书、程序、教材搭配，不能说「编写当年的老车站」。"}, {"text": "统计", "is_correct": false, "explanation": "语义：「统计」的对象是数字、数据，不能用来指地点。"}], "explanations": {"即为": "正确：「即为」说明「此地」正是当年的老车站，符合语境。", "研发": "语义：「研发」的对象是产品、技术，不能用于地点。", "编写": "搭配：「编写」多跟书、程序、教材搭配，不能说「编写当年的老车站」。", "统计": "语义：「统计」的对象是数字、数据，不能用来指地点。"}, "sentence_index": 6, "correct_answer": "即为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛取消了，即为下雨了。", "explanation": "这里应该用〈因为〉。「即为」表示判断或确认，不能用来引出原因。"}, {"text": "哎，我们班即为三十个人，快去吧！", "explanation": "这里应该用〈一共〉。「即为」是书面判断词，表示总数时口语应说「我们班一共三十个人」。"}, {"text": "哎呀，他即为厉害！", "explanation": "这里应该用〈很〉。「即为」是书面判断词，不能直接接形容词，口语应说「他很厉害」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工程师很即为我的哥哥。", "corrected_sentence": "这位工程师即为我的哥哥。", "error_description": "程度副词误用：「即为」是判断词，不能受程度副词「很」修饰，应去掉「很」，说「这位工程师即为我的哥哥」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师即为是我们的班主任。", "corrected_sentence": "这位老师即为我们的班主任。", "error_description": "重复判断：「即为」与「是」意思重复，只用其中一个，应说「这位老师即为我们的班主任」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
