INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "去年，也就是今年的前一年。", "primary_collocate": null, "pronunciation": "qù suì", "ipa": "tɕʰy˥˩ suei˥˩", "syllable_count": 2, "sentences": [{"text": "去岁今日，我们一起去了西湖。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去岁考上了大学，今年读大二。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁的今天，这里还是一片空地。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起去岁，今年的物价高了不少。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁秋天，奶奶搬到了我们家。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁我去过一次海边，今年想再去。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树去岁刚种，今年就开花了。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁夏天雨水少，今年河水涨了很多。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去岁学会了游泳，今年准备参加比赛。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁年底，公司搬到了新楼里。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "今年的前一年，多用于书面表达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁今日”指去年的今天，与后句“去了西湖”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是时间词，不能作“今日”前的时间状语。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能作时间状语，句中说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能作时间状语，“心情今日”说不通。"}], "explanations": {"去岁": "正确。“去岁今日”指去年的今天，与后句“去了西湖”相符。", "石头": "语义：“石头”不是时间词，不能作“今日”前的时间状语。", "身体": "搭配：“身体”不能作时间状语，句中说不通。", "心情": "搭配：“心情”不能作时间状语，“心情今日”说不通。"}, "sentence_index": 0, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去岁，我们马上就出发。", "explanation": "这里应该用〈待会儿〉。去岁指整整一年，不能与“马上”这种即刻的时间搭配。"}, {"text": "去岁晚上，我做了一个奇怪的梦。", "explanation": "这里应该用〈昨天〉。去岁指去年一整年，不能和“晚上”这种具体某一天的时段连用。"}, {"text": "去岁的会议我们马上就开。", "explanation": "这里应该用〈今天〉。去岁指整整一年，与“马上就开”这种近在眼前的安排矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁刚种”指去年刚种下，与后句“今年就开花了”相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年刚种，今年就开花”前后矛盾，树不可能先在明年种、今年开花。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示反复，不能和“刚种”这一次性的动作搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“月亮”不能被种，“月亮刚种”说不通。"}], "explanations": {"去岁": "正确。“去岁刚种”指去年刚种下，与后句“今年就开花了”相符。", "明年": "语义：“明年刚种，今年就开花”前后矛盾，树不可能先在明年种、今年开花。", "每天": "语义：“每天”表示反复，不能和“刚种”这一次性的动作搭配。", "月亮": "搭配：“月亮”不能被种，“月亮刚种”说不通。"}, "sentence_index": 6, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "等到去岁，我就要上大学了。", "explanation": "这里应该用〈明年〉。去岁指已经过去的一年，不能用于“等到……就要”这样的将来。"}, {"text": "去岁早上，我七点就起床了。", "explanation": "这里应该用〈昨天〉。去岁指去年一整年，不能和“早上”这种某一天的时段连用。"}, {"text": "我们约好去岁再见面。", "explanation": "这里应该用〈明年〉。去岁是过去的时间，不能用于约定将来的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去岁了他已经去过一次西湖。", "corrected_sentence": "去岁他已经去过一次西湖。", "error_description": "错误：“去岁”是时间名词，后面不能直接加“了”。正确：“去岁他已经去过一次西湖。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑是去岁的买的。", "corrected_sentence": "这台电脑是去岁买的。", "error_description": "错误：“去岁”后多加了“的”，“去岁的买的”不成结构。正确：“这台电脑是去岁买的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
