INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "（书面）去年。", "primary_collocate": null, "pronunciation": "qù suì", "ipa": "tɕʰy˥˩ suei˥˩", "syllable_count": 2, "sentences": [{"text": "去岁此时，我还在北京工作。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，去岁却是大旱。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去岁毕业，如今已在银行上班。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁冬天很冷，今年却暖和多了。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁一别，我们至今未见。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是去岁修好的。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁他买了房子，今年又换了工作。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与去岁相比，今年的收成好得多。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲去岁生了一场病，现已痊愈。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去岁春天，我们在江边种了几棵树。", "target_word": "去岁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语中指今年的前一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁此时”指去年的这个时候，与后句的“还在北京工作”相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是时间词，不能作“此时”的时间状语。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能充当时间状语，“身体此时”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不是时间词，句子不能说“海洋此时”。"}], "explanations": {"去岁": "正确。“去岁此时”指去年的这个时候，与后句的“还在北京工作”相符。", "月亮": "语义：“月亮”不是时间词，不能作“此时”的时间状语。", "身体": "搭配：“身体”不能充当时间状语，“身体此时”说不通。", "海洋": "语义：“海洋”不是时间词，句子不能说“海洋此时”。"}, "sentence_index": 0, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去岁中午，我在食堂吃了饺子。", "explanation": "这里应该用〈昨天〉。去岁指去年一整年，不能和“中午”这种某一天的时段连用。"}, {"text": "你去岁一定要来我家玩。", "explanation": "这里应该用〈明年〉。去岁是过去的时间，不能用于对将来的邀请。"}, {"text": "再过两个月就是去岁了。", "explanation": "这里应该用〈明年〉。去岁已经过去，不能说“再过两个月就是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去岁", "is_correct": true, "explanation": "正确。“去岁”表示去年，与后句“今年又换了工作”形成对照。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”与后句的“今年”冲突，明年买房、今年换工作的顺序说不通。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示反复，不能和一次性的买房事件搭配。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能作时间状语，也不能充当“买房”的主语。"}], "explanations": {"去岁": "正确。“去岁”表示去年，与后句“今年又换了工作”形成对照。", "明年": "语义：“明年”与后句的“今年”冲突，明年买房、今年换工作的顺序说不通。", "每天": "语义：“每天”表示反复，不能和一次性的买房事件搭配。", "心情": "搭配：“心情”不能作时间状语，也不能充当“买房”的主语。"}, "sentence_index": 6, "correct_answer": "去岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去岁下午三点，我在家看书。", "explanation": "这里应该用〈昨天〉。去岁指去年一整年，不能和“下午三点”这种某一天的时刻连用。"}, {"text": "等到去岁，我们再一起去旅行。", "explanation": "这里应该用〈明年〉。去岁是过去的时间，不能用于“等到……再”这样的将来。"}, {"text": "我打算去岁春天去江边种树。", "explanation": "这里应该用〈明年〉。去岁已经过去，不能和“打算”这种对将来的计划连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去岁了这时候，他还在老家。", "corrected_sentence": "去岁这时候，他还在老家。", "error_description": "错误：“去岁”是时间名词，后面不能直接加“了”。正确：“去岁这时候，他还在老家。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去岁的买了一辆车，现在还很新。", "corrected_sentence": "他去岁买了一辆车，现在还很新。", "error_description": "错误：“去岁”后多加了“的”，“去岁的买了一辆车”没有中心语，不成句。正确：“他去岁买了一辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
