INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89799, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "卷是把纸、布这样的东西转一转,弄成圆圆的。", "primary_collocate": null, "pronunciation": "juǎn", "ipa": "tɕɥæn˨˩˦", "syllable_count": 1, "sentences": [{"text": "他把画纸卷成了一个筒。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这块布卷起来。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把地图卷好，放进包里。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把海报卷一卷再带走。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把那张纸卷得圆圆的。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把毛巾卷好放进箱子。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把床上的毯子卷了起来。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用纸卷了一个小喇叭。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把旧地毯卷起来搬走了。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把信纸卷得很整齐。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "卷了", "label": "体标（了）"}, {"form": "卷一卷", "label": "重叠"}, {"form": "卷起来", "label": "复合"}, {"form": "捲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把纸、布等转成圆形或筒形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89799, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷（juǎn，第三声）：把纸、布等转成圆形或筒形，是本义。"}, {"text": "捐", "is_correct": false, "explanation": "juān（第一声）与 juǎn（第三声）声调不同，意思是捐献。"}, {"text": "倦", "is_correct": false, "explanation": "juàn（第四声）与 juǎn（第三声）声调不同，意思是疲倦。"}, {"text": "选", "is_correct": false, "explanation": "xuǎn 与 juǎn 声母不同（x 与 j），意思是挑选。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是剪断。"}], "explanations": {"卷": "卷（juǎn，第三声）：把纸、布等转成圆形或筒形，是本义。", "捐": "juān（第一声）与 juǎn（第三声）声调不同，意思是捐献。", "倦": "juàn（第四声）与 juǎn（第三声）声调不同，意思是疲倦。", "选": "xuǎn 与 juǎn 声母不同（x 与 j），意思是挑选。", "剪": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是剪断。"}, "sentence_index": null, "correct_answer": "卷"}, "level_3": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷：把纸转成圆筒，与“画纸卷成筒”相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是把纸扯碎，撕不出一个圆筒。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂成”多指涂上颜色，不能用来说纸变成筒形。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是书写文字，纸不能被写成一个筒。"}], "explanations": {"卷": "卷：把纸转成圆筒，与“画纸卷成筒”相符。", "撕": "语义：撕是把纸扯碎，撕不出一个圆筒。", "涂": "搭配：“涂成”多指涂上颜色，不能用来说纸变成筒形。", "写": "语义：写是书写文字，纸不能被写成一个筒。"}, "sentence_index": 0, "correct_answer": "卷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把纸卷成了一只小鸟。", "explanation": "这里应该用〈折〉。卷是把东西弯转成圆筒形，把纸折成小鸟这类形状要用〈折〉。"}, {"text": "他卷进了那场纠纷。", "explanation": "这里的“卷”是“卷入、牵连”的义项，指被牵扯进某件事，与“把纸、布弯转成圆筒”无关，不能替换为别的词。"}, {"text": "他用书把纸卷平了。", "explanation": "这里应该用〈压〉。卷指弯转成筒形，把纸弄平要用〈压〉，应说“压平”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89799, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷（juǎn，第三声）：把纸、布等转成圆形或筒形，是本义。"}, {"text": "犬", "is_correct": false, "explanation": "quǎn 与 juǎn 声母不同（q 与 j），意思是狗。"}, {"text": "转", "is_correct": false, "explanation": "zhuǎn 与 juǎn 声母不同（zh 与 j），意思是转动。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是减少。"}], "explanations": {"卷": "卷（juǎn，第三声）：把纸、布等转成圆形或筒形，是本义。", "犬": "quǎn 与 juǎn 声母不同（q 与 j），意思是狗。", "转": "zhuǎn 与 juǎn 声母不同（zh 与 j），意思是转动。", "减": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是减少。"}, "sentence_index": null, "correct_answer": "卷"}, "level_3": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷：把毯子卷起来，与“把床上的毯子……了起来”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌，毯子不能被“唱”起来。"}, {"text": "骂", "is_correct": false, "explanation": "语义：骂的对象是人，不能用来说毯子，句子读来不通。"}, {"text": "演", "is_correct": false, "explanation": "搭配：“演”搭配戏剧、角色，不搭配毯子。"}], "explanations": {"卷": "卷：把毯子卷起来，与“把床上的毯子……了起来”相符。", "唱": "语义：唱的对象是歌，毯子不能被“唱”起来。", "骂": "语义：骂的对象是人，不能用来说毯子，句子读来不通。", "演": "搭配：“演”搭配戏剧、角色，不搭配毯子。"}, "sentence_index": 6, "correct_answer": "卷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用泥卷成了一只小猴子。", "explanation": "这里应该用〈捏〉。卷是弯转成圆筒，用泥做出小猴子这种造型要用〈捏〉。"}, {"text": "他用力卷开了瓶盖。", "explanation": "这里应该用〈扭〉。卷指弯转成圆筒，拧开瓶盖这种转动要用〈扭〉。"}, {"text": "他用笔卷下了名字。", "explanation": "这里应该用〈写〉。卷不能表示书写，写下名字要用〈写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把布卷到了一个圆筒。", "corrected_sentence": "他把布卷成了一个圆筒。", "error_description": "“卷”的结果补语应为“成”，表示卷成圆筒；“卷到”不能表示结果，应为“卷成了一个圆筒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把挂图卷很整齐。", "corrected_sentence": "他把挂图卷得很整齐。", "error_description": "“卷”后的程度补语要用“得”引出，应为“卷得很整齐”；漏掉“得”后，“很”不能直接跟在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
