INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89800, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西弯转成圆筒形。", "primary_collocate": null, "pronunciation": "juǎn", "ipa": "tɕɥæn˨˩˦", "syllable_count": 1, "sentences": [{"text": "他把袖子卷到手肘上。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把裤腿卷到膝盖。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把彩纸卷成了小筒。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一张薄饼卷起来吃。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些画都卷好再放进筒里。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把作业本卷成筒，拿在手里。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把春联卷成筒，放在桌上。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把图纸卷紧，用绳子捆好。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把宣传画都卷好，交给了我。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢卷着一张大海报。", "target_word": "卷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "卷了", "label": "体标（了）"}, {"form": "卷一卷", "label": "重叠"}, {"form": "卷起来", "label": "复合"}, {"form": "捲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西弯转成圆筒形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89800, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷（juǎn，第三声）：把东西弯转成圆筒形，是本义。"}, {"text": "捐", "is_correct": false, "explanation": "juān（第一声）与 juǎn（第三声）声调不同，意思是捐献。"}, {"text": "倦", "is_correct": false, "explanation": "juàn（第四声）与 juǎn（第三声）声调不同，意思是疲倦。"}, {"text": "选", "is_correct": false, "explanation": "xuǎn 与 juǎn 声母不同（x 与 j），意思是挑选。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是剪断。"}], "explanations": {"卷": "卷（juǎn，第三声）：把东西弯转成圆筒形，是本义。", "捐": "juān（第一声）与 juǎn（第三声）声调不同，意思是捐献。", "倦": "juàn（第四声）与 juǎn（第三声）声调不同，意思是疲倦。", "选": "xuǎn 与 juǎn 声母不同（x 与 j），意思是挑选。", "剪": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是剪断。"}, "sentence_index": null, "correct_answer": "卷"}, "level_3": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷：把袖子弯转向上，与“把袖子……到手肘上”相符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、手表等，不搭配袖子。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掉，把袖子扔到手肘上说不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆是拆开或拆卸，袖子不能被拆到手肘上。"}], "explanations": {"卷": "卷：把袖子弯转向上，与“把袖子……到手肘上”相符。", "戴": "搭配：“戴”搭配帽子、手表等，不搭配袖子。", "扔": "语义：扔是抛掉，把袖子扔到手肘上说不通。", "拆": "语义：拆是拆开或拆卸，袖子不能被拆到手肘上。"}, "sentence_index": 0, "correct_answer": "卷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的头发很卷。", "explanation": "这里的“卷”是“卷曲”的义项，指头发弯曲，不是把东西弯转成圆筒形，不能替换为别的词。"}, {"text": "他用熨斗把布卷平了。", "explanation": "这里应该用〈熨〉。卷指弯转成筒形，把布弄平要用〈熨〉，应说“熨平”。"}, {"text": "他用橡皮泥卷了一只狗。", "explanation": "这里应该用〈捏〉。卷指弯转成圆筒，用橡皮泥做出小狗这种造型要用〈捏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89800, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷（juǎn，第三声）：把东西弯转成圆筒形，是本义。"}, {"text": "犬", "is_correct": false, "explanation": "quǎn 与 juǎn 声母不同（q 与 j），意思是狗。"}, {"text": "转", "is_correct": false, "explanation": "zhuǎn 与 juǎn 声母不同（zh 与 j），意思是转动。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是减少。"}], "explanations": {"卷": "卷（juǎn，第三声）：把东西弯转成圆筒形，是本义。", "犬": "quǎn 与 juǎn 声母不同（q 与 j），意思是狗。", "转": "zhuǎn 与 juǎn 声母不同（zh 与 j），意思是转动。", "减": "jiǎn 与 juǎn 韵母不同（ian 与 uan），意思是减少。"}, "sentence_index": null, "correct_answer": "卷"}, "level_3": {"options": [{"text": "卷", "is_correct": true, "explanation": "卷：把春联弯转成圆筒，与“春联卷成筒”相符。"}, {"text": "贴", "is_correct": false, "explanation": "语义：贴是粘在表面，春联不能被贴成圆筒形。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写成”搭配文字内容，不能用来说春联变成筒。"}, {"text": "画", "is_correct": false, "explanation": "语义：画是描绘图样，春联不能被画成圆筒。"}], "explanations": {"卷": "卷：把春联弯转成圆筒，与“春联卷成筒”相符。", "贴": "语义：贴是粘在表面，春联不能被贴成圆筒形。", "写": "搭配：“写成”搭配文字内容，不能用来说春联变成筒。", "画": "语义：画是描绘图样，春联不能被画成圆筒。"}, "sentence_index": 6, "correct_answer": "卷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把餐巾卷成了一只天鹅。", "explanation": "这里应该用〈折〉。卷是弯转成圆筒，把餐巾叠成天鹅这类造型要用〈折〉。"}, {"text": "她把照片卷在了墙上。", "explanation": "这里应该用〈贴〉。卷指弯转成筒，把照片固定在墙上要用〈贴〉。"}, {"text": "她用抹布把桌子卷干净了。", "explanation": "这里应该用〈擦〉。卷指弯转成圆筒，擦去桌面灰尘要用〈擦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把袖子卷了手腕上。", "corrected_sentence": "她把袖子卷到了手腕上。", "error_description": "“卷到”表示卷至某处，“到”不能省略，应为“卷到了手腕上”；漏掉“到”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把地图卷在筒，放在桌上。", "corrected_sentence": "他把地图卷成筒，放在桌上。", "error_description": "“卷”的结果要用补语“成”，应为“卷成筒”；“卷在筒”不成立，把“成”换成“在”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
