INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89801, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男孩喜欢男孩，或女孩喜欢女孩。", "primary_collocate": null, "pronunciation": "tóng xìng liàn", "ipa": "tʰʊŋ˧˥ ɕiŋ˥˩ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "他告诉朋友他是同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的人慢慢接受了同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同性恋不是病，我们要尊重他们。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟问我什么是同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的好朋友是同性恋，她一直都知道。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影讲的是同性恋的故事。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，同性恋也是一种爱。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前很多人不了解同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕家人不接受他是同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同性恋的人也想有自己的家。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "同性恋者", "label": "复合"}], "register": "中性", "sense_fingerprint": "男生喜欢男生或女生喜欢女生这种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同性恋", "is_correct": true, "explanation": "正确。“同性恋”作“是”的宾语，指喜欢同性的人，与上句“告诉朋友”的语境相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不能用来说明“他”的性取向或身份，“他是手机”说不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“是”后接身份名词时不说病症，应说“他感冒了”，不能说“他是感冒”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然事物，不能指人的身份，与“告诉朋友”的语境不合。"}], "explanations": {"同性恋": "正确。“同性恋”作“是”的宾语，指喜欢同性的人，与上句“告诉朋友”的语境相合。", "手机": "语义：“手机”是物品，不能用来说明“他”的性取向或身份，“他是手机”说不通。", "感冒": "搭配：“是”后接身份名词时不说病症，应说“他感冒了”，不能说“他是感冒”。", "河流": "语义：“河流”是自然事物，不能指人的身份，与“告诉朋友”的语境不合。"}, "sentence_index": 0, "correct_answer": "同性恋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的职业是同性恋。", "explanation": "此处误把〈同性恋〉当作工作类别来用，它表示性取向，不是〈医生〉〈教师〉那样的工作身份。"}, {"text": "我每天早上喝一杯同性恋。", "explanation": "同性恋指性取向或指人，不是饮品，不能和“喝一杯”搭配。"}, {"text": "他的爱好是同性恋。", "explanation": "此处误把〈同性恋〉当作业余活动来用，它表示性取向，不是〈游泳〉〈画画〉那类爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同性恋", "is_correct": true, "explanation": "正确。“同性恋”指喜欢同性的人或取向，放在“也是一种爱”前，语义通顺。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：“白菜”是蔬菜，不能说“白菜也是一种爱”，句意不通。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”是工具书，不是一种爱，与“也是一种爱”的语义相矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“一种爱”一般指情感，“冰箱”是家电，不能与“一种爱”搭配。"}], "explanations": {"同性恋": "正确。“同性恋”指喜欢同性的人或取向，放在“也是一种爱”前，语义通顺。", "白菜": "语义：“白菜”是蔬菜，不能说“白菜也是一种爱”，句意不通。", "词典": "语义：“词典”是工具书，不是一种爱，与“也是一种爱”的语义相矛盾。", "冰箱": "搭配：“一种爱”一般指情感，“冰箱”是家电，不能与“一种爱”搭配。"}, "sentence_index": 6, "correct_answer": "同性恋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性别是同性恋。", "explanation": "此处误把〈同性恋〉当作性别类别来用，它表示性取向，不是〈男〉〈女〉那样的性别。"}, {"text": "他得了同性恋，要去看医生。", "explanation": "同性恋不是疾病，不能说“得了同性恋”。"}, {"text": "他每天骑一辆同性恋去上班。", "explanation": "此处误把〈同性恋〉当作交通工具来用，它表示性取向，不能像〈自行车〉那样被骑去上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是同性恋，但他从来没告诉了家人。", "corrected_sentence": "他是同性恋，但他从来没告诉过家人。", "error_description": "体标误用：“没（有）”否定过去的事时，动词后不能再加“了”。表示从未有过的经历，应说“从来没告诉过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校开了一节课，讨论大家对同性恋看法。", "corrected_sentence": "学校开了一节课，讨论大家对同性恋的看法。", "error_description": "“对……的看法”中间需要“的”。应说“对同性恋的看法”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
