INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对同性产生爱慕之情的性取向，也指有这种取向的人。", "primary_collocate": null, "pronunciation": "tóng xìng liàn", "ipa": "tʰʊŋ˧˥ ɕiŋ˥˩ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "他很早就知道自己是同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同性恋是一种性取向，不是选择。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说同性恋不是一种病。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家公开说自己是同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会对同性恋的看法变了很多。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在会上谈了同性恋的权利问题。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是同性恋，但是过得很快乐。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多地方以前不接受同性恋。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究发现，同性恋在每个国家都有。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对同性恋没有看法，大家都一样。", "target_word": "同性恋", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "同性恋者", "label": "复合"}], "register": "中性", "sense_fingerprint": "喜欢同性的性取向，或有这种取向的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同性恋", "is_correct": true, "explanation": "正确。“同性恋”指对同性有爱慕之情的性取向，放在“自己是……”中语义通顺。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是物品，不能说明“自己”的性取向，“自己是黑板”说不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：“牛奶”是饮品，不能指人的性取向，与句意不合。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“是”后接性取向时不说病症，应说“自己感冒了”。"}], "explanations": {"同性恋": "正确。“同性恋”指对同性有爱慕之情的性取向，放在“自己是……”中语义通顺。", "黑板": "语义：“黑板”是物品，不能说明“自己”的性取向，“自己是黑板”说不通。", "牛奶": "语义：“牛奶”是饮品，不能指人的性取向，与句意不合。", "感冒": "搭配：“是”后接性取向时不说病症，应说“自己感冒了”。"}, "sentence_index": 0, "correct_answer": "同性恋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的招牌菜是同性恋。", "explanation": "同性恋不是菜品，不能用作招牌菜。"}, {"text": "这次比赛按同性恋分组，男队和女队分开比。", "explanation": "这里应该用〈性别〉。比赛要按性别分组，同性恋是性取向，不能作为分组的依据。"}, {"text": "他在饭店点了一盘同性恋。", "explanation": "此处误把〈同性恋〉当作菜品来用，它表示性取向或指人，不能像〈饺子〉那样用“一盘”点来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同性恋", "is_correct": true, "explanation": "正确。“同性恋”指性取向或有这种取向的人，放在“他们是……”中语义通顺。"}, {"text": "北京", "is_correct": false, "explanation": "搭配：地名不能作表示人的身份的同位成分，“他们是北京”不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：“钢笔”是文具，不能指人，与“过得很快乐”的语义不合。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：“大衣”是衣物，不能指人的身份，句子说不通。"}], "explanations": {"同性恋": "正确。“同性恋”指性取向或有这种取向的人，放在“他们是……”中语义通顺。", "北京": "搭配：地名不能作表示人的身份的同位成分，“他们是北京”不通。", "钢笔": "语义：“钢笔”是文具，不能指人，与“过得很快乐”的语义不合。", "大衣": "语义：“大衣”是衣物，不能指人的身份，句子说不通。"}, "sentence_index": 6, "correct_answer": "同性恋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身高是同性恋。", "explanation": "此处误把〈同性恋〉当作可以量出的身体特征来用，它表示性取向，不能用来描述人的身体尺寸。"}, {"text": "今天下了一场同性恋。", "explanation": "此处误把〈同性恋〉当作天气现象来用，它表示性取向，不能用来形容下雨下雪。"}, {"text": "他在窗户上贴了一张同性恋。", "explanation": "此处误把〈同性恋〉当作纸张或画作来用，它表示性取向，不能像海报那样贴在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是同性恋这件事，他一直没告诉了父母。", "corrected_sentence": "他是同性恋这件事，他一直没告诉父母。", "error_description": "体标误用：用“没”否定的动词后面不能加“了”，应说“一直没告诉父母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多家庭对同性恋的态度越来开放。", "corrected_sentence": "很多家庭对同性恋的态度越来越开放。", "error_description": "“越来越”是一个整体，表示程度逐步加深，不能省去其中的“越”，应说“越来越开放”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
