INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89803, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受伤是身体被弄坏了,会痛、会流血。", "primary_collocate": null, "pronunciation": "shòu shāng", "ipa": "ʂoʊ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "他的手受伤了，流了很多血。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不小心受伤，腿很痛。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗受伤了，一直在叫。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的人马上去了医院。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从树上掉下来，受伤了。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看到我受伤，很着急。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤的地方还在流血。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她受伤后一直躺着休息。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟玩刀的时候受伤了。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕受伤，所以不爬山。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受伤了", "label": "完成体"}, {"form": "受了伤", "label": "离合形式"}, {"form": "受过伤", "label": "经历体"}, {"form": "受傷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指身体被弄坏，伴有疼痛或流血，如手受伤了、受伤的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89803, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受伤", "is_correct": true, "explanation": "正确：受伤 shòu shāng，身体受到损害。"}, {"text": "手上", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同；“上”在“手上”中读轻声，与 shāng（第一声）声调也不同，意思是在手里。"}, {"text": "手伤", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，其余音节相同，意思是手上的伤。"}, {"text": "手生", "is_correct": false, "explanation": "shǒu 与 shòu 声调不同；shēng 与 shāng 韵母不同（eng／ang），意思是不熟练。"}, {"text": "手霜", "is_correct": false, "explanation": "shǒu 与 shòu 声调不同；shuāng 比 shāng 多一个 u 介音，意思是护手霜。"}], "explanations": {"受伤": "正确：受伤 shòu shāng，身体受到损害。", "手上": "shǒu（第三声）与 shòu（第四声）声调不同；“上”在“手上”中读轻声，与 shāng（第一声）声调也不同，意思是在手里。", "手伤": "shǒu（第三声）与 shòu（第四声）声调不同，其余音节相同，意思是手上的伤。", "手生": "shǒu 与 shòu 声调不同；shēng 与 shāng 韵母不同（eng／ang），意思是不熟练。", "手霜": "shǒu 与 shòu 声调不同；shuāng 比 shāng 多一个 u 介音，意思是护手霜。"}, "sentence_index": null, "correct_answer": "受伤"}, "level_3": {"options": [{"text": "受伤", "is_correct": true, "explanation": "正确：手受伤后流血，与句意相符。"}, {"text": "写字", "is_correct": false, "explanation": "语义：手写字与流血的伤情无关，句子说不通。"}, {"text": "冻僵", "is_correct": false, "explanation": "语义：手冻僵是失去知觉，与“流了很多血”的伤情不相符。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属等物品，不能用于人的手。"}], "explanations": {"受伤": "正确：手受伤后流血，与句意相符。", "写字": "语义：手写字与流血的伤情无关，句子说不通。", "冻僵": "语义：手冻僵是失去知觉，与“流了很多血”的伤情不相符。", "生锈": "搭配：“生锈”只用于金属等物品，不能用于人的手。"}, "sentence_index": 0, "correct_answer": "受伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天晚上他没穿外套，受伤了。", "explanation": "这里应该用〈受凉〉。没穿外套引起的是感冒，不是外伤，要用受凉。"}, {"text": "这本书的封面已经受伤了。", "explanation": "这里应该用〈破损〉。受伤只用于人或动物的身体，书的封面要用破损。"}, {"text": "他三天没吃东西，受伤了。", "explanation": "这里应该用〈挨饿〉。长时间不进食是挨饿，受伤指身体被弄坏，不能替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受伤", "is_correct": true, "explanation": "正确：“受伤的地方”指身体受伤处，与“还在流血”相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试的地方还在流血，句子说不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡的地方与“还在流血”的伤情无关，句子说不通。"}, {"text": "结冰", "is_correct": false, "explanation": "搭配：“结冰”用于水等液体，不能用于人的身体部位。"}], "explanations": {"受伤": "正确：“受伤的地方”指身体受伤处，与“还在流血”相符。", "考试": "语义：考试的地方还在流血，句子说不通。", "洗澡": "语义：洗澡的地方与“还在流血”的伤情无关，句子说不通。", "结冰": "搭配：“结冰”用于水等液体，不能用于人的身体部位。"}, "sentence_index": 6, "correct_answer": "受伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在室外站了一下午，受伤了。", "explanation": "这里应该用〈中暑〉。长时间暴晒引起的是中暑，不是外伤，受伤只指身体被弄坏。"}, {"text": "这次考试他考得很好，受伤了。", "explanation": "这里应该用〈受表扬〉。好成绩要说受表扬，受伤只表示身体受到损害。"}, {"text": "这种饮料很受伤。", "explanation": "这里应该用〈受欢迎〉。饮料受人喜爱要说受欢迎，受伤只用于身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的腿被受伤了，要休息几天。", "corrected_sentence": "他的腿受伤了，要休息几天。", "error_description": "错误在“被”：受伤是不及物动词，不能与“被”合用构成被动，正确形式为“受伤了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从楼梯上摔下来，腿受伤着。", "corrected_sentence": "他从楼梯上摔下来，腿受伤了。", "error_description": "错误在「受伤着」：受伤是一下子发生的变化，不能用表示持续的「着」，应改用「了」，说「腿受伤了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
