INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体受到损害。", "primary_collocate": null, "pronunciation": "shòu shāng", "ipa": "ʂoʊ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "他踢球时受伤了。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别受伤。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥骑车摔倒，腿受伤了。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛有三个人受伤。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的小鸟飞不起来。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤以后，不能上班。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做运动前要热身，才不会受伤。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她手受伤了，不能写字。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩的时候容易受伤。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他受伤不重。", "target_word": "受伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受伤了", "label": "完成体"}, {"form": "受了伤", "label": "离合形式"}, {"form": "受过伤", "label": "经历体"}, {"form": "受傷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指身体因意外、运动等受到损害，如踢球受伤、容易受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受伤", "is_correct": true, "explanation": "正确：受伤 shòu shāng，身体受到损害。"}, {"text": "手上", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同；“上”在“手上”中读轻声，与 shāng（第一声）声调也不同，意思是在手里。"}, {"text": "手伤", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，其余音节相同，意思是手上的伤。"}, {"text": "手生", "is_correct": false, "explanation": "shǒu 与 shòu 声调不同；shēng 与 shāng 韵母不同（eng／ang），意思是不熟练。"}, {"text": "手霜", "is_correct": false, "explanation": "shǒu 与 shòu 声调不同；shuāng 比 shāng 多一个 u 介音，意思是护手霜。"}], "explanations": {"受伤": "正确：受伤 shòu shāng，身体受到损害。", "手上": "shǒu（第三声）与 shòu（第四声）声调不同；“上”在“手上”中读轻声，与 shāng（第一声）声调也不同，意思是在手里。", "手伤": "shǒu（第三声）与 shòu（第四声）声调不同，其余音节相同，意思是手上的伤。", "手生": "shǒu 与 shòu 声调不同；shēng 与 shāng 韵母不同（eng／ang），意思是不熟练。", "手霜": "shǒu 与 shòu 声调不同；shuāng 比 shāng 多一个 u 介音，意思是护手霜。"}, "sentence_index": null, "correct_answer": "受伤"}, "level_3": {"options": [{"text": "受伤", "is_correct": true, "explanation": "正确：踢球时身体受到损害，与“他踢球时___了”相符。"}, {"text": "写字", "is_correct": false, "explanation": "语义：踢球与写字不能同时进行，句子说不通。"}, {"text": "读书", "is_correct": false, "explanation": "语义：踢球时读书与句子的语境相矛盾。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：“摔碎”多用于易碎的物品，不能用于人的身体状态。"}], "explanations": {"受伤": "正确：踢球时身体受到损害，与“他踢球时___了”相符。", "写字": "语义：踢球与写字不能同时进行，句子说不通。", "读书": "语义：踢球时读书与句子的语境相矛盾。", "摔碎": "搭配：“摔碎”多用于易碎的物品，不能用于人的身体状态。"}, "sentence_index": 0, "correct_answer": "受伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次地震使房屋受伤了。", "explanation": "这里应该用〈受损〉。受伤只用于人或动物的身体，房屋等物体遭到破坏要用受损。"}, {"text": "他的计划在比赛前受伤了。", "explanation": "这里应该用〈受挫〉。计划、事业遇到阻碍要说受挫，受伤只指身体。"}, {"text": "这场大雨使比赛的进行受伤了。", "explanation": "这里应该用〈受影响〉。比赛的进行、工作等受到作用要说受影响，受伤只用于身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受伤", "is_correct": true, "explanation": "正确：热身是为了防止身体受伤，与句意相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：热身与唱歌无关，“才不会唱歌”说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：热身的目的是防止伤害，“才不会睡觉”与句意矛盾。"}, {"text": "沉没", "is_correct": false, "explanation": "搭配：“沉没”多用于船只等，不能用于人。"}], "explanations": {"受伤": "正确：热身是为了防止身体受伤，与句意相符。", "唱歌": "语义：热身与唱歌无关，“才不会唱歌”说不通。", "睡觉": "语义：热身的目的是防止伤害，“才不会睡觉”与句意矛盾。", "沉没": "搭配：“沉没”多用于船只等，不能用于人。"}, "sentence_index": 6, "correct_answer": "受伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为违反校规而受伤了。", "explanation": "这里应该用〈受处罚〉。受伤指身体受到损害，因违反规定受到惩罚要说受处罚。"}, {"text": "他吃了变质的牛奶，受伤了。", "explanation": "这里应该用〈中毒〉。吃了有害的东西是中毒，受伤指外力造成的身体损伤。"}, {"text": "他昨晚没盖被子，受伤了。", "explanation": "这里应该用〈感冒〉。没盖被子引起的是疾病，不是外伤，受伤不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年踢球时把脚受伤了。", "corrected_sentence": "他去年踢球时脚受伤了。", "error_description": "错误在「把」：受伤是不及物动词，不能用「把」字句带出受伤部位，应删去「把」，说「脚受伤了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的弟弟在操场上被受伤了。", "corrected_sentence": "我的弟弟在操场上受伤了。", "error_description": "错误在“被”：受伤是不及物动词，不能再加“被”表示被动，正确形式为“受伤了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
