INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89805, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不动，也不说话，看着一个地方。", "primary_collocate": null, "pronunciation": "dāi", "ipa": "tai˥", "syllable_count": 1, "sentences": [{"text": "他呆呆地看着窗外。", "target_word": "呆呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，她呆站着，一句话也不说。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子呆坐在床上，看着墙。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人呆呆地望着河水。", "target_word": "呆呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈呆呆地看着照片，半天不说话。", "target_word": "呆呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我呆坐了一个小时，什么也没做。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗呆呆地看着门口。", "target_word": "呆呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她呆站在路边，看着远处的车。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人呆坐着，望着天上的云。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他呆呆地看着我，没有说话。", "target_word": "呆呆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呆呆", "label": "重叠"}], "register": "口语", "sense_fingerprint": "神情发愣、一动不动地看着一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呆", "is_correct": true, "explanation": "正确。呆（dāi，第一声）在此指一动不动地看着某处。"}, {"text": "代", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，意思是代替。"}, {"text": "开", "is_correct": false, "explanation": "kāi 与 dāi 声母不同（k 与 d），意思是打开。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 dāi 声母不同（z 与 d），意思是灾难。"}, {"text": "该", "is_correct": false, "explanation": "gāi 与 dāi 声母不同（g 与 d），意思是应该。"}], "explanations": {"呆": "正确。呆（dāi，第一声）在此指一动不动地看着某处。", "代": "dài（第四声）与 dāi（第一声）声调不同，意思是代替。", "开": "kāi 与 dāi 声母不同（k 与 d），意思是打开。", "灾": "zāi 与 dāi 声母不同（z 与 d），意思是灾难。", "该": "gāi 与 dāi 声母不同（g 与 d），意思是应该。"}, "sentence_index": null, "correct_answer": "呆"}, "level_3": {"options": [{"text": "呆呆", "is_correct": true, "explanation": "正确。“呆呆地”表示一动不动地看着窗外。"}, {"text": "哗哗", "is_correct": false, "explanation": "语义：“哗哗”形容水流声，不能修饰“看着窗外”。"}, {"text": "呼呼", "is_correct": false, "explanation": "语义：“呼呼”形容风声或快速的动作，不能修饰“看”。"}, {"text": "嗖嗖", "is_correct": false, "explanation": "搭配：“嗖嗖”形容快速移动，不能修饰“看着窗外”。"}], "explanations": {"呆呆": "正确。“呆呆地”表示一动不动地看着窗外。", "哗哗": "语义：“哗哗”形容水流声，不能修饰“看着窗外”。", "呼呼": "语义：“呼呼”形容风声或快速的动作，不能修饰“看”。", "嗖嗖": "搭配：“嗖嗖”形容快速移动，不能修饰“看着窗外”。"}, "sentence_index": 0, "correct_answer": "呆呆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈呆呆地收拾房间，很快就干完了。", "explanation": "这里应该用〈默默〉。“默默”指安静地做事，可以修饰收拾房间；“呆呆”强调一动不动地看着，不修饰做事。"}, {"text": "他呆呆地跑了三公里，满头大汗。", "explanation": "这里应该用〈飞快〉。“呆呆”表示一动不动地看着，不能修饰剧烈运动；跑步应说“飞快”。"}, {"text": "她呆呆地在操场上跳舞，跳得很开心。", "explanation": "这里应该用〈欢快〉。“呆呆”表示一动不动，与跳舞、开心矛盾；跳舞应说“欢快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89805, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "呆", "is_correct": true, "explanation": "正确。呆（dāi，第一声）在此指一动不动地看着某处。"}, {"text": "戴", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，意思是戴上。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 dāi 声母不同（送气的 t 与不送气的 d），意思是胎儿。"}, {"text": "待", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，意思是等待。"}], "explanations": {"呆": "正确。呆（dāi，第一声）在此指一动不动地看着某处。", "戴": "dài（第四声）与 dāi（第一声）声调不同，意思是戴上。", "胎": "tāi 与 dāi 声母不同（送气的 t 与不送气的 d），意思是胎儿。", "待": "dài（第四声）与 dāi（第一声）声调不同，意思是等待。"}, "sentence_index": null, "correct_answer": "呆"}, "level_3": {"options": [{"text": "呆呆", "is_correct": true, "explanation": "正确。“呆呆地”表示一动不动地看着门口。"}, {"text": "咚咚", "is_correct": false, "explanation": "语义：“咚咚”形容敲击声，不能修饰“看着门口”。"}, {"text": "哗哗", "is_correct": false, "explanation": "语义：“哗哗”形容水流声，不能修饰看的动作。"}, {"text": "噼啪", "is_correct": false, "explanation": "搭配：“噼啪”是象声词，不能用来修饰“看”。"}], "explanations": {"呆呆": "正确。“呆呆地”表示一动不动地看着门口。", "咚咚": "语义：“咚咚”形容敲击声，不能修饰“看着门口”。", "哗哗": "语义：“哗哗”形容水流声，不能修饰看的动作。", "噼啪": "搭配：“噼啪”是象声词，不能用来修饰“看”。"}, "sentence_index": 6, "correct_answer": "呆呆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他呆呆地跑进教室，大声唱歌。", "explanation": "这里应该用〈兴冲冲〉。“呆呆”表示一动不动，与跑进教室、大声唱歌矛盾；形容兴奋地进门应说“兴冲冲”。"}, {"text": "他呆呆地修着自行车，半个小时就修好了。", "explanation": "这里应该用〈熟练地〉。“呆呆”表示一动不动，与半小时修好的做事效率矛盾；形容做事熟练应说“熟练地”。"}, {"text": "她呆呆地敲着键盘，很快就写完了报告。", "explanation": "这里应该用〈认真地〉。“呆呆”表示一动不动，不修饰敲键盘这类动作；工作时应说“认真地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他呆呆得看着窗外，半天不动。", "corrected_sentence": "他呆呆地看着窗外，半天不动。", "error_description": "助词错误：修饰动词“看”的状语要用“地”，不用“得”。“得”用于补语，“呆呆得看”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈呆呆地坐过，一动不动。", "corrected_sentence": "妈妈呆呆地坐着，一动不动。", "error_description": "体助词错误：描写持续的姿态要用“着”，“过”表示曾经有过的经历。应说“呆呆地坐着”，不说“呆呆地坐过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "机灵", "is_correct": true, "explanation": "正确。机灵与“呆”相对，指反应快、头脑灵活。"}, {"text": "勤快", "is_correct": false, "explanation": "勤快指做事勤劳，与“呆”没有反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "美丽形容外貌，与“呆”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指场面吵闹，与“呆”没有反义关系。"}], "correct_answer": "机灵", "explanations": {"机灵": "正确。机灵与“呆”相对，指反应快、头脑灵活。", "勤快": "勤快指做事勤劳，与“呆”没有反义关系。", "美丽": "美丽形容外貌，与“呆”没有反义关系。", "热闹": "热闹指场面吵闹，与“呆”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "正确。聪明与“呆”相对，指理解快、反应快。"}, {"text": "干净", "is_correct": false, "explanation": "干净指整洁，与“呆”没有反义关系。"}, {"text": "富有", "is_correct": false, "explanation": "富有指有钱或内容丰富，与“呆”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜指价钱低，与“呆”没有反义关系。"}], "correct_answer": "聪明", "explanations": {"聪明": "正确。聪明与“呆”相对，指理解快、反应快。", "干净": "干净指整洁，与“呆”没有反义关系。", "富有": "富有指有钱或内容丰富，与“呆”没有反义关系。", "便宜": "便宜指价钱低，与“呆”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "发愣；反应迟钝。", "primary_collocate": null, "pronunciation": "dāi", "ipa": "tai˥", "syllable_count": 1, "sentences": [{"text": "他这个人有点呆，反应很慢。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别笑他，他只是不爱说话，并不呆。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么呆，连这个笑话都听不懂？", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子看上去呆，其实很聪明。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太呆了，问三遍才明白。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟有点呆，别人说话他总是慢半拍。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前很呆，现在聪明多了。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗看起来有点呆。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他不呆，只是需要多一点时间。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他人呆，但是做事认真。", "target_word": "呆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呆呆", "label": "重叠"}], "register": "口语", "sense_fingerprint": "人反应慢、不机灵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呆", "is_correct": true, "explanation": "正确。呆（dāi，第一声）指发愣、反应迟钝。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，意思是带子。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 dāi 声母不同（送气的 t 与不送气的 d），意思是胎儿。"}, {"text": "开", "is_correct": false, "explanation": "kāi 与 dāi 声母不同（k 与 d），意思是打开。"}, {"text": "该", "is_correct": false, "explanation": "gāi 与 dāi 声母不同（g 与 d），意思是应该。"}], "explanations": {"呆": "正确。呆（dāi，第一声）指发愣、反应迟钝。", "带": "dài（第四声）与 dāi（第一声）声调不同，意思是带子。", "胎": "tāi 与 dāi 声母不同（送气的 t 与不送气的 d），意思是胎儿。", "开": "kāi 与 dāi 声母不同（k 与 d），意思是打开。", "该": "gāi 与 dāi 声母不同（g 与 d），意思是应该。"}, "sentence_index": null, "correct_answer": "呆"}, "level_3": {"options": [{"text": "呆", "is_correct": true, "explanation": "正确。“有点呆”说的是反应慢，与后句“反应很慢”一致。"}, {"text": "敏捷", "is_correct": false, "explanation": "语义：“敏捷”指反应快，与后句“反应很慢”相矛盾。"}, {"text": "机灵", "is_correct": false, "explanation": "语义：“机灵”指反应快，与后句“反应很慢”相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”说的是身材，与反应快慢无关。"}], "explanations": {"呆": "正确。“有点呆”说的是反应慢，与后句“反应很慢”一致。", "敏捷": "语义：“敏捷”指反应快，与后句“反应很慢”相矛盾。", "机灵": "语义：“机灵”指反应快，与后句“反应很慢”相矛盾。", "高大": "体貌：“高大”说的是身材，与反应快慢无关。"}, "sentence_index": 0, "correct_answer": "呆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书法很呆，每一笔都写得很有力。", "explanation": "这里应该用〈苍劲〉。“呆”形容人反应迟钝，用于书法不合适；书法的笔力应说“苍劲”。"}, {"text": "他的手指很呆，系不好鞋带。", "explanation": "这里应该用〈笨拙〉。“笨拙”指动作不灵活，可以说手指笨拙；“呆”形容人的反应或神态，不说手指很呆。"}, {"text": "这篇文章写得很呆，没有新意。", "explanation": "这里应该用〈呆板〉。“呆板”形容文章死板、没有变化；“呆”不用来说文章写得很呆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "呆", "is_correct": true, "explanation": "正确。呆（dāi，第一声）指发愣、反应迟钝。"}, {"text": "戴", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，意思是戴上。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 dāi 声母不同（z 与 d），意思是灾难。"}, {"text": "待", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，意思是等待。"}], "explanations": {"呆": "正确。呆（dāi，第一声）指发愣、反应迟钝。", "戴": "dài（第四声）与 dāi（第一声）声调不同，意思是戴上。", "灾": "zāi 与 dāi 声母不同（z 与 d），意思是灾难。", "待": "dài（第四声）与 dāi（第一声）声调不同，意思是等待。"}, "sentence_index": null, "correct_answer": "呆"}, "level_3": {"options": [{"text": "呆", "is_correct": true, "explanation": "正确。“以前很呆”与后句“现在聪明多了”形成对比，符合句意。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面吵闹，不能用来形容以前的人，与“聪明多了”也对不上。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”说价钱，不能形容人，与“聪明多了”无关。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”指身材，与“聪明多了”无关。"}], "explanations": {"呆": "正确。“以前很呆”与后句“现在聪明多了”形成对比，符合句意。", "热闹": "语义：“热闹”指场面吵闹，不能用来形容以前的人，与“聪明多了”也对不上。", "便宜": "语义：“便宜”说价钱，不能形容人，与“聪明多了”无关。", "矮小": "体貌：“矮小”指身材，与“聪明多了”无关。"}, "sentence_index": 6, "correct_answer": "呆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的舞跳得很呆，大家都夸她。", "explanation": "这里应该用〈优美〉。“呆”形容人反应迟钝，不用来形容舞蹈；形容舞姿应说“优美”。"}, {"text": "他很呆，一学就会。", "explanation": "这里应该用〈机灵〉。“呆”表示反应迟钝，与“一学就会”矛盾；形容学得快应说“机灵”。"}, {"text": "这位老师上课很呆，学生都听得入迷。", "explanation": "这里应该用〈生动〉。“呆”形容呆板、反应慢，与学生听得入迷矛盾；形容讲课有趣应说“生动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个人呆很，做事总是慢半拍。", "corrected_sentence": "他这个人很呆，做事总是慢半拍。", "error_description": "语序错误：程度副词“很”应放在形容词“呆”前，应说“很呆”，不能说“呆很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听到消息后住呆了半天，才回过神来。", "corrected_sentence": "他听到消息后呆住了半天，才回过神来。", "error_description": "结果补语错误：“住”是“呆”的结果补语，要紧跟动词，应说“呆住了”，不能说“住呆了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
