INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89808, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上级对下级指示;要求别人必须照做。", "primary_collocate": null, "pronunciation": "mìng lìng", "ipa": "miŋ⁵¹ liŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "队长命令大家马上集合。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师命令学生把手机关掉。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军命令士兵守住这座桥。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察命令他放下手里的刀。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理命令我们今天必须交报告。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王命令人打开城门。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长命令水手们快点下船。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级命令我们明早出发，没有人敢问为什么。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令命令部队连夜离开这里。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练命令队员们绕场跑三圈。", "target_word": "命令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "命令了", "label": "体标"}, {"form": "命令过", "label": "体标"}], "register": "中性", "sense_fingerprint": "上级要求下级必须照做(动词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命令", "is_correct": true, "explanation": "正确：命令表示上级要求下级必须照做，与“大家马上集合”的语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑表示讥笑，不能用来要求大家马上集合。"}, {"text": "体谅", "is_correct": false, "explanation": "语义：体谅表示理解和宽容，不能带出要求集合的内容。"}, {"text": "恭喜", "is_correct": false, "explanation": "搭配：“恭喜”后接祝福，不能接“大家马上集合”这样的要求。"}], "explanations": {"命令": "正确：命令表示上级要求下级必须照做，与“大家马上集合”的语境相符。", "嘲笑": "语义：嘲笑表示讥笑，不能用来要求大家马上集合。", "体谅": "语义：体谅表示理解和宽容，不能带出要求集合的内容。", "恭喜": "搭配：“恭喜”后接祝福，不能接“大家马上集合”这样的要求。"}, "sentence_index": 0, "correct_answer": "命令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新兵命令将军把枪放下。", "explanation": "身份错误：〈命令〉要求发令者高于听令者，新兵不能对将军下命令，这里应该用〈请求〉。"}, {"text": "学生命令老师批改作业。", "explanation": "身份错误：〈命令〉要求发令者高于听令者，学生不能对老师下命令，这里应该用〈要求〉。"}, {"text": "警察命令他喜欢手里的刀。", "explanation": "搭配错误：〈命令〉要求对方执行可以做到的动作，〈喜欢〉是心理状态，不能用〈命令〉来要求；表达这种意思应该用〈希望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命令", "is_correct": true, "explanation": "正确：命令表示上级要求下级必须照做，与“快点下船”的指示相符。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：安慰是让人安心，不能用来要求快点下船。"}, {"text": "同情", "is_correct": false, "explanation": "语义：同情表示怜悯，不能带出快速行动的指示。"}, {"text": "悼念", "is_correct": false, "explanation": "搭配：“悼念”一般用于已故的人，不能用于正在下船的活人。"}], "explanations": {"命令": "正确：命令表示上级要求下级必须照做，与“快点下船”的指示相符。", "安慰": "语义：安慰是让人安心，不能用来要求快点下船。", "同情": "语义：同情表示怜悯，不能带出快速行动的指示。", "悼念": "搭配：“悼念”一般用于已故的人，不能用于正在下船的活人。"}, "sentence_index": 6, "correct_answer": "命令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "队员们命令教练绕场跑三圈。", "explanation": "身份错误：〈命令〉要求发令者高于听令者，队员不能对教练下命令，这里应该用〈请求〉。"}, {"text": "教练命令队员们喜欢跑步。", "explanation": "搭配错误：〈命令〉要求对方去做某个动作，〈喜欢〉是心理状态，不能被命令；这里应该用〈希望〉。"}, {"text": "这件事命令大家很吃惊。", "explanation": "词义错误：这里应该用〈使〉，表示引起某种状态；〈命令〉要求对方执行某个动作，不能用来说明人的心理感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教官把命令学员站好队。", "corrected_sentence": "教官命令学员站好队。", "error_description": "误用“把”：“命令”是动词，不能作“把”字句的宾语；正确为“教官命令学员站好队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队长命令给我们立刻出发。", "corrected_sentence": "队长命令我们立刻出发。", "error_description": "多余的“给”：“命令”后面直接带受令者时不加“给”，应说“队长命令我们立刻出发”；“命令给我们”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
