INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "周围；附近。", "primary_collocate": null, "pronunciation": "zhōu biān", "ipa": "ʈʂoʊ˥ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "我家周边很安静。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这周边有银行吗？", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周边没有人，他有点害怕。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在酒店周边吃饭很方便。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周边的东西都很贵。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去了周边的几个小镇。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周边的邻居都认识他。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司周边有地铁，上下班很方便。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在周边找一家便宜的旅馆。", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看看周边，有没有人在等你？", "target_word": "周边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "周边地区", "label": "复合"}, {"form": "周边国家", "label": "复合"}], "register": "中性", "sense_fingerprint": "身边、附近一带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周边", "is_correct": true, "explanation": "正确：周边指附近一带，“我家周边很安静”符合语义。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地机器声很大，与“很安静”矛盾。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场人多、声音大，与“很安静”矛盾。"}, {"text": "夜市", "is_correct": false, "explanation": "搭配：夜市是公共场所，不能说“我家夜市”。"}], "explanations": {"周边": "正确：周边指附近一带，“我家周边很安静”符合语义。", "工地": "语义：工地机器声很大，与“很安静”矛盾。", "菜市场": "语义：菜市场人多、声音大，与“很安静”矛盾。", "夜市": "搭配：夜市是公共场所，不能说“我家夜市”。"}, "sentence_index": 0, "correct_answer": "周边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他周边疼得厉害。", "explanation": "这里应该用〈周身〉。周身指全身，周边指附近或四周，不指身体的全部。"}, {"text": "这家店专门卖动漫周边。", "explanation": "这里“周边”指动漫、影视等的衍生商品，是另一义项，与“附近一带”的意思不符。"}, {"text": "他的周边有很多好朋友，总是帮助他。", "explanation": "这里应该用〈身边〉。周边指某个地方的附近一带，不指一个人身边的人际圈子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周边", "is_correct": true, "explanation": "正确：周边指附近一带，“周边的邻居”指住在附近的邻居，符合语义。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气不是地方，不能说“天气的邻居”。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“邻居”指住在附近的人，不能说“菜谱的邻居”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不会有住在附近的邻居。"}], "explanations": {"周边": "正确：周边指附近一带，“周边的邻居”指住在附近的邻居，符合语义。", "天气": "搭配：天气不是地方，不能说“天气的邻居”。", "菜谱": "搭配：“邻居”指住在附近的人，不能说“菜谱的邻居”。", "窗户": "语义：窗户是物件，不会有住在附近的邻居。"}, "sentence_index": 6, "correct_answer": "周边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨水把他周边淋湿了。", "explanation": "这里应该用〈周身〉。周身指全身，周边指附近，不能指身体的全部。"}, {"text": "春节周边，火车票很难买。", "explanation": "这里应该用〈前后〉。周边指空间上的附近一带，不能表示时间上的前后。"}, {"text": "这家店的动漫周边很受欢迎。", "explanation": "这里“周边”指衍生商品，是另一义项，与“附近一带”的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小区周边里有一家超市。", "corrected_sentence": "小区周边有一家超市。", "error_description": "错误：“周边”本身已表示处所，后面不能再加“里”。正确：“小区周边有一家超市”，不说“小区周边里有一家超市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家一个周边有一个公园。", "corrected_sentence": "他家周边有一个公园。", "error_description": "错误：“周边”是处所词，不能加量词“一个”计数。正确：“他家周边有一个公园”，不说“他家一个周边有一个公园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
