INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "具有某国国籍的人。", "primary_collocate": null, "pronunciation": "guó mín", "ipa": "kwo˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "领事馆会先核实伤者是否为本国国民。", "target_word": "国民", "complexity_tier": "T3", "furigana": "lǐng shì guǎn huì xiān hé shí shāng zhě shì fǒu wéi běn guó guó mín.", "sentence_source": "generated"}, {"text": "撤离时，本国国民可以凭护照出境。", "target_word": "国民", "complexity_tier": "T3", "furigana": "chè lí shí, běn guó guó mín kě yǐ píng hù zhào chū jìng.", "sentence_source": "generated"}, {"text": "出国前，本国国民应随身携带护照。", "target_word": "国民", "complexity_tier": "T3", "furigana": "chū guó qián, běn guó guó mín yīng suí shēn xié dài hù zhào.", "sentence_source": "generated"}, {"text": "凡持有本国国籍的人，都是本国国民。", "target_word": "国民", "complexity_tier": "T3", "furigana": "fán chí yǒu běn guó guó jí de rén, dōu shì běn guó guó mín.", "sentence_source": "generated"}, {"text": "这个国家的国民可以投票选总统。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外出生，却依然享有本国国民的各项权利。", "target_word": "国民", "complexity_tier": "T3", "furigana": "tā zài guó wài chū shēng, què yī rán xiǎng yǒu běn guó guó mín de gè xiàng quán lì.", "sentence_source": "generated"}, {"text": "大使馆会保护本国国民的安全。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他入籍后，与当地国民享有同等的权利。", "target_word": "国民", "complexity_tier": "T3", "furigana": "tā rù jí hòu, yǔ dāng dì guó mín xiǎng yǒu tóng děng de quán lì.", "sentence_source": "generated"}, {"text": "这个国家的国民不用办签证。", "target_word": "国民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "撤离名单上的日本国民已全部离境。", "target_word": "国民", "complexity_tier": "T3", "furigana": "chè lí míng dān shàng de rì běn guó mín yǐ quán bù lí jìng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "國民", "label": "繁体"}, {"form": "国民经济", "label": "复合"}], "register": "书面", "sense_fingerprint": "国民：具有某国国籍的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国民", "is_correct": true, "explanation": "正确：国民指具有本国国籍的人，领事馆核实伤者的国籍，符合语境。"}, {"text": "国王", "is_correct": false, "explanation": "语义：领事馆核实的是国籍，不是身份是否为君主，句子不合语境。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是证件，不是人，“是否为本国护照”不通，句子不合语境。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：“本国外国人”自相矛盾，句子不通。"}], "explanations": {"国民": "正确：国民指具有本国国籍的人，领事馆核实伤者的国籍，符合语境。", "国王": "语义：领事馆核实的是国籍，不是身份是否为君主，句子不合语境。", "护照": "语义：护照是证件，不是人，“是否为本国护照”不通，句子不合语境。", "外国人": "语义：“本国外国人”自相矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "国民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的国民很大。", "explanation": "这里应该用〈国家〉。国民指国家里的人，说国家的大小要用“国家”。"}, {"text": "他是学校的国民。", "explanation": "这里应该用〈老师〉。国民指具有某国国籍的人，学校里的教职员要说“老师”。"}, {"text": "他是一颗国民。", "explanation": "这里应该用〈名〉。“颗”用于小而圆的东西，国民指人，应该用“名”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国民", "is_correct": true, "explanation": "正确：国民指具有本国国籍的人，大使馆保护的是这些人的安全，符合语境。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不需要大使馆保护安全，句子不通。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“国籍”不是人，不能有“安全”，且“保护国籍的安全”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不需要大使馆保护，句子不通。"}], "explanations": {"国民": "正确：国民指具有本国国籍的人，大使馆保护的是这些人的安全，符合语境。", "树木": "语义：树木不需要大使馆保护安全，句子不通。", "国籍": "搭配：“国籍”不是人，不能有“安全”，且“保护国籍的安全”不成立。", "桌子": "语义：桌子不需要大使馆保护，句子不通。"}, "sentence_index": 6, "correct_answer": "国民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的国民都很喜欢吃饺子。", "explanation": "这里应该用〈家人〉。国民指具有某国国籍的人，家里的人要说“家人”。"}, {"text": "公司的国民都很努力。", "explanation": "这里应该用〈员工〉。国民指具有某国国籍的人，公司里的人要说“员工”。"}, {"text": "那辆国民开得很快。", "explanation": "这里应该用〈名〉。“辆”用于车辆，国民指人，应该用“名”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在本国出生，是本国个国民。", "corrected_sentence": "他在本国出生，是本国的国民。", "error_description": "错误：“个”放错了位置。正确：“本国的国民”。“个”不能插在定语“本国”和名词“国民”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一名本国国民了已经离境。", "corrected_sentence": "一名本国国民已经离境。", "error_description": "错误：“国民”后多了“了”。正确：“一名本国国民已经离境”。“了”不能插在“国民”和“已经”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
