INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89819, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89819, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "块是数一小块一小块东西用的字。", "primary_collocate": null, "pronunciation": "kuài", "ipa": "kʰuaɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "我想吃一块蛋糕。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给了我一块糖。", "target_word": "块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一块西瓜。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有两块饼干。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把一块巧克力分给了朋友。", "target_word": "块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里还剩下三块肉。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我早饭吃了一块面包。", "target_word": "块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蛋糕太甜了，我吃不下。", "target_word": "块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她切了一块苹果给弟弟。", "target_word": "块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子手里拿着一块饼干。", "target_word": "块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "塊", "label": "繁体"}, {"form": "一块块", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词：数小块的食物或小东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89819, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "块", "is_correct": true, "explanation": "正确：块 kuài，数成块东西的量词。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 kuài 同为第四声，只有声母不同（h／k），意思是坏。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 kuài 同为第四声，只有声母不同（g／k），意思是奇怪。"}, {"text": "帅", "is_correct": false, "explanation": "shuài 与 kuài 同为第四声，只有声母不同（sh／k），意思是英俊。"}], "explanations": {"块": "正确：块 kuài，数成块东西的量词。", "坏": "huài 与 kuài 同为第四声，只有声母不同（h／k），意思是坏。", "怪": "guài 与 kuài 同为第四声，只有声母不同（g／k），意思是奇怪。", "帅": "shuài 与 kuài 同为第四声，只有声母不同（sh／k），意思是英俊。"}, "sentence_index": null, "correct_answer": "块"}, "level_3": {"options": [{"text": "块", "is_correct": true, "explanation": "正确：“一块蛋糕”是数块状食物的说法，与句意相符。"}, {"text": "根", "is_correct": false, "explanation": "搭配：“根”用于细长条状的东西，蛋糕不是这种形状。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对物中的一个，蛋糕不能用这个量词。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书册，蛋糕不能装订成册，与“吃”的对象不合。"}], "explanations": {"块": "正确：“一块蛋糕”是数块状食物的说法，与句意相符。", "根": "搭配：“根”用于细长条状的东西，蛋糕不是这种形状。", "只": "搭配：“只”用于动物或成对物中的一个，蛋糕不能用这个量词。", "本": "语义：“本”用于书册，蛋糕不能装订成册，与“吃”的对象不合。"}, "sentence_index": 0, "correct_answer": "块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一块书。", "explanation": "这里应该用〈本〉。书要用本，块只用于一小块一小块的东西，不能用于书。"}, {"text": "桌上有一块树叶。", "explanation": "这里应该用〈片〉。树叶是薄片，要用片，块用于块状的东西。"}, {"text": "他送我一块花。", "explanation": "这里应该用〈束〉或〈朵〉。花要用束或朵，块不能用于花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "块", "is_correct": true, "explanation": "正确：“一块面包”是数块状食物的说法，与句意相符。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”用于花、云等，不用于面包。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、桥等大型固定的东西，面包不能用它。"}, {"text": "杯", "is_correct": false, "explanation": "语义：“杯”用于盛装液体的容器，面包不是液体，句子说不通。"}], "explanations": {"块": "正确：“一块面包”是数块状食物的说法，与句意相符。", "朵": "搭配：“朵”用于花、云等，不用于面包。", "座": "搭配：“座”用于山、桥等大型固定的东西，面包不能用它。", "杯": "语义：“杯”用于盛装液体的容器，面包不是液体，句子说不通。"}, "sentence_index": 6, "correct_answer": "块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子上有一块米。", "explanation": "这里应该用〈粒〉。米是颗粒状的，要用粒，块不能用于颗粒。"}, {"text": "我喝了一块水。", "explanation": "这里应该用〈杯〉。水是液体，要用杯、瓶等容器量词，块只用于块状的东西。"}, {"text": "池塘里有一块鱼。", "explanation": "这里应该用〈条〉。鱼要用条，块不能用于活的鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一个块巧克力。", "corrected_sentence": "我买了一块巧克力。", "error_description": "错误在量词重复：「块」本身已是量词，前面不能再加「个」，正确形式为「一块巧克力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
