INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89820, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词,用于块状或片状的东西。", "primary_collocate": null, "pronunciation": "kuài", "ipa": "kʰuaɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "地上有一块大石头。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了一块新手表。", "target_word": "块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上挂着一块黑板。", "target_word": "块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用一块布擦桌子。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我一块橡皮。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那块地种着很多菜。", "target_word": "块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上飘着一块白云。", "target_word": "块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶送我一块香皂。", "target_word": "块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在河边找到一块平平的石头。", "target_word": "块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把那块布放在桌子上。", "target_word": "块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "塊", "label": "繁体"}, {"form": "一块块", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词：用于块状、片状的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "块", "is_correct": true, "explanation": "正确：块 kuài，用于块状或片状东西的量词。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 kuài 同为第四声，只有声母不同（h／k），意思是坏。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 kuài 同为第四声，只有声母不同（g／k），意思是奇怪。"}, {"text": "帅", "is_correct": false, "explanation": "shuài 与 kuài 同为第四声，只有声母不同（sh／k），意思是英俊。"}], "explanations": {"块": "正确：块 kuài，用于块状或片状东西的量词。", "坏": "huài 与 kuài 同为第四声，只有声母不同（h／k），意思是坏。", "怪": "guài 与 kuài 同为第四声，只有声母不同（g／k），意思是奇怪。", "帅": "shuài 与 kuài 同为第四声，只有声母不同（sh／k），意思是英俊。"}, "sentence_index": null, "correct_answer": "块"}, "level_3": {"options": [{"text": "块", "is_correct": true, "explanation": "正确：“一块大石头”是量词搭配，与句意相符。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”用于花、云等，不用于石头。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于画、布帛等平面的东西，石头不能用它。"}, {"text": "支", "is_correct": false, "explanation": "语义：“支”多指细长的杆状物，与“大石头”的形状不符。"}], "explanations": {"块": "正确：“一块大石头”是量词搭配，与句意相符。", "朵": "搭配：“朵”用于花、云等，不用于石头。", "幅": "搭配：“幅”用于画、布帛等平面的东西，石头不能用它。", "支": "语义：“支”多指细长的杆状物，与“大石头”的形状不符。"}, "sentence_index": 0, "correct_answer": "块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一块鞋子。", "explanation": "这里应该用〈双〉。鞋子成对，要用双，块只用于块状或片状的东西，不能用于鞋子。"}, {"text": "他拿着一块照片。", "explanation": "这里应该用〈张〉。照片是平面的纸，要用张，块不适用。"}, {"text": "路边有一块电线。", "explanation": "这里应该用〈根〉。电线细长，要用根，块用于块状的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "块", "is_correct": true, "explanation": "正确：“一块白云”是量词搭配，与句意相符。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”指颗粒状的小东西，白云不是这种形状。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于带柄的物件，云没有柄，不能用这个量词。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对物中的一个，白云不能用它。"}], "explanations": {"块": "正确：“一块白云”是量词搭配，与句意相符。", "颗": "语义：“颗”指颗粒状的小东西，白云不是这种形状。", "把": "搭配：“把”用于带柄的物件，云没有柄，不能用这个量词。", "只": "搭配：“只”用于动物或成对物中的一个，白云不能用它。"}, "sentence_index": 6, "correct_answer": "块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗外落下一块雨。", "explanation": "这里应该用〈滴〉。雨要用滴计量，块不能用于雨。"}, {"text": "桌上有一块葡萄。", "explanation": "这里应该用〈串〉。葡萄成串，要用串，块不能用于葡萄。"}, {"text": "他送我一块信。", "explanation": "这里应该用〈封〉。信要用封，块不能用于信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈切了一个块奶酪。", "corrected_sentence": "妈妈切了一块奶酪。", "error_description": "错误在量词重复：「块」本身已是量词，前面不能再加「个」，正确形式为「一块奶酪」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那个块布洗干净了。", "corrected_sentence": "他把那块布洗干净了。", "error_description": "错误在量词重复：“块”前面不能再加“个”，正确形式为“那块布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
