INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89821, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "堕落是变得越来越坏，做了不好的事。", "primary_collocate": null, "pronunciation": "duò luò", "ipa": "twɔ˥˩ lwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他后来堕落了，开始偷东西。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了钱堕落，做了很多坏事。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人堕落以后，天天喝酒赌钱。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从好学生堕落成小偷。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他堕落到连朋友的钱也偷。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么好人会堕落成坏人？", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他越堕落，家里人越难过。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着儿子一天天堕落，父亲很伤心。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他堕落过一次，后来改好了。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个官员堕落了，收了很多钱。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堕落了", "label": "体标"}, {"form": "堕落过", "label": "体标"}, {"form": "堕落者", "label": "复合"}], "register": "中性", "sense_fingerprint": "行为变坏，做出偷东西、赌钱等坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堕落", "is_correct": true, "explanation": "正确。“堕落”指行为变坏、做出坏事，与后面“开始偷东西”相合。"}, {"text": "悔改", "is_correct": false, "explanation": "语义：“悔改”指认识错误并改正，与“开始偷东西”正相反，句子矛盾。"}, {"text": "长胖", "is_correct": false, "explanation": "体貌：“长胖”说身体变胖，与“偷东西”的行为无关，句子不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是清洁身体的动作，与“行为变坏”的意思不符。"}], "explanations": {"堕落": "正确。“堕落”指行为变坏、做出坏事，与后面“开始偷东西”相合。", "悔改": "语义：“悔改”指认识错误并改正，与“开始偷东西”正相反，句子矛盾。", "长胖": "体貌：“长胖”说身体变胖，与“偷东西”的行为无关，句子不通。", "洗澡": "语义：“洗澡”是清洁身体的动作，与“行为变坏”的意思不符。"}, "sentence_index": 0, "correct_answer": "堕落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学生的成绩越来越堕落了，几乎要留级。", "explanation": "这里应该用〈下降〉。堕落指人的思想或行为变坏、做出坏事，成绩变差要用〈下降〉。"}, {"text": "这个国家的经济越来越堕落了，失业的人越来越多。", "explanation": "这里应该用〈衰退〉。堕落指人变坏、做坏事，经济变差要用〈衰退〉。"}, {"text": "他的牙齿慢慢堕落了。", "explanation": "这里用“堕落”说牙齿的衰坏，“堕落”不用于身体机能的衰退，也不表示行为变坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堕落", "is_correct": true, "explanation": "正确。“堕落”指行为变坏、做出坏事，符合“越……家里人越难过”的语境。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能以“他”作主语，句子不通。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指水变成冰，人不会结冰，句子不通。"}, {"text": "殉职", "is_correct": false, "explanation": "语义：“殉职”指因公牺牲，是一次性的事，不能说“越殉职”，句子不通。"}], "explanations": {"堕落": "正确。“堕落”指行为变坏、做出坏事，符合“越……家里人越难过”的语境。", "下雨": "语义：“下雨”是天气现象，不能以“他”作主语，句子不通。", "结冰": "语义：“结冰”指水变成冰，人不会结冰，句子不通。", "殉职": "语义：“殉职”指因公牺牲，是一次性的事，不能说“越殉职”，句子不通。"}, "sentence_index": 6, "correct_answer": "堕落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苹果从树上堕落下来，砸到了他的头。", "explanation": "这里用“堕落”表示东西掉下来，现代汉语中“堕落”指行为变坏，不指东西掉落，这种用法不对。"}, {"text": "瓦片从屋顶堕落在院子里，差点砸到人。", "explanation": "这里用“堕落”表示东西掉下来，现代汉语中“堕落”指行为变坏，不指东西掉落，这种用法不对。"}, {"text": "大片积雪从屋顶堕落下来，压塌了棚子。", "explanation": "这里用“堕落”表示东西掉下来，现代汉语中“堕落”指行为变坏，不指东西掉落，这种用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快堕落了小偷。", "corrected_sentence": "他很快堕落成了小偷。", "error_description": "错误形式：“他很快堕落了小偷”。正确形式：“他很快堕落成了小偷”。“堕落”后面要用“成”引出结果，不能直接带宾语，漏掉“成”就不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个经理被堕落了，常常拿公司的钱。", "corrected_sentence": "这个经理堕落了，常常拿公司的钱。", "error_description": "错误形式：“被堕落了”。正确形式：“堕落了”。“堕落”是不及物动词，表示自己变坏，不能加“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
