INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89822, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "思想向坏的方向发展，意志消沉。", "primary_collocate": null, "pronunciation": "duò luò", "ipa": "twɔ˥˩ lwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他没有工作，思想慢慢堕落了。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了钱以后，他的思想越来越堕落。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不要让自己堕落下去。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他整天玩乐，不想工作，渐渐堕落了。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人说他堕落，他不在乎。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕自己的想法被坏人影响，慢慢堕落。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，他不想努力，只想堕落。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师担心学生意志消沉，渐渐堕落。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，人一放松就会堕落。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对未来失去了希望，思想一天天堕落。", "target_word": "堕落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堕落了", "label": "体标"}, {"form": "堕落过", "label": "体标"}, {"form": "堕落者", "label": "复合"}], "register": "中性", "sense_fingerprint": "思想、想法逐渐变坏，意志消沉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堕落", "is_correct": true, "explanation": "正确。“堕落”指思想向坏的方向发展，符合“没有工作，思想慢慢……了”的语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是身体的疾病，思想不会感冒，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指人之间的婚姻关系，思想不能结婚。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”说人或动物的身体变胖，不能用于思想。"}], "explanations": {"堕落": "正确。“堕落”指思想向坏的方向发展，符合“没有工作，思想慢慢……了”的语境。", "感冒": "语义：“感冒”是身体的疾病，思想不会感冒，句子不通。", "结婚": "语义：“结婚”指人之间的婚姻关系，思想不能结婚。", "发胖": "体貌：“发胖”说人或动物的身体变胖，不能用于思想。"}, "sentence_index": 0, "correct_answer": "堕落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树叶从枝头堕落在地上。", "explanation": "这里用“堕落”表示东西掉下来，现代汉语中“堕落”只指思想或行为变坏，不指东西掉落，这种用法不对。"}, {"text": "石头从山上堕落下来，砸坏了屋顶。", "explanation": "这里用“堕落”表示东西掉下来，现代汉语中“堕落”只指思想或行为变坏，不指东西掉落，这种用法不对。"}, {"text": "雨水从屋檐堕落在院子里。", "explanation": "这里用“堕落”表示东西掉下来，现代汉语中“堕落”只指思想或行为变坏，不指东西掉落，这种用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堕落", "is_correct": true, "explanation": "正确。“堕落”指思想向坏的方向发展、意志消沉，与“失败以后不想努力”相合。"}, {"text": "提高", "is_correct": false, "explanation": "配价：“提高”要带宾语，句中没有说明提高什么，而且与“不想努力”的语境相矛盾。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，不能表示思想变坏，句子不通。"}, {"text": "结晶", "is_correct": false, "explanation": "语义：“结晶”指物质凝结成晶体，人的想法不会结晶，句子不通。"}], "explanations": {"堕落": "正确。“堕落”指思想向坏的方向发展、意志消沉，与“失败以后不想努力”相合。", "提高": "配价：“提高”要带宾语，句中没有说明提高什么，而且与“不想努力”的语境相矛盾。", "咳嗽": "语义：“咳嗽”是身体的反应，不能表示思想变坏，句子不通。", "结晶": "语义：“结晶”指物质凝结成晶体，人的想法不会结晶，句子不通。"}, "sentence_index": 6, "correct_answer": "堕落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身体慢慢堕落了。", "explanation": "这里用“堕落”说身体或东西的衰退，“堕落”只用于人的思想、行为变坏，这种用法不对。"}, {"text": "这几年，他的视力逐渐堕落。", "explanation": "这里用“堕落”说视力下降，“堕落”不用于身体机能的衰退，这种用法不对。"}, {"text": "老房子的墙壁慢慢堕落了。", "explanation": "这里用“堕落”说墙壁的衰败，“堕落”只用于人的思想、行为变坏，这种用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有目标，思想渐渐被堕落了。", "corrected_sentence": "他没有目标，思想渐渐堕落了。", "error_description": "错误形式：“思想渐渐被堕落了”。正确形式：“思想渐渐堕落了”。“堕落”是不及物动词，不能加“被”，直接说“堕落了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近不再学习，把思想慢慢堕落了。", "corrected_sentence": "他最近不再学习，思想慢慢堕落了。", "error_description": "错误形式：“把思想慢慢堕落了”。正确形式：“思想慢慢堕落了”。“堕落”是不及物动词，不能用于“把”字句，去掉“把”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
