INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89823, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "境内是一个国家或地方的里面。", "primary_collocate": null, "pronunciation": "jìng nèi", "ipa": "tɕiŋ˥˩ neɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家境内有很多大河。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国境内有五十六个民族。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家境内，你可以用手机付钱。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河流经三个国家的境内。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的公司在中国境内有两百家店。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人在我国境内要遵守法律。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山在日本境内，不在韩国。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在法国境内降落了。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟只生活在我国境内。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家境内没有海，只有湖。", "target_word": "境内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "境内外", "label": "复合词"}], "register": "书面", "sense_fingerprint": "国家或地方的里面，与境外相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "境内", "is_correct": true, "explanation": "境内：指国家之内，与“这个国家”搭配，表示范围，符合句意。"}, {"text": "体内", "is_correct": false, "explanation": "语义：“体内”指身体里面，与“这个国家”搭配不当。"}, {"text": "校内", "is_correct": false, "explanation": "语义：“校内”指学校范围，国家不能位于学校里面。"}, {"text": "室内", "is_correct": false, "explanation": "搭配：“室内”指房屋之内，不用来指一个国家的范围。"}], "explanations": {"境内": "境内：指国家之内，与“这个国家”搭配，表示范围，符合句意。", "体内": "语义：“体内”指身体里面，与“这个国家”搭配不当。", "校内": "语义：“校内”指学校范围，国家不能位于学校里面。", "室内": "搭配：“室内”指房屋之内，不用来指一个国家的范围。"}, "sentence_index": 0, "correct_answer": "境内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子境内很暖和。", "explanation": "这里应该用〈室内〉。境内只指国家或地区的范围，不能用来指房间里面。"}, {"text": "病菌已经进入他的境内。", "explanation": "这里应该用〈体内〉。境内指国家或地区之内，不指身体里面。"}, {"text": "这所学校境内有很多树。", "explanation": "这里应该用〈校内〉。境内指国家或地区之内，不指学校的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "境内", "is_correct": true, "explanation": "境内：指国家之内，与“在日本”搭配，表示山位于日本国土之内，与“不在韩国”形成对照。"}, {"text": "海外", "is_correct": false, "explanation": "语义：“海外”指国外，与“在日本”矛盾，无法同时位于日本又在海外。"}, {"text": "海上", "is_correct": false, "explanation": "搭配：山不能位于海面上，“海上”与“山”搭配不当。"}, {"text": "车内", "is_correct": false, "explanation": "语义：“车内”指车厢里面，山不能位于车内。"}], "explanations": {"境内": "境内：指国家之内，与“在日本”搭配，表示山位于日本国土之内，与“不在韩国”形成对照。", "海外": "语义：“海外”指国外，与“在日本”矛盾，无法同时位于日本又在海外。", "海上": "搭配：山不能位于海面上，“海上”与“山”搭配不当。", "车内": "语义：“车内”指车厢里面，山不能位于车内。"}, "sentence_index": 6, "correct_answer": "境内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公园境内有很多树。", "explanation": "这里应该用〈公园内〉。境内只指国家或地区的范围，不指公园里面。"}, {"text": "我把钥匙放在包境内。", "explanation": "这里应该用〈包里〉。境内不能指包的里面，只指国家或地区之内。"}, {"text": "他坐在车境内。", "explanation": "这里应该用〈车内〉。境内只指国家或地区之内，不用于车厢里面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我国境内里有很多大河。", "corrected_sentence": "我国境内有很多大河。", "error_description": "“境内”本身已表示“里面”，后面不能再加“里”。应说“我国境内”，不能说“境内里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河我国境内流过。", "corrected_sentence": "这条河在我国境内流过。", "error_description": "表示处所时，“境内”前要有介词“在”。应说“在我国境内”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
