INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大城市是人很多、房子很多、很热闹的大地方。", "primary_collocate": null, "pronunciation": "dà chéng shì", "ipa": "ta˥˩ ʈʂʰɤŋ˧˥ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "大城市里的人很多，路上总是很热闹。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在小镇，不在大城市。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去大城市找一份工作。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的楼很高，车也很多。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次去大城市，觉得什么都新鲜。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们坐火车去了大城市玩儿。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市晚上也很亮，到处都是灯。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大城市住过三年，现在回家了。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的地铁每天都挤满了人。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不喜欢大城市，觉得太吵了。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "人多楼多、热闹的大地方，日常生活中的大城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小山村", "is_correct": false, "explanation": "语义：“小山村”人少、路上清静，与句中“人很多”“很热闹”矛盾。"}, {"text": "大城市", "is_correct": true, "explanation": "大城市指人多、房子多、热闹的大地方，与句中“人很多”“很热闹”相符。"}, {"text": "无人岛", "is_correct": false, "explanation": "语义：“无人岛”没有人居住，与“里的人很多”直接矛盾。"}, {"text": "大农村", "is_correct": false, "explanation": "搭配：“大农村”不是常用说法，农村一般不这样用“大”来修饰。"}], "explanations": {"小山村": "语义：“小山村”人少、路上清静，与句中“人很多”“很热闹”矛盾。", "大城市": "大城市指人多、房子多、热闹的大地方，与句中“人很多”“很热闹”相符。", "无人岛": "语义：“无人岛”没有人居住，与“里的人很多”直接矛盾。", "大农村": "搭配：“大农村”不是常用说法，农村一般不这样用“大”来修饰。"}, "sentence_index": 0, "correct_answer": "大城市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个大城市的人很少，大家都很安静。", "explanation": "这里应该用〈小镇〉。大城市人口多、热闹，形容人少、安静要用小镇。"}, {"text": "中国是一个人口很多、土地很大的大城市。", "explanation": "这里应该用〈国家〉。大城市指一座城市，不能用来指整个国家。"}, {"text": "大城市里一望无际，只有几只羊在吃草。", "explanation": "这里应该用〈草原〉。大城市是人口密集的城市，不会一望无际，也不会有成群的羊在吃草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深山村", "is_correct": false, "explanation": "语义：深山村位置偏僻，夜里少有灯光，与“到处都是灯”矛盾。"}, {"text": "大城市", "is_correct": true, "explanation": "大城市是灯火通明、人口密集的地方，与“晚上也很亮，到处都是灯”相符。"}, {"text": "无人区", "is_correct": false, "explanation": "语义：“无人区”没有人居住，不会“到处都是灯”。"}, {"text": "小农村", "is_correct": false, "explanation": "搭配：“小农村”不是常用说法，且农村夜里通常灯光较少。"}], "explanations": {"深山村": "语义：深山村位置偏僻，夜里少有灯光，与“到处都是灯”矛盾。", "大城市": "大城市是灯火通明、人口密集的地方，与“晚上也很亮，到处都是灯”相符。", "无人区": "语义：“无人区”没有人居住，不会“到处都是灯”。", "小农村": "搭配：“小农村”不是常用说法，且农村夜里通常灯光较少。"}, "sentence_index": 6, "correct_answer": "大城市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷在大城市种了一辈子地。", "explanation": "这里应该用〈农村〉。大城市是人口和建筑密集的城市，不适合种地，这里要用农村。"}, {"text": "大城市的街上很安静，几乎没有人走路。", "explanation": "这里应该用〈小村〉。大城市热闹、人多，描写安静、没人走路的街道要用小村。"}, {"text": "大城市里只有一条小路，路边就几间小房子。", "explanation": "这里应该用〈山村〉。大城市人多、楼多、路多，只有一条小路和几间小房子的地方要用山村。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多大城市们都有地铁，大家出行很方便。", "corrected_sentence": "很多大城市都有地铁，大家出行很方便。", "error_description": "“们”只用于指人，不能加在“大城市”后面，应为“很多大城市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去过一只大城市，那里的楼特别高。", "corrected_sentence": "我去过一座大城市，那里的楼特别高。", "error_description": "“城市”的量词应为“座”，“只”多用于动物，不能用于城市。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
