INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人口众多、经济和文化发达的大型城市。", "primary_collocate": null, "pronunciation": "dà chéng shì", "ipa": "ta˥˩ ʈʂʰɤŋ˧˥ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "北京和上海都是中国的大城市。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的经济发展很快。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市有很多博物馆和大学。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人毕业后留在大城市工作。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的房价比小城市高得多。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市里的文化活动特别丰富。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着经济发展，大城市吸引了很多人口。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大城市的交通非常发达。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的教育资源比小地方好。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大城市生活过十年，很熟悉这里。", "target_word": "大城市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "人口多、经济文化发达的大型城市，如北京、上海", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小村庄", "is_correct": false, "explanation": "语义：北京和上海是大型城市，不是“小村庄”。"}, {"text": "大城市", "is_correct": true, "explanation": "大城市指人口众多、经济和文化发达的大型城市，北京和上海符合这一定义。"}, {"text": "大学堂", "is_correct": false, "explanation": "语域：“大学堂”是旧时的说法，且北京、上海都不是学校。"}, {"text": "大农村", "is_correct": false, "explanation": "搭配：“大农村”不是常用说法，北京和上海也不是农村。"}], "explanations": {"小村庄": "语义：北京和上海是大型城市，不是“小村庄”。", "大城市": "大城市指人口众多、经济和文化发达的大型城市，北京和上海符合这一定义。", "大学堂": "语域：“大学堂”是旧时的说法，且北京、上海都不是学校。", "大农村": "搭配：“大农村”不是常用说法，北京和上海也不是农村。"}, "sentence_index": 0, "correct_answer": "大城市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个大城市经济落后，人口很少。", "explanation": "这里应该用〈村庄〉。大城市经济和人口都发达众多，描写经济落后、人口少要用村庄。"}, {"text": "农民在大城市种地，一年忙到头。", "explanation": "这里应该用〈农村〉。大城市是经济和人口中心，不会是农民种地的地方，这里要用农村。"}, {"text": "大城市的文化活动很少，大家很少去看展览。", "explanation": "这里应该用〈乡村〉。大城市文化发达，文化活动丰富，描写文化活动少要用乡村。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒岛", "is_correct": false, "explanation": "语义：“荒岛”指荒凉、没人住的小岛，与“吸引了很多人口”矛盾。"}, {"text": "大城市", "is_correct": true, "explanation": "大城市经济发达、人口众多，因此能随经济发展吸引人口，符合句意。"}, {"text": "荒村", "is_correct": false, "explanation": "语义：“荒村”指荒凉、无人居住的村落，与“吸引了很多人口”矛盾。"}, {"text": "旧军营", "is_correct": false, "explanation": "语义：旧军营不是经济和居住中心，不会因经济发展吸引人口。"}], "explanations": {"荒岛": "语义：“荒岛”指荒凉、没人住的小岛，与“吸引了很多人口”矛盾。", "大城市": "大城市经济发达、人口众多，因此能随经济发展吸引人口，符合句意。", "荒村": "语义：“荒村”指荒凉、无人居住的村落，与“吸引了很多人口”矛盾。", "旧军营": "语义：旧军营不是经济和居住中心，不会因经济发展吸引人口。"}, "sentence_index": 6, "correct_answer": "大城市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大城市的生活很慢，大家每天都很悠闲。", "explanation": "这里应该用〈小地方〉。大城市人多、节奏快，说生活很慢、大家悠闲要用小地方。"}, {"text": "这座大城市只有几户人家，周围都是田地，很少有人来。", "explanation": "这里应该用〈村子〉。大城市人口众多、建筑密集，说只有几户人家、周围都是田地要用村子。"}, {"text": "大城市的草原很大，牛羊成群。", "explanation": "这里应该用〈牧区〉。大城市是人口密集的城市，不会有大片草原和成群的牛羊，这里要用牧区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只大城市的地铁很长，几乎能到每个区。", "corrected_sentence": "这座大城市的地铁很长，几乎能到每个区。", "error_description": "“城市”的量词应为“座”，“只”不能用于城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多大城市们都有大学和博物馆，文化生活很丰富。", "corrected_sentence": "很多大城市都有大学和博物馆，文化生活很丰富。", "error_description": "“们”只用于指人，不能加在“大城市”后面，应为“很多大城市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
