INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大一是上大学的第一年。", "primary_collocate": null, "pronunciation": "dà yī", "ipa": "ta˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "我现在大一，刚进大学。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的时候，我住在学校里。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大一就学会了开车。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的课不多，我有很多空。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥去年大一，今年大二了。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我大一那年认识了现在的好朋友。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一最难的是早上起床。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大一时每天都去图书馆。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人大一的时候最想家。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我大一的时候住四个人的房间。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "上大学的第一年，指那一年的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89827, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大一", "is_correct": true, "explanation": "正确：大一指上大学的第一年，读音为 dà yī。"}, {"text": "大姨", "is_correct": false, "explanation": "dàyí（第二声）与 dàyī（第一声）第二音节声调不同，意思是母亲的姐妹。"}, {"text": "大义", "is_correct": false, "explanation": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是大道理或正义。"}, {"text": "大雨", "is_correct": false, "explanation": "dàyǔ（第三声）与 dàyī 第二音节声调不同，意思是下得很大的雨。"}, {"text": "大意", "is_correct": false, "explanation": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是粗心或主要意思。"}], "explanations": {"大一": "正确：大一指上大学的第一年，读音为 dà yī。", "大姨": "dàyí（第二声）与 dàyī（第一声）第二音节声调不同，意思是母亲的姐妹。", "大义": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是大道理或正义。", "大雨": "dàyǔ（第三声）与 dàyī 第二音节声调不同，意思是下得很大的雨。", "大意": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是粗心或主要意思。"}, "sentence_index": null, "correct_answer": "大一"}, "level_3": {"options": [{"text": "大一", "is_correct": true, "explanation": "正确：大一指大学第一年，与「刚进大学」的新生身份相符。"}, {"text": "大四", "is_correct": false, "explanation": "语义：大四是大学最后一年，与「刚进大学」矛盾。"}, {"text": "研三", "is_correct": false, "explanation": "语义：研三是研究生的第三年，刚进大学的人不可能是研三。"}, {"text": "大五", "is_correct": false, "explanation": "搭配：「大五」只用于五年制专业的第五年，不能用来指普通大学生。"}], "explanations": {"大一": "正确：大一指大学第一年，与「刚进大学」的新生身份相符。", "大四": "语义：大四是大学最后一年，与「刚进大学」矛盾。", "研三": "语义：研三是研究生的第三年，刚进大学的人不可能是研三。", "大五": "搭配：「大五」只用于五年制专业的第五年，不能用来指普通大学生。"}, "sentence_index": 0, "correct_answer": "大一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在这所中学读大一的时候，成绩一直很好。", "explanation": "这里应该用〈高一〉。大一指大学的第一年，中学的第一年要说高一，不能和「中学」一起用。"}, {"text": "这批刚进公司的人都是大一。", "explanation": "这里应该用〈新员工〉。大一只指大学的第一年级学生，不能指公司里刚进来的人。"}, {"text": "我妹妹今年六岁，刚上大一。", "explanation": "这里应该用〈一年级〉。大一指大学的第一年，六岁的孩子上的是小学一年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大一", "is_correct": true, "explanation": "正确：这里指大学第一年，作主语，符合句意。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是深夜，与「早上起床」的时间矛盾。"}, {"text": "傍晚", "is_correct": false, "explanation": "搭配：「傍晚」与「早上起床」时间不搭，不能说最难的是早上起床。"}, {"text": "下午", "is_correct": false, "explanation": "语义：下午与「早上起床」的时间相矛盾。"}], "explanations": {"大一": "正确：这里指大学第一年，作主语，符合句意。", "午夜": "语义：午夜是深夜，与「早上起床」的时间矛盾。", "傍晚": "搭配：「傍晚」与「早上起床」时间不搭，不能说最难的是早上起床。", "下午": "语义：下午与「早上起床」的时间相矛盾。"}, "sentence_index": 6, "correct_answer": "大一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我儿子今年大一，刚开始上小学。", "explanation": "这里应该用〈一年级〉。大一只指大学的第一年，小学的第一年要说一年级。"}, {"text": "他刚上初中，今年才大一。", "explanation": "这里应该用〈初一〉。大一指大学的第一年，初中的第一年要说初一。"}, {"text": "宝宝刚出生，今年大一。", "explanation": "这里应该用〈一岁〉。大一指上大学的第一年，不能用来说年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹明年就要上的大一了。", "corrected_sentence": "我妹妹明年就要上大一了。", "error_description": "错误形式「上的大一」多加了「的」。「要上大一」是动词带宾语，「上」后不能加「的」再接「大一」，应说「明年就要上大一了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
