INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大学的一年级。", "primary_collocate": null, "pronunciation": "dà yī", "ipa": "ta˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "我们学校大一有八百个学生。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的学生要上英语课。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大一读书，妹妹在大三。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的新生下周一开学。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课只有大一的人能选。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的男生住在三号楼。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚入学，是大一的学生，不是大二的。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的教室在一楼，大二的在二楼。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大一的同学今天去参观图书馆。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给大一的新生发了书。", "target_word": "大一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "大学的一年级，指年级或这一级的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大一", "is_correct": true, "explanation": "正确：大一指大学的一年级，读音为 dà yī。"}, {"text": "大姨", "is_correct": false, "explanation": "dàyí（第二声）与 dàyī（第一声）第二音节声调不同，意思是母亲的姐妹。"}, {"text": "大义", "is_correct": false, "explanation": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是大道理或正义。"}, {"text": "大雨", "is_correct": false, "explanation": "dàyǔ（第三声）与 dàyī 第二音节声调不同，意思是下得很大的雨。"}, {"text": "大意", "is_correct": false, "explanation": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是粗心或主要意思。"}], "explanations": {"大一": "正确：大一指大学的一年级，读音为 dà yī。", "大姨": "dàyí（第二声）与 dàyī（第一声）第二音节声调不同，意思是母亲的姐妹。", "大义": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是大道理或正义。", "大雨": "dàyǔ（第三声）与 dàyī 第二音节声调不同，意思是下得很大的雨。", "大意": "dàyì（第四声）与 dàyī 第二音节声调不同，意思是粗心或主要意思。"}, "sentence_index": null, "correct_answer": "大一"}, "level_3": {"options": [{"text": "大一", "is_correct": true, "explanation": "正确：这里指大学一年级这一群学生，是句子的主语。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是钱，不能「有八百个学生」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能拥有学生，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是年级或场所，不能说「考试有八百个学生」。"}], "explanations": {"大一": "正确：这里指大学一年级这一群学生，是句子的主语。", "学费": "语义：学费是钱，不能「有八百个学生」。", "天气": "语义：天气不能拥有学生，句意不通。", "考试": "语义：考试不是年级或场所，不能说「考试有八百个学生」。"}, "sentence_index": 0, "correct_answer": "大一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟是大一的学生，还在中学读书。", "explanation": "这里应该用〈高一〉。大一指大学一年级，中学一年级要说高一。"}, {"text": "这批刚调到部队的人都是大一。", "explanation": "这里应该用〈新兵〉。大一只指大学的一年级，不能指部队里刚来的人。"}, {"text": "我妹妹今年六岁，刚上大一。", "explanation": "这里应该用〈一年级〉。大一指大学一年级，六岁的孩子上的是小学一年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大一", "is_correct": true, "explanation": "正确：这里指大学一年级，与后半句「不是大二的」形成对比。"}, {"text": "大二", "is_correct": false, "explanation": "语义：前半句填「大二」，就与后半句「不是大二的」直接矛盾。"}, {"text": "大三", "is_correct": false, "explanation": "语义：大三是大学第三年，与「刚入学」矛盾，不能作这里的年级。"}, {"text": "大四", "is_correct": false, "explanation": "语义：大四是大学最后一年，与「刚入学」矛盾。"}], "explanations": {"大一": "正确：这里指大学一年级，与后半句「不是大二的」形成对比。", "大二": "语义：前半句填「大二」，就与后半句「不是大二的」直接矛盾。", "大三": "语义：大三是大学第三年，与「刚入学」矛盾，不能作这里的年级。", "大四": "语义：大四是大学最后一年，与「刚入学」矛盾。"}, "sentence_index": 6, "correct_answer": "大一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹上小学，今年大一了。", "explanation": "这里应该用〈一年级〉。大一指大学的第一年，小学的第一年要说一年级。"}, {"text": "他刚上初中，今年才大一。", "explanation": "这里应该用〈初一〉。大一指大学的第一年，初中的第一年要说初一。"}, {"text": "宝宝刚出生，今年大一。", "explanation": "这里应该用〈一岁〉。大一指大学一年级，不能用来说年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大一地同学都住在学校里。", "corrected_sentence": "大一的同学都住在学校里。", "error_description": "错误：「大一地同学」用错了助词。修饰名词「同学」要用「的」，「地」用来修饰动词。应说「大一的同学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
