INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大部分是一大半,多的那一些。", "primary_collocate": null, "pronunciation": "dà bù fen", "ipa": "ta˥˩ pu˥˩ fən", "syllable_count": 3, "sentences": [{"text": "班里大部分同学都喜欢踢足球。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大部分人早上坐地铁去上班。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果大部分已经坏了。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大部分学生通过了这次考试。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里大部分东西都在打折。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司大部分员工住在附近。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大部分时候他都在家看书。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子里的书，大部分是我买的。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业大部分我已经做完了。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加会议的大部分是老师。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "一群人或事物中超过一半的多数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大部分", "is_correct": true, "explanation": "“大部分”指一大半，修饰“同学”，与“都喜欢踢足球”相符，是唯一符合句意的词。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地点，不能修饰“同学”表示数量，“班里厨房同学”不成立。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教具，不能修饰“同学”表示数量，“班里黑板同学”不成立。"}, {"text": "对象", "is_correct": false, "explanation": "搭配：“对象”不能用来修饰“同学”表示数量，“班里对象同学”不成立。"}], "explanations": {"大部分": "“大部分”指一大半，修饰“同学”，与“都喜欢踢足球”相符，是唯一符合句意的词。", "厨房": "语义：“厨房”是地点，不能修饰“同学”表示数量，“班里厨房同学”不成立。", "黑板": "语义：“黑板”是教具，不能修饰“同学”表示数量，“班里黑板同学”不成立。", "对象": "搭配：“对象”不能用来修饰“同学”表示数量，“班里对象同学”不成立。"}, "sentence_index": 0, "correct_answer": "大部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里大部分同学一个也没有通过考试。", "explanation": "此句中的“大部分”表示超过一半，与“一个也没有”（零）矛盾。改为“班里没有同学通过考试”或“班里大部分同学没有通过考试”即可成立。"}, {"text": "班里大部分同学正好一半通过了考试。", "explanation": "此句中的“大部分”表示超过一半，与“正好一半”（恰好二分之一）矛盾。本义项指多数，不能用来表示恰好一半，应该用〈半数〉。"}, {"text": "班里大部分同学每个人都通过了考试。", "explanation": "此句中的“大部分”表示超过一半，而“每个人都”表示全体，二者矛盾。本义项指多数而非全体，应该用〈全体〉来表示全部人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大部分", "is_correct": true, "explanation": "“大部分时候”指多数时间，与“他都在家看书”的习惯相符，是唯一符合句意的词。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：“片刻”指很短的时间，与“都在家看书”这种长时段的习惯矛盾。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”指极短的时刻，无法与“都在家看书”这种常态搭配。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”不表示时间段，与“时候”无法搭配，“名字时候”不成立。"}], "explanations": {"大部分": "“大部分时候”指多数时间，与“他都在家看书”的习惯相符，是唯一符合句意的词。", "片刻": "语义：“片刻”指很短的时间，与“都在家看书”这种长时段的习惯矛盾。", "瞬间": "语义：“瞬间”指极短的时刻，无法与“都在家看书”这种常态搭配。", "名字": "搭配：“名字”不表示时间段，与“时候”无法搭配，“名字时候”不成立。"}, "sentence_index": 6, "correct_answer": "大部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些饼干大部分被我吃光了，一块也没剩。", "explanation": "这里应该用〈全部〉。“一块也没剩”表示全部吃完，“大部分”只表示超过一半，二者矛盾。"}, {"text": "这些苹果大部分只有一个是坏的。", "explanation": "此句中的“大部分”表示超过一半，而“只有一个”表示数量极少，二者矛盾。这里应该用〈个别〉，表示少数几个。"}, {"text": "班里大部分同学迟到的人数正好为零。", "explanation": "此句中的“大部分”表示超过一半，而“正好为零”表示没有人迟到，二者矛盾。改为“班里没有人迟到”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班大部分个同学都爱打篮球。", "corrected_sentence": "我们班大部分同学都爱打篮球。", "error_description": "“大部分”后面直接接名词，不能再加量词“个”。错误形式是“大部分个同学”，正确形式是“大部分同学”，因为“大部分”本身不需要量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛大部分选手的都来自外地。", "corrected_sentence": "这次比赛大部分选手都来自外地。", "error_description": "错误：“的”放在了“选手”后面（“选手的都”），句子不通。“大部分”后面可以接“的”（大部分的选手都来自外地），但这里应去掉“选手”后的“的”，即“大部分选手都来自外地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
