INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体中占比较大的部分。", "primary_collocate": null, "pronunciation": "dà bù fen", "ipa": "ta˥˩ pu˥˩ fən", "syllable_count": 3, "sentences": [{"text": "他把工资的大部分存进了银行。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的大部分地方下了雪。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把大部分时间花在工作上。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林的大部分已经变成了农田。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的大部分内容我都看懂了。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园的大部分种着各种花草。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的收入大部分用来付房租。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水的大部分来自山上的雪。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一天的大部分时间都在路上。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的大部分是讲环境问题的。", "target_word": "大部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "一个整体（金额、时间、内容、地域）中占比最大的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大部分", "is_correct": true, "explanation": "“大部分”指整体中占比较大的部分，修饰“工资”，与“存进银行”搭配，是唯一符合句意的词。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“存进银行”的对象应是钱款，“时间”不能存入银行。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌特征，不能说“工资的身高”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是钱款，与“工资”的数量含义相矛盾。"}], "explanations": {"大部分": "“大部分”指整体中占比较大的部分，修饰“工资”，与“存进银行”搭配，是唯一符合句意的词。", "时间": "搭配：“存进银行”的对象应是钱款，“时间”不能存入银行。", "身高": "体貌：“身高”是人的体貌特征，不能说“工资的身高”。", "颜色": "语义：“颜色”不是钱款，与“工资”的数量含义相矛盾。"}, "sentence_index": 0, "correct_answer": "大部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的大部分地方只有一处下了雪。", "explanation": "此句中的“大部分”表示超过一半，而“只有一处”表示数量极少，二者矛盾。本义项指整体中占比较大的部分，不能与极少的数量搭配，这里应该用〈个别〉。"}, {"text": "森林的大部分正好占了总面积的一半。", "explanation": "此句中的“大部分”表示超过一半，而“正好占一半”表示恰好二分之一，二者矛盾。这里应该用〈一半〉。"}, {"text": "这本书的大部分内容全部看完了。", "explanation": "此句中的“大部分”表示超过一半，而“全部看完”表示全体，二者矛盾。改为“这本书的大部分内容我看完了”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大部分", "is_correct": true, "explanation": "“大部分”表示大半，修饰“收入”，说明收入的多数用来付房租，是唯一符合句意的词。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”不是可以用来付房租的东西，与“收入”不相容。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”不是钱款，不能说“收入的家具”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用于修饰“收入”。"}], "explanations": {"大部分": "“大部分”表示大半，修饰“收入”，说明收入的多数用来付房租，是唯一符合句意的词。", "性格": "语义：“性格”不是可以用来付房租的东西，与“收入”不相容。", "家具": "语义：“家具”不是钱款，不能说“收入的家具”。", "身材": "体貌：“身材”指人的体形，不能用于修饰“收入”。"}, "sentence_index": 6, "correct_answer": "大部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把工资大部分都花光了，一分钱也没剩。", "explanation": "这里应该用〈全部〉。“一分钱也没剩”表示全部花完，“大部分”只表示超过一半，二者矛盾。"}, {"text": "这篇文章的大部分只讲了一句话。", "explanation": "此句中的“大部分”表示超过一半，而“只讲了一句话”表示内容极少，二者矛盾。这里应该用〈一小部分〉，表示占比很小的部分。"}, {"text": "他把工资的大部分存进了银行，正好全部都存完了。", "explanation": "此句中的“大部分”表示超过一半，而“全部都存完了”表示全额，二者矛盾。这里应该用〈全额〉，表示整笔金额都被处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天把大部分个时间用来读书。", "corrected_sentence": "他每天把大部分时间用来读书。", "error_description": "“大部分”后面直接接名词“时间”，不能再加量词“个”。错误形式是“大部分个时间”，正确形式是“大部分时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的大部分都经费来自政府。", "corrected_sentence": "学校的大部分经费来自政府。", "error_description": "“都”的位置错误。“大部分”应直接修饰名词“经费”，“都”不应插在“大部分”与“经费”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
