INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89831, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "从而是说前面做了,所以得到了后面的结果。", "primary_collocate": null, "pronunciation": "cóng ér", "ipa": "tsʰʊŋ˧˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "他每天锻炼身体，从而变得更健康。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司改进了服务，从而赢得了更多客户。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认真复习功课，从而取得了好成绩。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书可以开阔眼界，从而提高写作水平。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府修了新路，从而方便了村民出行。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们减少用电，从而节约了不少钱。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学会了控制情绪，从而改善了和同事的关系。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店降低了价格，从而吸引了很多年轻人。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师换了教法，从而让学生更感兴趣。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水能促进代谢，从而帮助身体排出废物。", "target_word": "从而", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "连词，前面的做法带来后面的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从而", "is_correct": true, "explanation": "从而：表示前面的做法带来后面的结果，符合句意。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“却、也”等呼应，这里没有相应的词，且不能表示结果。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与“锻炼身体→变得更健康”的因果关系相反。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，句意变成锻炼之后却不健康，与原意不符。"}], "explanations": {"从而": "从而：表示前面的做法带来后面的结果，符合句意。", "虽然": "搭配：“虽然”要与“却、也”等呼应，这里没有相应的词，且不能表示结果。", "但是": "语义：“但是”表示转折，与“锻炼身体→变得更健康”的因果关系相反。", "然而": "语义：“然而”表示转折，句意变成锻炼之后却不健康，与原意不符。"}, "sentence_index": 0, "correct_answer": "从而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边做饭，从而听了一会儿音乐。", "explanation": "这里应该用〈同时〉。“同时”表示两件事一起进行；“从而”要求前一行为带来后一结果，做饭并不导致听音乐，所以不能用“从而”。"}, {"text": "我吃完饭，从而去看了电视。", "explanation": "这里应该用〈然后〉。“然后”只表示先后顺序；“从而”要求前一行为带来后一结果，吃饭和看电视之间没有这种因果关系。"}, {"text": "他会弹钢琴，从而会唱歌。", "explanation": "这里应该用〈并且〉。“并且”连接并列的两项能力；“从而”不表示并列，不能说“会弹钢琴，从而会唱歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从而", "is_correct": true, "explanation": "从而：表示前面的做法带来后面的结果，符合句意。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与“却、也”等呼应，这里后面没有相应的词，句子不成立。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，与“学会控制情绪→改善关系”的顺承关系相反。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”用于补充理由，句中前后并非补充关系，读起来不通。"}], "explanations": {"从而": "从而：表示前面的做法带来后面的结果，符合句意。", "尽管": "搭配：“尽管”要与“却、也”等呼应，这里后面没有相应的词，句子不成立。", "可是": "语义：“可是”表示转折，与“学会控制情绪→改善关系”的顺承关系相反。", "况且": "语义：“况且”用于补充理由，句中前后并非补充关系，读起来不通。"}, "sentence_index": 6, "correct_answer": "从而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他复习得很认真，从而没有考上大学。", "explanation": "这里应该用〈但是〉。“但是”表示转折，前后意思相反；“从而”只承接顺向的结果，不能表示转折。"}, {"text": "你要早点睡，从而明天会起不来。", "explanation": "这里应该用〈否则〉。“否则”表示不这样做就会出现某种后果；“从而”只表示顺承的结果，不能引出假设的后果。"}, {"text": "他不但没道歉，从而生气了。", "explanation": "这里应该用〈反而〉。“反而”表示与预期相反；“从而”不能表示与预期相反的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他认真听讲，所以从而理解了课文。", "corrected_sentence": "他认真听讲，从而理解了课文。", "error_description": "“所以”和“从而”都表示结果，二者叠用属于重复、不通顺；应去掉“所以”，说“他认真听讲，从而理解了课文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天练习书法，所以从而写出了漂亮的字。", "corrected_sentence": "他每天练习书法，从而写出了漂亮的字。", "error_description": "错误：“所以”与“从而”都表示结果，二者叠用重复、不通顺。正确：应去掉“所以”，说“他每天练习书法，从而写出了漂亮的字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
