INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89833, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大晚上是说天已经黑了很久的深夜。", "primary_collocate": null, "pronunciation": "dà wǎn shang", "ipa": "ta˥˩ wan˨˩ ʂaŋ", "syllable_count": 3, "sentences": [{"text": "大晚上的，路上已经没有车了。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大晚上的，楼里特别安静。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我大晚上才到家。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大晚上，街上的店都关门了。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大晚上还在写作业。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大晚上出门，一定要小心。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大晚上的，窗外黑黑的。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大晚上，孩子们早就睡着了。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈大晚上还在厨房里忙着。", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大晚上的，你去哪儿了？", "target_word": "大晚上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "天黑了很久的深夜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89833, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大晚上", "is_correct": true, "explanation": "正确：“大晚上的，路上已经没有车了”指天黑很久的深夜，与句意相符。"}, {"text": "大白天", "is_correct": false, "explanation": "语义：白天路上有车，“大白天的，路上已经没有车了”与常识矛盾。"}, {"text": "早高峰", "is_correct": false, "explanation": "语义：早高峰是上班时间，路上车最多，与“已经没有车了”矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是白天，路上通常车来车往，与「已经没有车了」的描述矛盾。"}], "explanations": {"大晚上": "正确：“大晚上的，路上已经没有车了”指天黑很久的深夜，与句意相符。", "大白天": "语义：白天路上有车，“大白天的，路上已经没有车了”与常识矛盾。", "早高峰": "语义：早高峰是上班时间，路上车最多，与“已经没有车了”矛盾。", "中午": "语义：中午是白天，路上通常车来车往，与「已经没有车了」的描述矛盾。"}, "sentence_index": 0, "correct_answer": "大晚上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们将在大晚上举行开幕式。", "explanation": "语域：〈大晚上〉是口语，正式场合应说〈晚上〉。"}, {"text": "本次会议定于大晚上在礼堂召开，请各位准时出席。", "explanation": "语域：〈大晚上〉是口语，正式通知应说〈晚上〉或〈夜间〉。"}, {"text": "这份合同规定，员工大晚上不得离岗。", "explanation": "语域：〈大晚上〉是口语，合同等正式文本应说〈夜间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大晚上", "is_correct": true, "explanation": "正确：“大晚上的，窗外黑黑的”描述天黑很久的深夜，与句意相符。"}, {"text": "上午", "is_correct": false, "explanation": "语义：上午阳光充足，与“窗外黑黑的”的描述冲突。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午的天色明亮，不可能“窗外黑黑的”，与句意矛盾。"}, {"text": "午间", "is_correct": false, "explanation": "语义：午间即中午，阳光明亮，与「窗外黑黑的」的描述冲突。"}], "explanations": {"大晚上": "正确：“大晚上的，窗外黑黑的”描述天黑很久的深夜，与句意相符。", "上午": "语义：上午阳光充足，与“窗外黑黑的”的描述冲突。", "正午": "语义：正午的天色明亮，不可能“窗外黑黑的”，与句意矛盾。", "午间": "语义：午间即中午，阳光明亮，与「窗外黑黑的」的描述冲突。"}, "sentence_index": 6, "correct_answer": "大晚上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院规定，病人大晚上不得探视。", "explanation": "语域：〈大晚上〉是口语，医院规定等正式文本应说〈夜间〉。"}, {"text": "学校把期末考试定在大晚上。", "explanation": "语域：〈大晚上〉是口语，安排正式考试应说〈晚上〉。"}, {"text": "据报道，该市领导大晚上召开了紧急会议。", "explanation": "语域：〈大晚上〉是口语，新闻报道等书面语应说〈夜间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很大晚上的，他还在看书。", "corrected_sentence": "大晚上的，他还在看书。", "error_description": "程度副词错误：“很”不能修饰时间词〈大晚上〉，应说“大晚上的”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "都大晚上，孩子们还在外面玩。", "corrected_sentence": "都大晚上了，孩子们还在外面玩。", "error_description": "漏字错误：〈都…了〉表示时间已经很晚，句末“了”不能省略，应说“都大晚上了”，不说“都大晚上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
