INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "担心某种不好的事会发生。", "primary_collocate": null, "pronunciation": "pà", "ipa": "pʰa˥˩", "syllable_count": 1, "sentences": [{"text": "我怕你听不懂,所以说得很慢。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快走吧,我怕会迟到。", "target_word": "怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "带上雨伞,我怕下午会下雨。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕妈妈难过,没有说自己生病了。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我怕忘了,所以把电话号码写在手上。", "target_word": "怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上车多,我们早点走,怕堵车。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怕孩子着凉,给他多穿了一件衣服。", "target_word": "怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕他不高兴,就没有告诉他。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜太少,我怕大家吃不饱。", "target_word": "怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你拿着地图吧,我怕你找不到路。", "target_word": "怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不怕", "label": "否定"}, {"form": "怕了", "label": "体标"}, {"form": "害怕", "label": "复合"}, {"form": "可怕", "label": "复合"}], "register": "中性", "sense_fingerprint": "怕:担心某种不好的事会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怕", "is_correct": true, "explanation": "pà（第四声）是“怕”，指担心某种不好的事会发生。"}, {"text": "爬", "is_correct": false, "explanation": "pá（第二声）与 pà（第四声）声调不同，意思是攀爬。"}, {"text": "霸", "is_correct": false, "explanation": "bà（第四声）与 pà 声母不同，意思是称霸、霸占。"}, {"text": "趴", "is_correct": false, "explanation": "pā（第一声）与 pà 声调不同，意思是伏在某处。"}], "explanations": {"怕": "pà（第四声）是“怕”，指担心某种不好的事会发生。", "爬": "pá（第二声）与 pà（第四声）声调不同，意思是攀爬。", "霸": "bà（第四声）与 pà 声母不同，意思是称霸、霸占。", "趴": "pā（第一声）与 pà 声调不同，意思是伏在某处。"}, "sentence_index": null, "correct_answer": "怕"}, "level_3": {"options": [{"text": "怕", "is_correct": true, "explanation": "正确：“怕”表示担心听不懂这件坏事会发生，与后句“说得很慢”相合。"}, {"text": "希望", "is_correct": false, "explanation": "语义：“希望”表示期盼，与后句“说得很慢”的原因矛盾。"}, {"text": "庆幸", "is_correct": false, "explanation": "语义：“庆幸”表示为好事高兴，与为照顾对方而放慢语速的做法不合。"}, {"text": "期盼", "is_correct": false, "explanation": "语域：“期盼”语体庄重，多用于重大愿望，不用于这里的日常说话。"}], "explanations": {"怕": "正确：“怕”表示担心听不懂这件坏事会发生，与后句“说得很慢”相合。", "希望": "语义：“希望”表示期盼，与后句“说得很慢”的原因矛盾。", "庆幸": "语义：“庆幸”表示为好事高兴，与为照顾对方而放慢语速的做法不合。", "期盼": "语域：“期盼”语体庄重，多用于重大愿望，不用于这里的日常说话。"}, "sentence_index": 0, "correct_answer": "怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我怕你平安回来，希望你早点到家。", "explanation": "这里应该用〈盼望〉。怕表示担心不好的事会发生，盼着好事发生要用盼望。"}, {"text": "我怕明天天气很好，就打算去郊游。", "explanation": "这里应该用〈希望〉。怕表示担心不好的事会发生，希望好天气要用希望。"}, {"text": "妈妈很怕我考得好，每次都给我买礼物。", "explanation": "这里应该用〈期待〉。怕表示担心不好的事会发生，考得好是好事，要用期待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89836, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "怕", "is_correct": true, "explanation": "pà（第四声）是“怕”，指担心某种不好的事会发生。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）与 pà 声母不同，意思是爸爸。"}, {"text": "罢", "is_correct": false, "explanation": "bà（第四声）与 pà 声母不同，意思是停止、罢了。"}, {"text": "扒", "is_correct": false, "explanation": "pá（第二声）与 pà 声调不同，意思是用手拨开或抓取。"}], "explanations": {"怕": "pà（第四声）是“怕”，指担心某种不好的事会发生。", "爸": "bà（第四声）与 pà 声母不同，意思是爸爸。", "罢": "bà（第四声）与 pà 声母不同，意思是停止、罢了。", "扒": "pá（第二声）与 pà 声调不同，意思是用手拨开或抓取。"}, "sentence_index": null, "correct_answer": "怕"}, "level_3": {"options": [{"text": "怕", "is_correct": true, "explanation": "正确：“怕”表示担心孩子着凉这件坏事会发生，与后句“多穿了一件衣服”相合。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”表示厌烦，与后句给孩子多穿衣服的照顾相矛盾。"}, {"text": "祈求", "is_correct": false, "explanation": "语域：“祈求”语体庄重，多用于向他人求助，与这里的照顾语境不合。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”表示期待，与为孩子多穿衣服的做法矛盾。"}], "explanations": {"怕": "正确：“怕”表示担心孩子着凉这件坏事会发生，与后句“多穿了一件衣服”相合。", "嫌": "语义：“嫌”表示厌烦，与后句给孩子多穿衣服的照顾相矛盾。", "祈求": "语域：“祈求”语体庄重，多用于向他人求助，与这里的照顾语境不合。", "盼望": "语义：“盼望”表示期待，与为孩子多穿衣服的做法矛盾。"}, "sentence_index": 6, "correct_answer": "怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我怕你找到了路，所以放心了。", "explanation": "这里应该用〈庆幸〉。怕表示担心坏事会发生，对已经发生的好事要用庆幸。"}, {"text": "老板怕我拿到了奖金，所以很早就准备好了红包。", "explanation": "这里应该用〈期望〉。怕表示担心不好的事会发生，拿到奖金是好事，不能用怕。"}, {"text": "我怕这次面试通过了，所以今天特别高兴。", "explanation": "这里应该用〈庆幸〉。“怕”表示担心坏事会发生，面试通过是好事，与“特别高兴”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我怕了下雨，就带了伞。", "corrected_sentence": "我怕会下雨，就带了伞。", "error_description": "错误：表示担心将来可能发生的事时，“怕”后面直接接要担心的事，不能加“了”。“怕了下雨”不通，应说“怕会下雨”或“怕下雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我怕很迟到，所以每次都提前出门。", "corrected_sentence": "我很怕迟到，所以每次都提前出门。", "error_description": "错误：程度副词“很”放错了位置。正确应为“很怕迟到”，“很”要放在“怕”前面，不能说“怕很迟到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
