INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89837, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "奇妙是说很特别，让人觉得好玩又想不到。", "primary_collocate": null, "pronunciation": "qí miào", "ipa": "tɕʰi˧˥ miɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个游戏太奇妙了，我从来没玩过。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子觉得蚂蚁的世界很奇妙。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔术师的表演真奇妙，我猜不出办法。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天发生了一件奇妙的事。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具有一个奇妙的小机关。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗居然会开门，真是太奇妙了！", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的想法很奇妙，大家都想不到。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪花落在手上就不见了，感觉很奇妙。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多奇妙的故事。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次奇妙的旅行让我们都笑了。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇妙的", "label": "的字结构"}, {"form": "奇妙地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "奇妙|形容词|特别好玩又想不到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”形容食物的味道，不能用来形容游戏。"}, {"text": "奇妙", "is_correct": true, "explanation": "奇妙形容游戏新奇美妙、令人惊叹，与“太……了”和“从来没玩过”的语境相符。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”用于人的举止和态度，不能用来形容游戏。"}, {"text": "常见", "is_correct": false, "explanation": "语义：“常见”指很多人都见过，与句中“我从来没玩过”矛盾。"}], "explanations": {"好吃": "搭配：“好吃”形容食物的味道，不能用来形容游戏。", "奇妙": "奇妙形容游戏新奇美妙、令人惊叹，与“太……了”和“从来没玩过”的语境相符。", "大方": "搭配：“大方”用于人的举止和态度，不能用来形容游戏。", "常见": "语义：“常见”指很多人都见过，与句中“我从来没玩过”矛盾。"}, "sentence_index": 0, "correct_answer": "奇妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话的样子很奇妙，让人觉得有点不舒服。", "explanation": "这里应该用〈奇怪〉。奇妙带有赞叹、新奇美好的色彩，形容让人不舒服的样子要用奇怪。"}, {"text": "听到雷声，他觉得很奇妙，吓得躲进了屋里。", "explanation": "这里应该用〈可怕〉。奇妙表示令人赞叹的感受，不能表示害怕，句中是惊吓的情形。"}, {"text": "这道题很奇妙，我做了半天还不会，越做越烦。", "explanation": "这里应该用〈难〉。奇妙表示新奇有趣、让人惊喜，不能形容让人做不出、越做越烦的题，这里要用难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来形容想法。"}, {"text": "奇妙", "is_correct": true, "explanation": "奇妙形容想法新奇、出人意料，与“大家都想不到”的语境相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材和外形，不能用来形容想法。"}, {"text": "平凡", "is_correct": false, "explanation": "语义：“平凡”指普通、不出奇，与“大家都想不到”矛盾。"}], "explanations": {"寒冷": "语义：“寒冷”形容温度，不能用来形容想法。", "奇妙": "奇妙形容想法新奇、出人意料，与“大家都想不到”的语境相符。", "高大": "体貌：“高大”形容人或物的身材和外形，不能用来形容想法。", "平凡": "语义：“平凡”指普通、不出奇，与“大家都想不到”矛盾。"}, "sentence_index": 6, "correct_answer": "奇妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次奇妙的旅行让我们都打起了哈欠。", "explanation": "这里应该用〈无聊〉。奇妙表示新奇美好，不能形容让人打哈欠的枯燥经历，这里要用无聊。"}, {"text": "这次考试的成绩很奇妙，我考得很差。", "explanation": "这里应该用〈糟糕〉。奇妙是赞美新奇美好，不能形容考得很差的成绩，这里要用糟糕。"}, {"text": "这碗面很奇妙，我一口都没吃完。", "explanation": "这里应该用〈难吃〉。奇妙不表示味道差，一口都没吃完要用难吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行有一个奇妙地结尾，大家都很惊喜。", "corrected_sentence": "这次旅行有一个奇妙的结尾，大家都很惊喜。", "error_description": "“地”只用于修饰动词，不能修饰名词“结尾”，应为“奇妙的结尾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小机关奇妙很，孩子们都围过来看。", "corrected_sentence": "这个小机关奇妙极了，孩子们都围过来看。", "error_description": "程度补语要放在形容词后面用“极了”，应说“奇妙极了”，“很”不能放在形容词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
