INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89838, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "新奇美妙，令人惊奇。", "primary_collocate": null, "pronunciation": "qí miào", "ipa": "tɕʰi˧˥ miɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "夜空中的极光美丽而奇妙。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大自然的变化真奇妙。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海底有一个奇妙的世界。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐带给人奇妙的感受。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次看到彩虹，觉得奇妙极了。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山里的景色奇妙得让人说不出话。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学让我们看到许多奇妙的现象。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一段奇妙的经历。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星空下，一切都显得那么奇妙。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次奇妙的相遇。", "target_word": "奇妙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇妙的", "label": "的字结构"}, {"form": "奇妙地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "奇妙|形容词|新奇美妙令人惊奇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音嘈杂，与美丽的极光不相符。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指旧的、过时的，与“美丽”的极光矛盾。"}, {"text": "奇妙", "is_correct": true, "explanation": "奇妙形容极光美丽而新奇，与“美丽而”的语境相符。"}, {"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”多用于体积大、行动不灵便的物品，不用于形容极光。"}], "explanations": {"吵闹": "语义：“吵闹”形容声音嘈杂，与美丽的极光不相符。", "陈旧": "语义：“陈旧”指旧的、过时的，与“美丽”的极光矛盾。", "奇妙": "奇妙形容极光美丽而新奇，与“美丽而”的语境相符。", "笨重": "搭配：“笨重”多用于体积大、行动不灵便的物品，不用于形容极光。"}, "sentence_index": 0, "correct_answer": "奇妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个山洞很奇妙，吓得我不敢进去。", "explanation": "这里应该用〈恐怖〉。奇妙表示令人赞叹的感受，不能表示让人害怕的环境，句中是惊吓的情形。"}, {"text": "这次比赛的结果很奇妙，大家都很失望。", "explanation": "这里应该用〈糟糕〉。奇妙是赞美新奇美好，不能形容让人失望的结果，这里要用糟糕。"}, {"text": "这门课很奇妙，大家都打瞌睡。", "explanation": "这里应该用〈枯燥〉。奇妙不表示乏味，大家都打瞌睡的课要用枯燥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简陋", "is_correct": false, "explanation": "搭配：“简陋”用于房屋、设施等，不说“简陋的现象”。"}, {"text": "愚蠢", "is_correct": false, "explanation": "语义：“愚蠢”形容人的言行，现象本身不能愚蠢，也与“科学”的语境不符。"}, {"text": "奇妙", "is_correct": true, "explanation": "奇妙形容现象新奇美妙、令人惊叹，与“科学让我们看到”的语境相符。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或动物的体形，不能用来形容现象。"}], "explanations": {"简陋": "搭配：“简陋”用于房屋、设施等，不说“简陋的现象”。", "愚蠢": "语义：“愚蠢”形容人的言行，现象本身不能愚蠢，也与“科学”的语境不符。", "奇妙": "奇妙形容现象新奇美妙、令人惊叹，与“科学让我们看到”的语境相符。", "瘦小": "体貌：“瘦小”形容人或动物的体形，不能用来形容现象。"}, "sentence_index": 6, "correct_answer": "奇妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的伤口很奇妙，疼得他直叫。", "explanation": "这里应该用〈痛〉。奇妙表示新奇美好、令人赞叹，不能形容伤口的痛感，句中是伤口痛得他直叫，要用痛。"}, {"text": "这部电影很奇妙，我看了一半就困得睡着了。", "explanation": "这里应该用〈平庸〉。奇妙表示令人赞叹，不能形容让人看到一半就睡着的平庸作品。"}, {"text": "屋里很奇妙，我们都冻得发抖。", "explanation": "这里应该用〈寒冷〉。奇妙不能形容温度，冻得发抖的环境要用寒冷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些光在夜空里奇妙的舞动，让人忍不住停下脚步。", "corrected_sentence": "这些光在夜空里奇妙地舞动，让人忍不住停下脚步。", "error_description": "“奇妙”修饰动词“舞动”、作状语时要用“地”，不能用“的”，应为“奇妙地舞动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片湖在星空下奇妙让人屏住了呼吸。", "corrected_sentence": "这片湖在星空下奇妙得让人屏住了呼吸。", "error_description": "“奇妙”后漏了“得”，程度补语结构应为“奇妙得让人……”，此处漏了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
