INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "妇女在政治、经济、社会等方面应享有的与男子平等的权利。", "primary_collocate": null, "pronunciation": "nǚ quán", "ipa": "ny˨˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "女权包括女人的政治权利和经济权利。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的宪法保护女权。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女权让妇女得到了投票的机会。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在法律上保障女权。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的演讲谈到了女权和教育。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女权在社会上受到越来越多的保护。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了女权的发展。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中的平等也是女权的一部分。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们讨论着女权在经济方面的意义。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了女权，她写过很多文章。", "target_word": "女权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女权主义", "label": "复合词"}, {"form": "女权运动", "label": "复合词"}], "register": "中性", "sense_fingerprint": "妇女在政治经济社会方面与男子平等的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女权", "is_correct": true, "explanation": "正确：“包括女人的政治权利和经济权利”说明女权的内容，与句意相符。"}, {"text": "养老金", "is_correct": false, "explanation": "语义：“包括……和……”要求同类的权利概念，养老金是社会保障，不能与女人的政治权利并列。"}, {"text": "房价", "is_correct": false, "explanation": "语义：房价不属于政治或经济权利的范畴，无法作为“包括”的内容。"}, {"text": "股票", "is_correct": false, "explanation": "搭配：“包括……经济权利”中的主语应为权利类名词，股票是金融产品，搭配不当。"}], "explanations": {"女权": "正确：“包括女人的政治权利和经济权利”说明女权的内容，与句意相符。", "养老金": "语义：“包括……和……”要求同类的权利概念，养老金是社会保障，不能与女人的政治权利并列。", "房价": "语义：房价不属于政治或经济权利的范畴，无法作为“包括”的内容。", "股票": "搭配：“包括……经济权利”中的主语应为权利类名词，股票是金融产品，搭配不当。"}, "sentence_index": 0, "correct_answer": "女权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "女权每天都在厨房里做饭。", "explanation": "语义：〈女权〉是抽象的权利，不能做饭；做事的人应说〈妇女〉。"}, {"text": "女权今天穿了一条红裙子。", "explanation": "语义：〈女权〉指权利，不是人，不能穿衣服。"}, {"text": "这个国家的女权人口超过了一亿。", "explanation": "这里应该用〈女性〉。女权指权利，不指人群，说人口要用〈女性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女权", "is_correct": true, "explanation": "正确：“介绍了女权的发展”指介绍女性权利的历史进程，与句意相符。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是生理现象，没有可以“介绍发展”的历程，“这本书介绍了眼泪的发展”与常识不符。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“发展”用于事物的演变过程，“微笑”是表情动作，不说“微笑的发展”。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳是生理活动，不是可以写进书里介绍其历史演变的对象，与书籍主题不符。"}], "explanations": {"女权": "正确：“介绍了女权的发展”指介绍女性权利的历史进程，与句意相符。", "眼泪": "语义：眼泪是生理现象，没有可以“介绍发展”的历程，“这本书介绍了眼泪的发展”与常识不符。", "微笑": "搭配：“发展”用于事物的演变过程，“微笑”是表情动作，不说“微笑的发展”。", "心跳": "语义：心跳是生理活动，不是可以写进书里介绍其历史演变的对象，与书籍主题不符。"}, "sentence_index": 6, "correct_answer": "女权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "女权昨天坐火车去了上海。", "explanation": "语义：〈女权〉是抽象的权利，不能坐火车出行。"}, {"text": "她是一名女权。", "explanation": "这里应该用〈女权主义者〉。女权指权利，不指人。"}, {"text": "这所学校的女权正在操场上踢足球。", "explanation": "语义：「女权」是抽象的权利，不能在操场上踢足球，此处主语应指人或群体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一位很有名的女权。", "corrected_sentence": "她是一位很有名的女权主义者。", "error_description": "用词错误：〈女权〉指妇女的平等权利，不指人；指人应说〈女权主义者〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有二十个女权。", "corrected_sentence": "我们班有二十个女生。", "error_description": "用词错误：〈女权〉指妇女的平等权利，不指人；说班里的人数应说〈女生〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
