INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89841, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所为是一个人做过的事。", "primary_collocate": null, "pronunciation": "suǒ wéi", "ipa": "suɔ˨˩˦ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事是他的所为。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察查出这是小偷的所为。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的所为让大家很失望。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为自己的所为道歉。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要对自己的所为负责。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都看到了他的所为。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的所为让妈妈很生气。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的所为不能原谅。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这到底是谁的所为？", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不知道这是孙子的所为。", "target_word": "所为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所作所为", "label": "复合"}], "register": "书面语", "sense_fingerprint": "一个人做过的事，多指不好的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所为", "is_correct": true, "explanation": "正确。「所为」指一个人做过的事，这里说这件事是他做的。"}, {"text": "电话", "is_correct": false, "explanation": "语义：「电话」是通信工具，「这件事是他的电话」句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是自然现象，不能说是某人做的，与「这件事是他的」矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：「房子」不能用来指一件事情的归属，「这件事是他的房子」搭配不通。"}], "explanations": {"所为": "正确。「所为」指一个人做过的事，这里说这件事是他做的。", "电话": "语义：「电话」是通信工具，「这件事是他的电话」句意不通。", "天气": "语义：「天气」是自然现象，不能说是某人做的，与「这件事是他的」矛盾。", "房子": "搭配：「房子」不能用来指一件事情的归属，「这件事是他的房子」搭配不通。"}, "sentence_index": 0, "correct_answer": "所为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看见一只所为从门口走过。", "explanation": "语义错误：「所为」指做过的事，是抽象的，不能用「只」计量，也不能「走过」。"}, {"text": "我们制定了所为计划。", "explanation": "这里应该用〈行动〉。「所为」指已经做过的事，不能用来修饰「计划」；「行动计划」中的「行动」指将要进行的活动，两者不能互换。"}, {"text": "这份所为很好吃，大家都想尝一尝。", "explanation": "这里的意思不对。「所为」指做过的事，不指食物；食物应说「食物」或「菜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所为", "is_correct": true, "explanation": "正确。「所为」指做过的事，这里指孩子做的事让妈妈生气。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」是家具，不是做过的事，不能让妈妈生气。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：「月亮」是天体，不能是孩子做的事，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：「孩子的天空」搭配不通，天空不能被孩子做出来。"}], "explanations": {"所为": "正确。「所为」指做过的事，这里指孩子做的事让妈妈生气。", "桌子": "语义：「桌子」是家具，不是做过的事，不能让妈妈生气。", "月亮": "语义：「月亮」是天体，不能是孩子做的事，句意不通。", "天空": "搭配：「孩子的天空」搭配不通，天空不能被孩子做出来。"}, "sentence_index": 6, "correct_answer": "所为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都在所为上花很多时间。", "explanation": "这里应该用〈工作〉。「所为」指已经做过的事，是过去的事情，不能用来表示正在投入时间的事务。"}, {"text": "孙子的所为给老人买了一个苹果。", "explanation": "这里应该用〈人〉作主语。「所为」指做过的事，是抽象概念，不能充当「买」的动作主体。"}, {"text": "老人不知道这是孙子的一只所为。", "explanation": "语义错误：「所为」指做过的事，一般不用量词，更不能用「只」，应说「孙子的所为」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那件坏事是邻居地所为。", "corrected_sentence": "那件坏事是邻居的所为。", "error_description": "助词错误：名词「所为」前的定语要用「的」，不能用「地」，应说「邻居的所为」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们地所为让老师很难过。", "corrected_sentence": "他们的所为让老师很难过。", "error_description": "助词错误：名词「所为」前的定语要用「的」，不能用「地」，应说「他们的所为」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
