INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89843, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "有可能是说也许会发生。", "primary_collocate": null, "pronunciation": "yǒu kě néng", "ipa": "joʊ˨˩˦ kʰɤ˨˩˦ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "明天有可能下大雨。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有可能已经回家了。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车,我有可能会迟到。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试,你有可能得第一名。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑,有可能要停电。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不接电话,有可能在开会。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果不努力,你有可能找不到工作。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年冬天有可能比去年冷。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有可能不知道这件事。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机有可能晚点,我们别着急。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很有可能", "label": "复合"}, {"form": "有可能会", "label": "复合"}], "register": "中性", "sense_fingerprint": "有可能:也许会,表示推测", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有可能", "is_correct": true, "explanation": "有可能表示事情也许会发生，与句中“明天”的推测相符，填入后句意成立。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示义务或必要，天气不能被要求，“明天必须下大雨”说不通。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，天气没有胆量，“明天敢下大雨”说不通。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意”表示主观意愿，天气没有意愿，句意不通。"}], "explanations": {"有可能": "有可能表示事情也许会发生，与句中“明天”的推测相符，填入后句意成立。", "必须": "语义：“必须”表示义务或必要，天气不能被要求，“明天必须下大雨”说不通。", "敢": "语义：“敢”表示有胆量，天气没有胆量，“明天敢下大雨”说不通。", "愿意": "语义：“愿意”表示主观意愿，天气没有意愿，句意不通。"}, "sentence_index": 0, "correct_answer": "有可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的女儿两岁就有可能背完《三字经》。", "explanation": "这里应该用〈能〉。〈能〉说明已经具备的能力，“两岁就背完”是事实；“有可能”只表示推测，会把已知能力说成猜测。"}, {"text": "我昨天有可能去了北京，还见了老朋友。", "explanation": "这里应该用〈确实〉或去掉“有可能”。自己昨天做过的事是确定的事实，“有可能”只表示推测。"}, {"text": "这件事已经定下来了，它有可能发生。", "explanation": "这里应该用〈一定〉。〈一定〉表示已经确定会发生；“有可能”只表示推测，与“已经定下来了”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有可能", "is_correct": true, "explanation": "有可能表示推测，“如果不努力”之后说明的是可能出现的结果，填入后句意成立。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示许可或能力，不表示推测，“你可以找不到工作”句意不通。"}, {"text": "该", "is_correct": false, "explanation": "语义：“该”表示应当，指本应做的事，“找不到工作”不是应当出现的结果。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量去做，不能与“找不到工作”这种不想要的结果搭配。"}], "explanations": {"有可能": "有可能表示推测，“如果不努力”之后说明的是可能出现的结果，填入后句意成立。", "可以": "语义：“可以”表示许可或能力，不表示推测，“你可以找不到工作”句意不通。", "该": "语义：“该”表示应当，指本应做的事，“找不到工作”不是应当出现的结果。", "敢": "语义：“敢”表示有胆量去做，不能与“找不到工作”这种不想要的结果搭配。"}, "sentence_index": 6, "correct_answer": "有可能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你有可能不要动。", "explanation": "这里应该用〈别〉。〈别〉表示禁止或劝阻，“有可能”只表示推测，不能用来要求对方不要做某事。"}, {"text": "这件事已经定了，我们有可能马上出发。", "explanation": "这里应该用〈一定〉。〈一定〉表示确定会发生，“有可能”只表示推测，与“已经定了”矛盾。"}, {"text": "我亲眼看见了他的教师证，他有可能是老师。", "explanation": "这里应该用〈确实〉。〈确实〉表示已经确认的事实；“有可能”只表示推测，与“亲眼看见了教师证”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午不有可能下雨。", "corrected_sentence": "下午有可能下雨。", "error_description": "错误：“不”放在了“有可能”前面，“不有可能”不成立。否定推测应说“下午不可能下雨”；想说也许不下雨，应说“下午有可能不下雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会有可能来。", "corrected_sentence": "他有可能来。", "error_description": "错误：“会”放在了“有可能”前面。“有可能”本身表示推测，前面不能再加“会”，应说“他有可能来”或“他有可能会来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
