INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示事情存在发生的可能。", "primary_collocate": null, "pronunciation": "yǒu kě néng", "ipa": "joʊ˨˩˦ kʰɤ˨˩˦ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这件事完全有可能。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的情况有可能吗?", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有可能成功,也有可能失败。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要努力,就有可能实现梦想。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么做有可能出问题。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这种天气里,迟到是有可能的。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得他会同意,有可能吗?", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队都有可能赢得比赛。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有可能是亲戚。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻有可能是假的。", "target_word": "有可能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很有可能", "label": "复合"}, {"form": "完全有可能", "label": "复合"}], "register": "中性", "sense_fingerprint": "有可能:事情存在发生的可能性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有可能", "is_correct": true, "explanation": "有可能表示事情存在发生的可能性，与“完全”搭配，句意成立。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”要求有意愿的施事，“这件事”不能同意，“这件事完全同意”不成立。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事情已经出现，“完全发生”与句中所说的可能性不符。"}, {"text": "说明", "is_correct": false, "explanation": "语义：“说明”需要说明的内容作宾语，且指向结果，与“可能性”的意思不符，句意不完整。"}], "explanations": {"有可能": "有可能表示事情存在发生的可能性，与“完全”搭配，句意成立。", "同意": "配价：“同意”要求有意愿的施事，“这件事”不能同意，“这件事完全同意”不成立。", "发生": "语义：“发生”指事情已经出现，“完全发生”与句中所说的可能性不符。", "说明": "语义：“说明”需要说明的内容作宾语，且指向结果，与“可能性”的意思不符，句意不完整。"}, "sentence_index": 0, "correct_answer": "有可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳有可能从东方升起。", "explanation": "这里应该用〈总是〉。太阳从东方升起是必然的事实，“有可能”只表示推测，会把必然的事说成不确定的事。"}, {"text": "这件事已经证实，它有可能是假的。", "explanation": "这里应该用〈肯定〉。“已经证实”说明事情已有定论，“有可能”只表示尚未确定的推测，两者矛盾。"}, {"text": "这次考试，他有可能必须及格。", "explanation": "这里应该用〈必须〉。〈必须〉表示必要或要求，“有可能”只表示推测，与“必须及格”的要求矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有可能", "is_correct": true, "explanation": "有可能用于对“他会同意”这种可能性提问，填入后句意完整。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示义务或必要，不能用来询问他同意的可能性，句意不通。"}, {"text": "存在", "is_correct": false, "explanation": "语义：“存在”表示有或是存在，不能对应“同意”这一行为，句意不通。"}, {"text": "实现", "is_correct": false, "explanation": "配价：“实现”要求一个目标或愿望作宾语，“他会同意”中没有可以实现的对象，句意不通。"}], "explanations": {"有可能": "有可能用于对“他会同意”这种可能性提问，填入后句意完整。", "必须": "语义：“必须”表示义务或必要，不能用来询问他同意的可能性，句意不通。", "存在": "语义：“存在”表示有或是存在，不能对应“同意”这一行为，句意不通。", "实现": "配价：“实现”要求一个目标或愿望作宾语，“他会同意”中没有可以实现的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "有可能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亲眼看到他，他有可能在场。", "explanation": "这里应该用〈确实〉。〈确实〉表示已亲眼确认的事实；“有可能”只表示推测，与“亲眼看到”矛盾。"}, {"text": "我昨天亲手交了作业，作业有可能交了。", "explanation": "这里应该用〈已经〉。“亲手交了”是自己确知的事实，“有可能”只表示推测，与确知的事实矛盾。"}, {"text": "这种做法必然会成功，它有可能导致失败。", "explanation": "这里应该用〈不会〉。“必然会成功”是确定的判断，“有可能导致失败”只表示推测，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次合作有可能能成功。", "corrected_sentence": "这次合作有可能成功。", "error_description": "错误：“有可能”后面又加了“能”，两个情态成分重叠。去掉“能”即为“这次合作有可能成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他可能有可能成功。", "corrected_sentence": "他有可能成功。", "error_description": "错误：“可能”与“有可能”意思重复，句中只留一个即可。应说“他有可能成功”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
