INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里很美丽、有神力的女子。", "primary_collocate": null, "pronunciation": "nǚ shén", "ipa": "ny˨˩˦ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "故事里的女神住在高高的山上。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女神很美，还有神奇的力量。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女神用手一指，河水就停下来了。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的女神帮助了很多穷人。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，奶奶常给我讲女神的故事。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女神从天上下来，送给农民一袋种子。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山里为女神盖了一座小庙。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，女神用神力把坏人变成了石头。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女神有一双会发光的眼睛。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王爱上了天上的女神。", "target_word": "女神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位女神", "label": "量词"}], "register": "中性", "sense_fingerprint": "故事、神话里美丽且有神力的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb81bd1-7443-4fba-9b2e-42070bd1a607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "女神", "is_correct": true, "explanation": "正确。「女神」指故事里美丽、有神力的女子。"}, {"text": "女生", "is_correct": false, "explanation": "nǚ shēng（第一声，-ng 韵尾）与 nǚ shén（第二声，-n 韵尾）韵尾与声调都不同，意思是女学生。"}, {"text": "女人", "is_correct": false, "explanation": "rén 与 shén 声母不同（r 与 sh），意思是成年女性。"}, {"text": "女身", "is_correct": false, "explanation": "nǚ shēn（第一声）与 nǚ shén（第二声）只差声调，意思是女性的身体。"}], "explanations": {"女神": "正确。「女神」指故事里美丽、有神力的女子。", "女生": "nǚ shēng（第一声，-ng 韵尾）与 nǚ shén（第二声，-n 韵尾）韵尾与声调都不同，意思是女学生。", "女人": "rén 与 shén 声母不同（r 与 sh），意思是成年女性。", "女身": "nǚ shēn（第一声）与 nǚ shén（第二声）只差声调，意思是女性的身体。"}, "sentence_index": null, "correct_answer": "女神"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会住在山上。"}, {"text": "女神", "is_correct": true, "explanation": "正确。「故事里的女神」指有神力的女子，能住在山上。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能住在山上。"}, {"text": "闪电", "is_correct": false, "explanation": "搭配：「住在」的主语要能居住，闪电不能说「住在山上」。"}], "explanations": {"桌子": "语义：桌子是家具，不会住在山上。", "女神": "正确。「故事里的女神」指有神力的女子，能住在山上。", "书包": "语义：书包是物品，不能住在山上。", "闪电": "搭配：「住在」的主语要能居住，闪电不能说「住在山上」。"}, "sentence_index": 0, "correct_answer": "女神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "故事里的女神是个驼背的老太婆，专门用毒药害人。", "explanation": "这里应该用〈女巫〉。女神指美丽、有神力的女子，专门用毒药害人、相貌丑陋的应称女巫。"}, {"text": "故事里的女神是一位白发苍苍的老爷爷，专门守护村庄。", "explanation": "这里应该用〈神〉。「女神」只指女性神灵，白发老爷爷这样的男性神灵应称〈神〉。"}, {"text": "我在书里看见一只女神。", "explanation": "这里量词用错。「只」用于动物，指神灵应用「位」，应说「一位女神」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公路", "is_correct": false, "explanation": "语义：公路是道路，不能成为被供奉的对象。"}, {"text": "女神", "is_correct": true, "explanation": "正确。「为女神盖了一座小庙」指为神灵建庙，与句子相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不会被人供奉，为它盖庙说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为被供奉的对象。"}], "explanations": {"公路": "语义：公路是道路，不能成为被供奉的对象。", "女神": "正确。「为女神盖了一座小庙」指为神灵建庙，与句子相合。", "书包": "语义：书包是物品，不会被人供奉，为它盖庙说不通。", "冰箱": "语义：冰箱是家电，不能作为被供奉的对象。"}, "sentence_index": 6, "correct_answer": "女神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国王的女神每天早上替他洗衣服。", "explanation": "这里应该用〈女仆〉。女神指美丽、有神力的女子，替人洗衣服的是女仆。"}, {"text": "国王在宫里种了一棵女神。", "explanation": "这里量词用错。「棵」用于植物，指神灵应用「位」，应说「一位女神」。"}, {"text": "这位女神专门吸人的血，村民们都躲着她。", "explanation": "这里应该用〈女妖〉。女神指美丽、有神力的女子，专门吸人血、人人躲避的是女妖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只女神在云上看着人间。", "corrected_sentence": "那位女神在云上看着人间。", "error_description": "量词错误：指神灵的「女神」应用「位」，不用「只」（「只」用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只女神把宝剑送给了英雄。", "corrected_sentence": "这位女神把宝剑送给了英雄。", "error_description": "量词错误：指神灵的「女神」应用「位」，不用「只」（「只」用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
