INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海外是在大海那边,别的国家。", "primary_collocate": null, "pronunciation": "hǎi wài", "ipa": "xaɪ˨˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他在海外住了五年。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在海外工作，很少回家。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想把产品卖到海外。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时，很多海外的朋友打来电话。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后去海外读书。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海外的生活和国内很不一样。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从海外给妈妈寄来一份礼物。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书在海外也很有名。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有去海外旅游过？", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海外的朋友说那里的冬天很冷。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海外华人", "label": "复合"}], "register": "中性", "sense_fingerprint": "海外：隔着大海的别的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "搭配：“住”的处所要是地点，不能说“在时间住了五年”。"}, {"text": "海外", "is_correct": true, "explanation": "正确：“海外”指隔着大海的别的国家，可以作“住”的处所。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以居住的地方，与“住了五年”的语境冲突。"}, {"text": "人群", "is_correct": false, "explanation": "语义：人群不是地点，不能作“住”的处所。"}], "explanations": {"时间": "搭配：“住”的处所要是地点，不能说“在时间住了五年”。", "海外": "正确：“海外”指隔着大海的别的国家，可以作“住”的处所。", "空气": "语义：空气不是可以居住的地方，与“住了五年”的语境冲突。", "人群": "语义：人群不是地点，不能作“住”的处所。"}, "sentence_index": 0, "correct_answer": "海外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在国内的海外堆沙子，玩得很开心。", "explanation": "这里应该用〈海边〉。海外指别的国家，与“国内”连用自相矛盾，堆沙子要说海边。"}, {"text": "我家在海外，每天骑车去北京上班。", "explanation": "这里应该用〈国内〉。海外指国外，北京在国内，骑车上班不能说海外。"}, {"text": "我去过很多条海外。", "explanation": "这里应该用〈国家〉。海外是地方，不能用〈条〉来数，应说“去过很多国家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是寄件的地方，与“寄来一份礼物”的语境冲突。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天是时间，不能作寄件的来处，“从白天寄来礼物”不通。"}, {"text": "海外", "is_correct": true, "explanation": "正确：“从海外寄来”表示从隔海的别国寄来，与“寄来”搭配。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底不能寄出包裹，与“寄来一份礼物”的语境冲突。"}], "explanations": {"天空": "语义：天空不是寄件的地方，与“寄来一份礼物”的语境冲突。", "白天": "语义：白天是时间，不能作寄件的来处，“从白天寄来礼物”不通。", "海外": "正确：“从海外寄来”表示从隔海的别国寄来，与“寄来”搭配。", "海底": "语义：海底不能寄出包裹，与“寄来一份礼物”的语境冲突。"}, "sentence_index": 6, "correct_answer": "海外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市很大，有十个海外。", "explanation": "这里应该用〈国家〉。海外是地方概念，不能用“个”来数，应说“有十个国家”。"}, {"text": "这家公司在北京海外，有一百名员工。", "explanation": "这里应该用〈国内〉。海外指国外，北京在国内，不能说“北京海外”。"}, {"text": "我们学校有两座海外。", "explanation": "这里应该用〈地方〉。〈座〉用于山、楼等大而固定的东西，海外是地方，不能用〈座〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥在一个海外做生意，一年回来两次。", "corrected_sentence": "我表哥在海外做生意，一年回来两次。", "error_description": "“海外”表示地方，前面不能加“一个”。应说“在海外”，不说“在一个海外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐在海外里读书，已经三年了。", "corrected_sentence": "我姐姐在海外读书，已经三年了。", "error_description": "“海外”本身已表示“在国外”，后面不再加方位词“里”。应说“在海外读书”，不说“在海外里读书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
