INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国外;海洋之外的地方。", "primary_collocate": null, "pronunciation": "hǎi wài", "ipa": "xaɪ˨˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他常常去海外出差。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的儿子在海外定居了。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在海外的中国人也很关心家乡的变化。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去海外看看不同的文化。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内的东西比海外的便宜很多。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画在海外卖得很好。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在海外学了三年音乐。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海外的市场对这家工厂很重要。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，海外的亲戚都回来了。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从海外回来的人要先检查身体。", "target_word": "海外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海外市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "海外：国外，海洋之外的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是出差的地方，与“出差”的语境冲突。"}, {"text": "海外", "is_correct": true, "explanation": "正确：“海外”指国外，可以作“去”的处所，表示到国外出差。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史不是可以前往的地方，与“去”的语境冲突。"}, {"text": "星期天", "is_correct": false, "explanation": "搭配：“去”后面要接地点，星期天是时间，不能说“去星期天出差”。"}], "explanations": {"厨房": "语义：厨房不是出差的地方，与“出差”的语境冲突。", "海外": "正确：“海外”指国外，可以作“去”的处所，表示到国外出差。", "历史": "语义：历史不是可以前往的地方，与“去”的语境冲突。", "星期天": "搭配：“去”后面要接地点，星期天是时间，不能说“去星期天出差”。"}, "sentence_index": 0, "correct_answer": "海外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们喜欢在老家的海外晒太阳，看海浪。", "explanation": "这里应该用〈海边〉。海外指国外，与“老家”连用自相矛盾；晒太阳看海浪要说海边。"}, {"text": "我每天坐一小时地铁，从海外去上班。", "explanation": "这里应该用〈市区〉。海外指国外，每天坐地铁上班说的是城市内部，不能说“从海外去”。"}, {"text": "我去过三座海外。", "explanation": "这里应该用〈国家〉。〈座〉用于山、楼等大而固定的东西，不能数“海外”，应说“去过三个国家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课桌", "is_correct": false, "explanation": "搭配：“学”的处所应是教室、琴房等，课桌不是学习音乐的地方。"}, {"text": "海外", "is_correct": true, "explanation": "正确：“在海外学”表示在国外学习，与“学了三年音乐”搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能作学习的处所，与句子的语境冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是学习的地方，句子读起来不合常理。"}], "explanations": {"课桌": "搭配：“学”的处所应是教室、琴房等，课桌不是学习音乐的地方。", "海外": "正确：“在海外学”表示在国外学习，与“学了三年音乐”搭配。", "月亮": "语义：月亮不能作学习的处所，与句子的语境冲突。", "冰箱": "语义：冰箱不是学习的地方，句子读起来不合常理。"}, "sentence_index": 6, "correct_answer": "海外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个港口在北京海外，来往的船很多。", "explanation": "这里应该用〈沿海〉。海外指国外，不能和“北京”连用来说港口的位置。"}, {"text": "我买了一颗海外，回家后送给朋友。", "explanation": "这里应该用〈地方〉。〈颗〉用于粒状的小东西，海外是地方，不能当作可以买的东西来数。"}, {"text": "饭桌上摆满了海外，大家都很开心。", "explanation": "这里应该用〈食物〉。海外是地方，不能当作可以摆在桌上的东西，应说“摆满了食物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹打算去在海外留学。", "corrected_sentence": "妹妹打算去海外留学。", "error_description": "“去”后面直接接处所，不用“在”。应说“去海外留学”，不说“去在海外留学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在海外回来，就一直很忙。", "corrected_sentence": "他从海外回来，就一直很忙。", "error_description": "表示“从某地来”要用介词“从”，“在海外回来”不对。应说“从海外回来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "老", "is_correct": true, "explanation": "反义：“老”指植物长成、不再嫩，与“嫩”相对。"}, {"text": "厚", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}, {"text": "快", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}, {"text": "宽", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}], "correct_answer": "老", "explanations": {"老": "反义：“老”指植物长成、不再嫩，与“嫩”相对。", "厚": "与“嫩”没有反义关系，二者不构成对立。", "快": "与“嫩”没有反义关系，二者不构成对立。", "宽": "与“嫩”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "老", "is_correct": true, "explanation": "反义：“老”指植物长成、不再嫩，与“嫩”相对。"}, {"text": "远", "is_correct": false, "explanation": "与“嫩”没有反义关系，“远”与“近”相对。"}, {"text": "冷", "is_correct": false, "explanation": "与“嫩”没有反义关系，“冷”与“热”相对。"}, {"text": "高", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}], "correct_answer": "老", "explanations": {"老": "反义：“老”指植物长成、不再嫩，与“嫩”相对。", "远": "与“嫩”没有反义关系，“远”与“近”相对。", "冷": "与“嫩”没有反义关系，“冷”与“热”相对。", "高": "与“嫩”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "嫩是说又软又小，还没有长老。", "primary_collocate": null, "pronunciation": "nèn", "ipa": "nən˥˩", "syllable_count": 1, "sentences": [{"text": "小草刚长出来，又小又嫩。", "target_word": "嫩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些豆苗很嫩，不用煮太久。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树苗还很嫩，要小心照顾。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，河边的柳枝又细又嫩。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿的皮肤很嫩，要小心洗。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵白菜很嫩，我们今天吃。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚摘的茶叶最嫩，也最香。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫的爪子又小又嫩。", "target_word": "嫩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "玉米还嫩着呢，再等几天吧。", "target_word": "嫩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看这朵花多嫩，一碰就掉了。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "娇嫩", "label": "复合"}, {"form": "嫩绿", "label": "复合"}], "register": "口语", "sense_fingerprint": "刚长出来、又软又小、还没长老", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”（nèn）指又软又小、还没有长老。"}, {"text": "闷", "is_correct": false, "explanation": "mèn（第四声）与 nèn（第四声）声母不同（m/n），意思是“闷热、烦闷”。"}, {"text": "认", "is_correct": false, "explanation": "rèn 与 nèn 声母不同（r/n），声调相同，意思是“认识、承认”。"}, {"text": "内", "is_correct": false, "explanation": "nèi 与 nèn 韵母不同（ei/en），声调相同，意思是“里面”。"}, {"text": "恨", "is_correct": false, "explanation": "hèn（第四声）与 nèn（第四声）声母不同（h/n），声调相同，意思是“怨恨”。"}], "explanations": {"嫩": "正确。“嫩”（nèn）指又软又小、还没有长老。", "闷": "mèn（第四声）与 nèn（第四声）声母不同（m/n），意思是“闷热、烦闷”。", "认": "rèn 与 nèn 声母不同（r/n），声调相同，意思是“认识、承认”。", "内": "nèi 与 nèn 韵母不同（ei/en），声调相同，意思是“里面”。", "恨": "hèn（第四声）与 nèn（第四声）声母不同（h/n），声调相同，意思是“怨恨”。"}, "sentence_index": null, "correct_answer": "嫩"}, "level_3": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”指刚长出来的小草柔软、未长老，与“刚长出来”相合。"}, {"text": "老", "is_correct": false, "explanation": "语义：“刚长出来”的草不会是“老”的，与前一分句矛盾。"}, {"text": "大", "is_correct": false, "explanation": "语义：“又小又大”自相矛盾，句子说不通。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”是味道，不用来形容草的状态，不能说“又小又辣”。"}], "explanations": {"嫩": "正确。“嫩”指刚长出来的小草柔软、未长老，与“刚长出来”相合。", "老": "语义：“刚长出来”的草不会是“老”的，与前一分句矛盾。", "大": "语义：“又小又大”自相矛盾，句子说不通。", "辣": "搭配：“辣”是味道，不用来形容草的状态，不能说“又小又辣”。"}, "sentence_index": 0, "correct_answer": "嫩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个枕头很嫩，躺着很舒服。", "explanation": "这里应该用〈软〉。“嫩”指植物或食物柔软、未长老，枕头的软硬要说“软”。"}, {"text": "这坛酒很嫩，已经放了十年了。", "explanation": "这里应该用〈陈〉。酒放久了要说“陈”，“嫩”指还没长老，不能用来形容放了很久的酒。"}, {"text": "这块石头很嫩，锤子都敲不碎。", "explanation": "这里应该用〈硬〉。石头的硬度要说“硬”，“嫩”只用于柔软、未长老的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”（nèn）指又软又小、还没有长老。"}, {"text": "笨", "is_correct": false, "explanation": "bèn（第四声）与 nèn（第四声）声母不同（b/n），声调相同，意思是“笨拙”。"}, {"text": "份", "is_correct": false, "explanation": "fèn（第四声）与 nèn（第四声）声母不同（f/n），声调相同，意思是“一份”。"}, {"text": "认", "is_correct": false, "explanation": "rèn（第四声）与 nèn（第四声）声母不同（r/n），声调相同，意思是“认识”。"}, {"text": "内", "is_correct": false, "explanation": "nèi（第四声）与 nèn（第四声）韵母不同（ei/en），声调相同，意思是“里面”。"}], "explanations": {"嫩": "正确。“嫩”（nèn）指又软又小、还没有长老。", "笨": "bèn（第四声）与 nèn（第四声）声母不同（b/n），声调相同，意思是“笨拙”。", "份": "fèn（第四声）与 nèn（第四声）声母不同（f/n），声调相同，意思是“一份”。", "认": "rèn（第四声）与 nèn（第四声）声母不同（r/n），声调相同，意思是“认识”。", "内": "nèi（第四声）与 nèn（第四声）韵母不同（ei/en），声调相同，意思是“里面”。"}, "sentence_index": null, "correct_answer": "嫩"}, "level_3": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”指茶叶刚摘下、未老，最适合“最……，也最香”的描述。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”指分量大，与茶叶的品质描述无关，句子说不通。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”描述质地，茶叶“最硬”不是常见搭配，与“最香”的评价不合。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”指长度，不能描述茶叶的品质，句子说不通。"}], "explanations": {"嫩": "正确。“嫩”指茶叶刚摘下、未老，最适合“最……，也最香”的描述。", "重": "语义：“重”指分量大，与茶叶的品质描述无关，句子说不通。", "硬": "搭配：“硬”描述质地，茶叶“最硬”不是常见搭配，与“最香”的评价不合。", "长": "语义：“长”指长度，不能描述茶叶的品质，句子说不通。"}, "sentence_index": 6, "correct_answer": "嫩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个饼干很嫩，咬下去咔嚓响。", "explanation": "这里应该用〈脆〉。咬下去发出“咔嚓”声要说“脆”，“嫩”强调柔软不老，不说明清脆。"}, {"text": "这张桌子很嫩，放点东西就压坏了。", "explanation": "这里应该用〈结实〉。桌子的牢固程度要说“结实”，“嫩”只用于柔软、未长老的东西。"}, {"text": "这条路很嫩，走了很久才到。", "explanation": "这里应该说路远。“嫩”形容柔软或未长老的东西，不能描述路的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫有一双又小又嫩爪子。", "corrected_sentence": "小猫有一双又小又嫩的爪子。", "error_description": "多个形容词修饰名词时，“又小又嫩”后面要加“的”，应说“又小又嫩的爪子”，不能说“又小又嫩爪子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种豆苗嫩最，炒着最好吃。", "corrected_sentence": "这种豆苗最嫩，炒着最好吃。", "error_description": "副词“最”应放在形容词前。应说“最嫩”，不能说“嫩最”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "老", "is_correct": true, "explanation": "反义：“老”指食物或植物韧、不嫩，与“嫩”相对。"}, {"text": "红", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}, {"text": "快", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}, {"text": "重", "is_correct": false, "explanation": "与“嫩”没有反义关系，“重”与“轻”相对，与“嫩”无关。"}], "correct_answer": "老", "explanations": {"老": "反义：“老”指食物或植物韧、不嫩，与“嫩”相对。", "红": "与“嫩”没有反义关系，二者不构成对立。", "快": "与“嫩”没有反义关系，二者不构成对立。", "重": "与“嫩”没有反义关系，“重”与“轻”相对，与“嫩”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "老", "is_correct": true, "explanation": "反义：“老”指食物或植物韧、不嫩，与“嫩”相对。"}, {"text": "冷", "is_correct": false, "explanation": "与“嫩”没有反义关系，“冷”与“热”相对。"}, {"text": "高", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}, {"text": "宽", "is_correct": false, "explanation": "与“嫩”没有反义关系，二者不构成对立。"}], "correct_answer": "老", "explanations": {"老": "反义：“老”指食物或植物韧、不嫩，与“嫩”相对。", "冷": "与“嫩”没有反义关系，“冷”与“热”相对。", "高": "与“嫩”没有反义关系，二者不构成对立。", "宽": "与“嫩”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "软而易碎、不老的；也指刚长出来的。", "primary_collocate": null, "pronunciation": "nèn", "ipa": "nən˥˩", "syllable_count": 1, "sentences": [{"text": "这块豆腐很嫩，一碰就碎。", "target_word": "嫩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这根豆角很嫩，炒着很香。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的小草又嫩又绿。", "target_word": "嫩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块牛肉很嫩，一咬就烂。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树枝上的叶子还很嫩。", "target_word": "嫩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈买了一把嫩菠菜。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种菜要趁嫩的时候吃。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鱼蒸得很嫩，孩子爱吃。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根黄瓜太老了，那根比较嫩。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他煎的鱼很嫩，大家都爱吃。", "target_word": "嫩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "娇嫩", "label": "复合"}, {"form": "嫩绿", "label": "复合"}], "register": "口语", "sense_fingerprint": "食物或植物软、不老、容易碎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”（nèn）指食物或植物柔软、不老。"}, {"text": "闷", "is_correct": false, "explanation": "mèn（第四声）与 nèn（第四声）声母不同（m/n），意思是“闷热、烦闷”。"}, {"text": "认", "is_correct": false, "explanation": "rèn 与 nèn 声母不同（r/n），声调相同，意思是“认识、承认”。"}, {"text": "内", "is_correct": false, "explanation": "nèi 与 nèn 韵母不同（ei/en），声调相同，意思是“里面”。"}, {"text": "恨", "is_correct": false, "explanation": "hèn（第四声）与 nèn（第四声）声母不同（h/n），声调相同，意思是“怨恨”。"}], "explanations": {"嫩": "正确。“嫩”（nèn）指食物或植物柔软、不老。", "闷": "mèn（第四声）与 nèn（第四声）声母不同（m/n），意思是“闷热、烦闷”。", "认": "rèn 与 nèn 声母不同（r/n），声调相同，意思是“认识、承认”。", "内": "nèi 与 nèn 韵母不同（ei/en），声调相同，意思是“里面”。", "恨": "hèn（第四声）与 nèn（第四声）声母不同（h/n），声调相同，意思是“怨恨”。"}, "sentence_index": null, "correct_answer": "嫩"}, "level_3": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”指豆腐柔软，与“一碰就碎”相合。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”与“一碰就碎”的语义相矛盾，硬豆腐不会一碰就碎。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”描述味道，不用来形容豆腐的质地。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与豆腐的柔软程度无关，句子说不通。"}], "explanations": {"嫩": "正确。“嫩”指豆腐柔软，与“一碰就碎”相合。", "硬": "语义：“硬”与“一碰就碎”的语义相矛盾，硬豆腐不会一碰就碎。", "辣": "搭配：“辣”描述味道，不用来形容豆腐的质地。", "甜": "语义：“甜”指味道，与豆腐的柔软程度无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "嫩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张床很嫩，躺上去很舒服。", "explanation": "这里应该用〈软〉。“嫩”多指食物或植物柔软、不老，床的软硬要说“软”。"}, {"text": "这辆旧自行车很嫩，骑了很多年了。", "explanation": "这里应该用〈老〉。“嫩”指刚长出来或未长老，用了很多年的东西要说“老”，不能说“嫩”。"}, {"text": "这根铁丝很嫩，一掰就弯。", "explanation": "这里应该用〈软〉。一掰就弯说明铁丝是软的；“嫩”多形容食物或植物，不能用来形容金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”（nèn）指食物或植物柔软、不老。"}, {"text": "笨", "is_correct": false, "explanation": "bèn（第四声）与 nèn（第四声）声母不同（b/n），声调相同，意思是“笨拙”。"}, {"text": "份", "is_correct": false, "explanation": "fèn（第四声）与 nèn（第四声）声母不同（f/n），声调相同，意思是“一份”。"}, {"text": "认", "is_correct": false, "explanation": "rèn（第四声）与 nèn（第四声）声母不同（r/n），声调相同，意思是“认识”。"}, {"text": "内", "is_correct": false, "explanation": "nèi（第四声）与 nèn（第四声）韵母不同（ei/en），声调相同，意思是“里面”。"}], "explanations": {"嫩": "正确。“嫩”（nèn）指食物或植物柔软、不老。", "笨": "bèn（第四声）与 nèn（第四声）声母不同（b/n），声调相同，意思是“笨拙”。", "份": "fèn（第四声）与 nèn（第四声）声母不同（f/n），声调相同，意思是“一份”。", "认": "rèn（第四声）与 nèn（第四声）声母不同（r/n），声调相同，意思是“认识”。", "内": "nèi（第四声）与 nèn（第四声）韵母不同（ei/en），声调相同，意思是“里面”。"}, "sentence_index": null, "correct_answer": "嫩"}, "level_3": {"options": [{"text": "嫩", "is_correct": true, "explanation": "正确。“嫩”指菜还不老，适合“趁……的时候吃”。"}, {"text": "老", "is_correct": false, "explanation": "语义：“老”指菜已老、口感韧，与“趁……吃”的要求相反。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，不能描述菜的成熟状态，句子说不通。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”不用来描述菜的成熟程度，不能说“趁重的时候吃”。"}], "explanations": {"嫩": "正确。“嫩”指菜还不老，适合“趁……的时候吃”。", "老": "语义：“老”指菜已老、口感韧，与“趁……吃”的要求相反。", "苦": "语义：“苦”指味道，不能描述菜的成熟状态，句子说不通。", "重": "搭配：“重”不用来描述菜的成熟程度，不能说“趁重的时候吃”。"}, "sentence_index": 6, "correct_answer": "嫩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根油条很嫩，咬下去咔嚓响。", "explanation": "这里应该用〈脆〉。咬下去咔嚓响要说“脆”，油条这类食物不能用“嫩”来形容。"}, {"text": "这件衣服是嫩黑色的，很显瘦。", "explanation": "这里应该用〈深〉。“嫩”形容颜色时指浅淡鲜亮，黑色不能用“嫩”。"}, {"text": "他跑步很嫩，一下子就跑完了。", "explanation": "这里应该用〈快〉。“嫩”形容柔软或未长老的东西，不能形容跑步的速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块猪肉嫩很，炒着好吃。", "corrected_sentence": "这块猪肉很嫩，炒着好吃。", "error_description": "“很”放在了“嫩”之后。形容词作谓语前应先说“很”，应为“很嫩”，不能说“嫩很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一块很嫩牛肉。", "corrected_sentence": "我买了一块很嫩的牛肉。", "error_description": "形容词“很嫩”修饰名词时，中间要加“的”。应说“很嫩的牛肉”，不能说“很嫩牛肉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
