INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大很漂亮、国王住的房子。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "国王住在宫里，那里又大又漂亮。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次进宫，觉得什么都很新奇。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宫里有很多漂亮的花园。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王每天早上出宫，去看他的百姓。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宫里的房间很多，我差点迷路。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王子从小在宫里长大。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说宫里的地板是金子做的。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主想出宫玩，国王不同意。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宫外有一条河，宫里有一座花园。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王带着客人在宫里走了一圈。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宮", "label": "繁体"}, {"form": "皇宫", "label": "复合"}, {"form": "宫殿", "label": "复合"}], "register": "中性", "sense_fingerprint": "国王居住的又大又漂亮的房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫（gōng）：国王居住的宫殿，正确答案。"}, {"text": "空", "is_correct": false, "explanation": "空（kōng）：声母 k 送气，与 gōng 的 g 不同，意思是“空”。"}, {"text": "刚", "is_correct": false, "explanation": "刚（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“刚才、刚好”。"}, {"text": "干", "is_correct": false, "explanation": "干（gān）：韵母 an，与 gōng 的 ong 不同，意思是“干燥、干活”。"}, {"text": "共", "is_correct": false, "explanation": "共（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“共同”。"}], "explanations": {"宫": "宫（gōng）：国王居住的宫殿，正确答案。", "空": "空（kōng）：声母 k 送气，与 gōng 的 g 不同，意思是“空”。", "刚": "刚（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“刚才、刚好”。", "干": "干（gān）：韵母 an，与 gōng 的 ong 不同，意思是“干燥、干活”。", "共": "共（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“共同”。"}, "sentence_index": null, "correct_answer": "宫"}, "level_3": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫：帝王居住的大型建筑，与“国王住在……里，那里又大又漂亮”的语境一致。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱是关押犯人的地方，国王不会住在那里，也不会“又大又漂亮”。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是学习的场所，与国王的居住身份不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“又大又漂亮”通常不用来形容厨房，而且厨房不是国王的住处。"}], "explanations": {"宫": "宫：帝王居住的大型建筑，与“国王住在……里，那里又大又漂亮”的语境一致。", "监狱": "语义：监狱是关押犯人的地方，国王不会住在那里，也不会“又大又漂亮”。", "学校": "语义：学校是学习的场所，与国王的居住身份不符。", "厨房": "搭配：“又大又漂亮”通常不用来形容厨房，而且厨房不是国王的住处。"}, "sentence_index": 0, "correct_answer": "宫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的宫很小，只有两间房。", "explanation": "这里应该用〈房子〉。宫专指帝王居住的宫殿，普通人家的住所不能叫宫。"}, {"text": "这位大臣的宫很大，院子里有几棵老树。", "explanation": "这里应该用〈府〉。宫专指帝王居住的宫殿，大臣的住宅应叫府，不能叫宫。"}, {"text": "那里有一只宫，又大又漂亮。", "explanation": "量词错误：宫殿是大型建筑，应该用“座”，“只”多用于动物和小件物品，不能用于宫殿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫（gōng）：国王居住的宫殿，正确答案。"}, {"text": "烘", "is_correct": false, "explanation": "烘（hōng）：声母 h 与 gōng 的 g 不同，意思是“烘烤”。"}, {"text": "巩", "is_correct": false, "explanation": "巩（gǒng）：声调为第三声，与 gōng 的第一声不同，意思是“巩固”。"}, {"text": "缸", "is_correct": false, "explanation": "缸（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“水缸”。"}, {"text": "贡", "is_correct": false, "explanation": "贡（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“进贡、贡献”。"}], "explanations": {"宫": "宫（gōng）：国王居住的宫殿，正确答案。", "烘": "烘（hōng）：声母 h 与 gōng 的 g 不同，意思是“烘烤”。", "巩": "巩（gǒng）：声调为第三声，与 gōng 的第一声不同，意思是“巩固”。", "缸": "缸（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“水缸”。", "贡": "贡（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“进贡、贡献”。"}, "sentence_index": null, "correct_answer": "宫"}, "level_3": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫：帝王居住的大型建筑，与“听说……里的地板是金子做的”的语境一致。"}, {"text": "草棚", "is_correct": false, "explanation": "语义：草棚是简陋的小屋，与“地板是金子做的”的说法矛盾。"}, {"text": "牛棚", "is_correct": false, "explanation": "语义：牛棚是养牛的地方，不可能有金子做的地板。"}, {"text": "垃圾场", "is_correct": false, "explanation": "语义：垃圾场堆放废弃物，不可能有金子做的地板，与“听说……”的语境也不符。"}], "explanations": {"宫": "宫：帝王居住的大型建筑，与“听说……里的地板是金子做的”的语境一致。", "草棚": "语义：草棚是简陋的小屋，与“地板是金子做的”的说法矛盾。", "牛棚": "语义：牛棚是养牛的地方，不可能有金子做的地板。", "垃圾场": "语义：垃圾场堆放废弃物，不可能有金子做的地板，与“听说……”的语境也不符。"}, "sentence_index": 6, "correct_answer": "宫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的宫很大，有一个大院子。", "explanation": "这里应该用〈宅子〉。宫专指帝王居住的宫殿，普通人家的住宅不能叫宫。"}, {"text": "我们住的宫很便宜，服务也不错。", "explanation": "这里应该用〈旅馆〉。宫专指帝王居住的宫殿，普通旅馆不能叫宫。"}, {"text": "这套宫在市中心，交通很方便。", "explanation": "这里应该用〈公寓〉。宫专指帝王居住的宫殿，普通公寓不能叫宫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们参观了一条很大的宫。", "corrected_sentence": "我们参观了一座很大的宫。", "error_description": "量词错误：“宫”是大型建筑，应说“一座宫”；“条”用于河流、道路等长条形事物，不能用来数宫殿。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们宫把打扫干净了。", "corrected_sentence": "他们把宫打扫干净了。", "error_description": "语序错误：“把”字句中，“把”应放在宾语“宫”之前，说“把宫打扫干净”，不能说“宫把打扫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
