INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "帝王居住的高大华丽的建筑；宫殿。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "皇帝住的宫高大华丽，一般人进不去。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，大臣每天早上要进宫见皇帝。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宫里有高高的墙，红红的门。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝很少出宫，也很少见外面的人。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用了十年才把宫修好。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事发生在很久以前的宫里。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪落在这座宫的屋顶上，一片白。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在宫外等了一天，也没见到皇帝。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是宫里的厨师，每天为皇帝做饭。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的皇帝一出生就住在宫里。", "target_word": "宫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宮", "label": "繁体"}, {"form": "皇宫", "label": "复合"}, {"form": "宫殿", "label": "复合"}], "register": "中性", "sense_fingerprint": "帝王居住的高大华丽的宫殿建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫（gōng）：帝王居住的宫殿，正确答案。"}, {"text": "空", "is_correct": false, "explanation": "空（kōng）：声母 k 送气，与 gōng 的 g 不同，意思是“空”。"}, {"text": "缸", "is_correct": false, "explanation": "缸（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“水缸”。"}, {"text": "干", "is_correct": false, "explanation": "干（gān）：韵母 an，与 gōng 的 ong 不同，意思是“干燥、干活”。"}, {"text": "贡", "is_correct": false, "explanation": "贡（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“进贡、贡献”。"}], "explanations": {"宫": "宫（gōng）：帝王居住的宫殿，正确答案。", "空": "空（kōng）：声母 k 送气，与 gōng 的 g 不同，意思是“空”。", "缸": "缸（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“水缸”。", "干": "干（gān）：韵母 an，与 gōng 的 ong 不同，意思是“干燥、干活”。", "贡": "贡（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“进贡、贡献”。"}, "sentence_index": null, "correct_answer": "宫"}, "level_3": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫：帝王居住的高大华丽的建筑，与“高大华丽，一般人进不去”一致。"}, {"text": "草屋", "is_correct": false, "explanation": "语义：草屋简陋，与“高大华丽”的描述相反。"}, {"text": "车库", "is_correct": false, "explanation": "搭配：“高大华丽”通常用来形容宫殿、楼宇，不用于形容车库。"}, {"text": "牢房", "is_correct": false, "explanation": "语义：牢房是关押犯人的地方，与“皇帝住的……高大华丽”的描述完全相反。"}], "explanations": {"宫": "宫：帝王居住的高大华丽的建筑，与“高大华丽，一般人进不去”一致。", "草屋": "语义：草屋简陋，与“高大华丽”的描述相反。", "车库": "搭配：“高大华丽”通常用来形容宫殿、楼宇，不用于形容车库。", "牢房": "语义：牢房是关押犯人的地方，与“皇帝住的……高大华丽”的描述完全相反。"}, "sentence_index": 0, "correct_answer": "宫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的宫很旧，但很温暖。", "explanation": "这里应该用〈民房〉。宫专指帝王居住的宫殿，普通人家的住所不能叫宫。"}, {"text": "我们住的宫在车站旁边，很方便。", "explanation": "这里应该用〈旅馆〉。宫专指帝王居住的宫殿，普通旅馆不能叫宫。"}, {"text": "前面有一只宫，非常高大。", "explanation": "量词错误：宫殿要用“座”，“只”多用于动物和小件物品，不能用于宫殿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫（gōng）：帝王居住的宫殿，正确答案。"}, {"text": "烘", "is_correct": false, "explanation": "烘（hōng）：声母 h 与 gōng 的 g 不同，意思是“烘烤”。"}, {"text": "巩", "is_correct": false, "explanation": "巩（gǒng）：声调为第三声，与 gōng 的第一声不同，意思是“巩固”。"}, {"text": "刚", "is_correct": false, "explanation": "刚（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“刚才、刚好”。"}, {"text": "共", "is_correct": false, "explanation": "共（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“共同”。"}], "explanations": {"宫": "宫（gōng）：帝王居住的宫殿，正确答案。", "烘": "烘（hōng）：声母 h 与 gōng 的 g 不同，意思是“烘烤”。", "巩": "巩（gǒng）：声调为第三声，与 gōng 的第一声不同，意思是“巩固”。", "刚": "刚（gāng）：韵母 ang，与 gōng 的 ong 不同，意思是“刚才、刚好”。", "共": "共（gòng）：声调为第四声，与 gōng 的第一声不同，意思是“共同”。"}, "sentence_index": null, "correct_answer": "宫"}, "level_3": {"options": [{"text": "宫", "is_correct": true, "explanation": "宫：帝王居住的高大建筑，与“大雪落在这座……的屋顶上”的语境一致。"}, {"text": "山", "is_correct": false, "explanation": "语义：山不会有屋顶，“这座山的屋顶”不成立。"}, {"text": "城墙", "is_correct": false, "explanation": "语义：城墙没有屋顶，与“屋顶上一片白”矛盾。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：雕像一般不说有屋顶，与“屋顶上一片白”搭配不当。"}], "explanations": {"宫": "宫：帝王居住的高大建筑，与“大雪落在这座……的屋顶上”的语境一致。", "山": "语义：山不会有屋顶，“这座山的屋顶”不成立。", "城墙": "语义：城墙没有屋顶，与“屋顶上一片白”矛盾。", "雕像": "搭配：雕像一般不说有屋顶，与“屋顶上一片白”搭配不当。"}, "sentence_index": 6, "correct_answer": "宫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家宫的服务很好，客人都很满意。", "explanation": "这里应该用〈酒店〉。宫专指帝王居住的宫殿，酒店不能叫宫。"}, {"text": "这位王爷的宫里种满了花，很气派。", "explanation": "这里应该用〈王府〉。宫专指帝王居住的宫殿，王爷的住宅应叫王府，不能叫宫。"}, {"text": "我住的宫在三楼，没有电梯。", "explanation": "这里应该用〈公寓〉。宫专指帝王居住的宫殿，普通居民楼不能叫宫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只宫建于明朝。", "corrected_sentence": "这座宫建于明朝。", "error_description": "量词错误：宫殿是大型建筑，应说“这座宫”；“只”用于动物和小件物品，不能用来数宫殿。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把宫修了好。", "corrected_sentence": "工人们把宫修好了。", "error_description": "补语错误：结果补语“好”应紧接动词，说“修好”，再加“了”，不能说“修了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
