INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "子时是半夜十一点到一点的这段时间。", "primary_collocate": null, "pronunciation": "zǐ shí", "ipa": "tsɿ˨˩˦ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "子时是半夜十一点到一点。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说子时前一定要睡觉。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医说，子时睡觉对身体好。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我到子时才睡着。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已经子时了，你快去睡吧。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子时的街上很安静，没有人。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天子时以前就睡了。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他加班到子时，才回到家。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子时一过，新的一天就开始了。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我们子时放了鞭炮。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "半夜十一点到一点的这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "子时", "is_correct": true, "explanation": "正确。子时指半夜十一点到一点的这段时间。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午是中午，与“半夜”冲突。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：黎明是天亮的时候，与“半夜”冲突。"}, {"text": "一刻", "is_correct": false, "explanation": "搭配：“一刻”是十五分钟的长度，不能指一段两小时的时间。"}], "explanations": {"子时": "正确。子时指半夜十一点到一点的这段时间。", "正午": "语义：正午是中午，与“半夜”冲突。", "黎明": "语义：黎明是天亮的时候，与“半夜”冲突。", "一刻": "搭配：“一刻”是十五分钟的长度，不能指一段两小时的时间。"}, "sentence_index": 0, "correct_answer": "子时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我熬到子时两点才睡。", "explanation": "这里应该用〈凌晨〉。子时只到夜里一点，两点已是凌晨，不能说子时。"}, {"text": "我每天在子时吃午饭。", "explanation": "这里应该用〈午时〉。子时是半夜，中午吃午饭应说午时。"}, {"text": "早上七点，子时就到了。", "explanation": "这里应该用〈清晨〉。子时是半夜，早上七点不能说子时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "子时", "is_correct": true, "explanation": "正确。子时是半夜十一点到一点，爷爷每天在这段时间之前就睡了。"}, {"text": "周末", "is_correct": false, "explanation": "语义：“周末”不是每天都有，与“每天”冲突。"}, {"text": "春节", "is_correct": false, "explanation": "语义：“春节”一年只有一次，与“每天”冲突。"}, {"text": "一刻", "is_correct": false, "explanation": "搭配：“一刻”是十五分钟的长度，不能作“以前”所指的时间点。"}], "explanations": {"子时": "正确。子时是半夜十一点到一点，爷爷每天在这段时间之前就睡了。", "周末": "语义：“周末”不是每天都有，与“每天”冲突。", "春节": "语义：“春节”一年只有一次，与“每天”冲突。", "一刻": "搭配：“一刻”是十五分钟的长度，不能作“以前”所指的时间点。"}, "sentence_index": 6, "correct_answer": "子时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子时六点，我们放了鞭炮。", "explanation": "这里应该用〈傍晚〉。子时指夜里十一点到一点，六点是傍晚，不在子时之内。"}, {"text": "过年的时候，我们子时才吃午饭。", "explanation": "这里应该用〈正午〉。午饭应在中午，子时是深夜，不能说吃午饭。"}, {"text": "子时三点，人们都去买菜了。", "explanation": "这里应该用〈下午〉。子时指夜里十一点到一点，三点不在其中，白天买菜应说下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他到子时的才睡着。", "corrected_sentence": "他到子时才睡着。", "error_description": "多余的“的”。“到子时”后面直接接“才”，中间不能加“的”，应说“他到子时才睡着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总是到子时学习。", "corrected_sentence": "她总是在子时学习。", "error_description": "介词误用。表示动作发生的时间应用“在”；“到”引出时间终点，不能直接修饰动作。应说“她总是在子时学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
