INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时十二时辰之一，指夜里十一点到次日凌晨一点。", "primary_collocate": null, "pronunciation": "zǐ shí", "ipa": "tsɿ˨˩˦ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "古时候，夜里十一点到一点叫子时。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人说的子时，就是现在的半夜。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二时辰里，子时排在第一个。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里写着，他总是到子时才睡下。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的更夫在子时打更。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子时一过，就是丑时了。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人认为子时要睡觉，对身体好。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本古书说，子时是一天的开始。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代，子时大概是夜里十一点。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，旧时的子时一到，街上就没人了。", "target_word": "子时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "旧时十二时辰之一，夜里十一点到一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "子时", "is_correct": true, "explanation": "正确。子时是旧时十二时辰之一，指夜里十一点到一点。"}, {"text": "午时", "is_correct": false, "explanation": "语义：午时是中午十一点到一点，与句中的“夜里”冲突。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：黎明是天快亮的时候，与“夜里十一点到一点”冲突。"}, {"text": "一刻", "is_correct": false, "explanation": "搭配：“一刻”指十五分钟，不能用来指“十一点到一点”这样的时段。"}], "explanations": {"子时": "正确。子时是旧时十二时辰之一，指夜里十一点到一点。", "午时": "语义：午时是中午十一点到一点，与句中的“夜里”冲突。", "黎明": "语义：黎明是天快亮的时候，与“夜里十一点到一点”冲突。", "一刻": "搭配：“一刻”指十五分钟，不能用来指“十一点到一点”这样的时段。"}, "sentence_index": 0, "correct_answer": "子时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天刚亮的时候，子时就来了。", "explanation": "这里应该用〈黎明〉。子时指夜里十一点到一点，天刚亮时不能说子时。"}, {"text": "古人常在子时吃午饭。", "explanation": "这里应该用〈午时〉。子时是深夜，中午吃午饭应说午时。"}, {"text": "他昨晚熬到子时四点才睡。", "explanation": "这里应该用〈凌晨〉。子时只指夜里十一点到一点，四点已是凌晨，不能说子时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "子时", "is_correct": true, "explanation": "正确。子时是旧时十二时辰之一，指夜里十一点到一点，古人认为此时睡觉对身体好。"}, {"text": "卯时", "is_correct": false, "explanation": "语义：卯时是早上五点到七点，正是起床的时候，与“要睡觉”冲突。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨是早上，与“睡觉对身体好”所说的时段冲突。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”是食物，不能作“要睡觉”的主语。"}], "explanations": {"子时": "正确。子时是旧时十二时辰之一，指夜里十一点到一点，古人认为此时睡觉对身体好。", "卯时": "语义：卯时是早上五点到七点，正是起床的时候，与“要睡觉”冲突。", "清晨": "语义：清晨是早上，与“睡觉对身体好”所说的时段冲突。", "早饭": "搭配：“早饭”是食物，不能作“要睡觉”的主语。"}, "sentence_index": 6, "correct_answer": "子时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子时六点，钟声响了。", "explanation": "这里应该用〈傍晚〉。子时指夜里十一点到一点，六点不在子时之内，应说傍晚。"}, {"text": "子时五点，他起床去跑步。", "explanation": "这里应该用〈清晨〉。子时指夜里十一点到一点，五点是清晨，不能说子时。"}, {"text": "子时七点，人们都去买菜了。", "explanation": "这里应该用〈早上〉。子时指夜里十一点到一点，七点是早上，不能用子时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨晚一直忙子时。", "corrected_sentence": "他昨晚一直忙到子时。", "error_description": "漏掉了介词“到”。“忙到子时”中“到”引出时间终点，不能省略，应说“忙到子时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们常常到子时工作。", "corrected_sentence": "我们常常在子时工作。", "error_description": "介词误用。表示动作发生的时间应用“在”；“到”引出时间终点，不能直接修饰动作。应说“我们常常在子时工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网友是在网上认识的朋友。", "primary_collocate": null, "pronunciation": "wǎng yǒu", "ipa": "wɑŋ˨˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是我在网上认识的网友。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和网友约好周末见面。", "target_word": "网友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位网友住在上海。", "target_word": "网友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的网友送了我一本书。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和网友每天晚上聊天。", "target_word": "网友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天我第一次见到了网友。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友告诉我他下个月要来北京，想和我见一面。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有一个网友在国外工作。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是网友，还没有见过面。", "target_word": "网友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给网友寄了一张明信片。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "網友", "label": "繁体"}, {"form": "网友们", "label": "复数"}], "register": "口语", "sense_fingerprint": "在网上认识的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网友", "is_correct": true, "explanation": "正确：“网友”指在网上认识的朋友，与“在网上认识的”一致。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：亲戚是血缘或婚姻关系，不会是在网上认识的人。"}, {"text": "同桌", "is_correct": false, "explanation": "搭配：“同桌”指同一张课桌的同学，与“网上认识”不搭配。"}, {"text": "父亲", "is_correct": false, "explanation": "语义：父亲是亲生或养育自己的人，不能在网上认识。"}], "explanations": {"网友": "正确：“网友”指在网上认识的朋友，与“在网上认识的”一致。", "亲戚": "语义：亲戚是血缘或婚姻关系，不会是在网上认识的人。", "同桌": "搭配：“同桌”指同一张课桌的同学，与“网上认识”不搭配。", "父亲": "语义：父亲是亲生或养育自己的人，不能在网上认识。"}, "sentence_index": 0, "correct_answer": "网友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我小学的网友，我们从小一起长大。", "explanation": "这里应该用〈同学〉。网友指在网上结识的人，不能用来说从小一起长大的小学同窗。"}, {"text": "我家的网友每天早上都和我一起去公园。", "explanation": "这里应该用〈邻居〉。网友是在网上认识的人，不住在身边，不能说“我家的网友”。"}, {"text": "这位网友是我的表哥，我们是一家人。", "explanation": "这里应该用〈亲戚〉。网友指在网上认识的朋友，不能说有血缘关系的表哥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网友", "is_correct": true, "explanation": "正确：“网友”可以作主语，说明是谁告诉我的，与句意一致。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“告诉我”需要能说话的人作主语，“食物”不能告诉人。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不能说话，无法告诉我别人的行程。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是电器，不能说话，无法告诉我消息。"}], "explanations": {"网友": "正确：“网友”可以作主语，说明是谁告诉我的，与句意一致。", "食物": "搭配：“告诉我”需要能说话的人作主语，“食物”不能告诉人。", "镜子": "语义：镜子不能说话，无法告诉我别人的行程。", "空调": "语义：空调是电器，不能说话，无法告诉我消息。"}, "sentence_index": 6, "correct_answer": "网友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的网友从小教我做人。", "explanation": "这里应该用〈父母〉。网友是在网上认识的人，不能从小教养我。"}, {"text": "我和网友在同一个村子长大，经常一起玩。", "explanation": "这里应该用〈老乡〉。网友指在网上认识的人，不能说同村长大、经常见面的人。"}, {"text": "这个网友很好用，我每天都用它修东西。", "explanation": "这里应该用〈工具〉。网友指人，不能说像工具一样好用、可以拿来修东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天认识了一只网友。", "corrected_sentence": "我昨天认识了一位网友。", "error_description": "量词错误：“网友”指人，应用量词“位”，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位网友们说这家店很好吃。", "corrected_sentence": "一位网友说这家店很好吃。", "error_description": "词尾错误：“一位”表示一个人，后面不能再加“们”；应说“一位网友说这家店很好吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
