INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89866, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "使用网络的人，即网民。", "primary_collocate": null, "pronunciation": "wǎng yǒu", "ipa": "wɑŋ˨˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "很多网友都在讨论这个新闻。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们给这部电影打了高分。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条消息让网友非常生气。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有网友说这家饭店很干净。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友留言说，他的歌很好听。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们都觉得这个办法不错。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个视频有一百万网友看过。", "target_word": "网友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位网友在网上问了一个问题。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不少网友喜欢在晚上上网聊天。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们的回答帮了他很多。", "target_word": "网友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "網友", "label": "繁体"}, {"form": "网友们", "label": "复数"}], "register": "口语", "sense_fingerprint": "使用网络的人，网民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网友", "is_correct": true, "explanation": "正确：“网友”指使用网络的人，可以“讨论新闻”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会讨论，也不能参与讨论新闻。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会讨论，与“讨论这个新闻”不符。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是电器，不会讨论新闻。"}], "explanations": {"网友": "正确：“网友”指使用网络的人，可以“讨论新闻”。", "石头": "语义：石头不会讨论，也不能参与讨论新闻。", "树": "语义：树不会讨论，与“讨论这个新闻”不符。", "灯泡": "语义：灯泡是电器，不会讨论新闻。"}, "sentence_index": 0, "correct_answer": "网友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的网友都在一楼办公。", "explanation": "这里应该用〈员工〉。网友指使用网络的人，不指在公司工作的人，“在一楼办公”说的是实际工作。"}, {"text": "这次战斗中，他的网友都牺牲了。", "explanation": "这里应该用〈战友〉。网友指使用网络的人或在网上结识的朋友，不能指一起作战、并肩牺牲的人。"}, {"text": "有个网友趁着夜色翻进了我家。", "explanation": "这里应该用〈小偷〉。网友指通过网络结识或使用网络的人，不指趁夜翻墙入室的盗贼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网友", "is_correct": true, "explanation": "正确：“网友”指使用网络的人，可以看视频，与“一百万”搭配自然。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不会看视频，句子说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能看视频。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”不指具体的看视频的人，“看过”的主体应是人，不与“人口”搭配。"}], "explanations": {"网友": "正确：“网友”指使用网络的人，可以看视频，与“一百万”搭配自然。", "电线": "语义：电线不会看视频，句子说不通。", "桌子": "语义：桌子不能看视频。", "人口": "搭配：“人口”不指具体的看视频的人，“看过”的主体应是人，不与“人口”搭配。"}, "sentence_index": 6, "correct_answer": "网友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的网友从小和我一起长大，是我的堂哥。", "explanation": "这里应该用〈亲戚〉。网友指通过网络结识或使用网络的人，不能指从小一起长大的堂哥。"}, {"text": "我和网友在同一个村里住了十年，天天一起玩。", "explanation": "这里应该用〈邻居〉。网友指在网上结识的人或使用网络的人，不能说同村住了十年、天天见面的人。"}, {"text": "这个网友的价格很便宜，我买了两个。", "explanation": "这里应该用〈商品〉。网友指人，不能说价格便宜、可以购买的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位网友们在网上提出了一个问题。", "corrected_sentence": "这位网友在网上提出了一个问题。", "error_description": "数量词错误：“这位”指一个人，后面不能加“们”表示复数；应说“这位网友在网上提出了一个问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目有一百万只网友看过。", "corrected_sentence": "这个节目有一百万网友看过。", "error_description": "量词错误：“只”多用于动物或成对、小件的物品，不能用来计量指人的“网友”；应删去“只”，说“这个节目有一百万网友看过。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "导航是告诉你该往哪儿走，帮你找到路。", "primary_collocate": null, "pronunciation": "dǎo háng", "ipa": "tau˨˩˦ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我用手机导航，很快找到了那家店。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不熟，请你帮我导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次来这个城市，全靠导航才找到酒店。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会导航，我们不会迷路。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边开车，一边让手机导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能用中文导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有网，手机就不能导航了。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他让手机导航到火车站。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先用地图导航，再走过去。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着手机导航，我们到了朋友家。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "导航了", "label": "体标"}, {"form": "导航过", "label": "体标"}, {"form": "导航仪", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手机或地图告诉人怎么走，帮人找路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导航", "is_correct": true, "explanation": "「导航」指用手机指引路线，正好对应“很快找到那家店”。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”是给手机补电，与后半句“找到那家店”没有因果关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”的主语须是人或动物，不能说“用手机睡觉”。"}, {"text": "煮饭", "is_correct": false, "explanation": "搭配：“煮饭”是动宾结构，不能用手机来煮，“用手机煮饭”说不通。"}], "explanations": {"导航": "「导航」指用手机指引路线，正好对应“很快找到那家店”。", "充电": "语义：“充电”是给手机补电，与后半句“找到那家店”没有因果关系。", "睡觉": "搭配：“睡觉”的主语须是人或动物，不能说“用手机睡觉”。", "煮饭": "搭配：“煮饭”是动宾结构，不能用手机来煮，“用手机煮饭”说不通。"}, "sentence_index": 0, "correct_answer": "导航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导游在车上热情地给我们导航历史故事。", "explanation": "这里应该用〈讲解〉。导航指引路线，不用来讲述历史；讲述历史要说〈讲解〉。"}, {"text": "店员热情地给我们导航新衣，推荐了几款。", "explanation": "这里应该用〈导购〉。导航指引路线，不用来推荐商品；陪客人挑选商品要说〈导购〉。"}, {"text": "他在台上导航乐队，动作很有力。", "explanation": "这里应该用〈指挥〉。导航指引路线，不用来指挥乐手演奏；指挥乐队要说〈指挥〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导航", "is_correct": true, "explanation": "「导航」需要网络或信号，没网时手机就不能导航，正好是这个意思。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”的主语须是人或动物，手机不能跳舞，“手机就不能跳舞了”说不通。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是人的情绪，手机不会生气，与“没有网”的条件不相关。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”的主语须是人或动物，手机不能吃饭。"}], "explanations": {"导航": "「导航」需要网络或信号，没网时手机就不能导航，正好是这个意思。", "跳舞": "搭配：“跳舞”的主语须是人或动物，手机不能跳舞，“手机就不能跳舞了”说不通。", "生气": "语义：“生气”是人的情绪，手机不会生气，与“没有网”的条件不相关。", "吃饭": "搭配：“吃饭”的主语须是人或动物，手机不能吃饭。"}, "sentence_index": 6, "correct_answer": "导航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上导航讨论，像一位主持人。", "explanation": "这里应该用〈主持〉。导航指引路线，不用来主持讨论；主持讨论要说〈主持〉。"}, {"text": "老师在操场上导航同学跑步。", "explanation": "这里应该用〈监督〉。导航指引路线，不用于管理人的行为；看着同学做事要说〈监督〉。"}, {"text": "老师课后导航学生做题。", "explanation": "这里应该用〈辅导〉。导航指引路线，不用来讲解题目；课后辅导学生要说〈辅导〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把手机导航去公园。", "corrected_sentence": "我用手机导航去公园。", "error_description": "错误形式：“我把手机导航去公园”。正确形式：“我用手机导航去公园”。“导航”指用手机指路，手机作工具要用“用”引出，不能用“把”；把“把”改为“用”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他让手机导航了到火车站。", "corrected_sentence": "他让手机导航到了火车站。", "error_description": "“了”的位置错了。正确是「导航到了火车站」，“了”放在补语“到”之后；「导航了到火车站」把“了”放在补语之前，说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
