INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89868, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引导车辆、船只或飞机等沿正确路线前进。", "primary_collocate": null, "pronunciation": "dǎo háng", "ipa": "tau˨˩˦ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "飞机靠雷达导航，晚上也能飞。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯塔帮船在夜里导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星可以给轮船导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套系统能为飞机导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上有雾，船长用仪器导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的水手靠星星导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新船用卫星导航，不会走错路。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机靠卫星导航，按预定路线飞行。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的信号为飞机导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在河上靠指南针导航。", "target_word": "导航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "导航了", "label": "体标"}, {"form": "导航过", "label": "体标"}, {"form": "导航仪", "label": "复合"}], "register": "中性", "sense_fingerprint": "用雷达、卫星等引导飞机、船只沿路线前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导航", "is_correct": true, "explanation": "「导航」指用雷达引导飞机沿航线飞行，句意通顺。"}, {"text": "充电", "is_correct": false, "explanation": "语义：雷达与充电无关，“飞机靠雷达充电”说不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”的主语须是人或动物，飞机不能洗澡。"}, {"text": "煮饭", "is_correct": false, "explanation": "搭配：“煮饭”不能说“飞机靠雷达煮饭”，飞机不会做饭。"}], "explanations": {"导航": "「导航」指用雷达引导飞机沿航线飞行，句意通顺。", "充电": "语义：雷达与充电无关，“飞机靠雷达充电”说不通。", "洗澡": "搭配：“洗澡”的主语须是人或动物，飞机不能洗澡。", "煮饭": "搭配：“煮饭”不能说“飞机靠雷达煮饭”，飞机不会做饭。"}, "sentence_index": 0, "correct_answer": "导航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆的讲解员为我们导航文物。", "explanation": "这里应该用〈讲解〉。导航是引导路线，不用来讲解展品；讲解文物要说〈讲解〉。"}, {"text": "舞蹈老师在台上导航学员的动作，很认真。", "explanation": "这里应该用〈指导〉。导航指引路线，不用来指点动作；指点学员动作要说〈指导〉。"}, {"text": "船长导航水手按时工作。", "explanation": "这里应该用〈监督〉。导航指引路线，不用于管理水手的工作；监督工作要说〈监督〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导航", "is_correct": true, "explanation": "「导航」指用卫星引导船只，与“不会走错路”前后呼应。"}, {"text": "烧水", "is_correct": false, "explanation": "语义：烧水是加热，与卫星、走错路没有关系。"}, {"text": "上课", "is_correct": false, "explanation": "搭配：“上课”的主语须是学生或老师，船不能上课。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：船和卫星不能唱歌，“新船用卫星唱歌”搭配不当。"}], "explanations": {"导航": "「导航」指用卫星引导船只，与“不会走错路”前后呼应。", "烧水": "语义：烧水是加热，与卫星、走错路没有关系。", "上课": "搭配：“上课”的主语须是学生或老师，船不能上课。", "唱歌": "搭配：船和卫星不能唱歌，“新船用卫星唱歌”搭配不当。"}, "sentence_index": 6, "correct_answer": "导航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长导航全校老师，工作很认真。", "explanation": "这里应该用〈领导〉。导航是引导路线，不用来管理人员；带领全校老师要说〈领导〉。"}, {"text": "工人在仓库导航货物，分类很仔细。", "explanation": "这里应该用〈分拣〉。导航指引路线，不用来分类货物；分类货物要说〈分拣〉。"}, {"text": "教练导航新队员，训练很认真。", "explanation": "这里应该用〈培训〉。导航指引路线，不用来培养队员；培训队员要说〈培训〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统导航的很准确。", "corrected_sentence": "这套系统导航得很准确。", "error_description": "补语标记用错了。补语前应用“得”，“的”用于定语，「导航的很准确」不成立；正确是「导航得很准确」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这艘船用卫星导航着三次。", "corrected_sentence": "这艘船用卫星导航过三次。", "error_description": "动态助词用错了。表示经历某动作几次要用“过”，“着”表示动作持续，「导航着三次」说不通；正确是「导航过三次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
