INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岩石是山上又大又硬的石头。", "primary_collocate": null, "pronunciation": "yán shí", "ipa": "jɛn˧˥ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "山上有一块又大又硬的岩石。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上岩石，看远处的风景。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岩石很硬，我用手搬不动。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在岩石上休息了一会儿。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有很多大岩石。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟站在高高的岩石上唱歌。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，岩石上湿湿的。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着山路走，看见了一块大岩石。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山路上绊到了一块大岩石，差点摔倒。", "target_word": "岩石", "complexity_tier": "T3", "furigana": "tā zài shān lù shàng bàn dào le yí kuài dà yán shí, chà diǎn shuāi dǎo。", "sentence_source": "generated"}, {"text": "岩石的上面长着一些小草。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "岩石层", "label": "复合"}, {"form": "岩石圈", "label": "复合"}], "register": "中性", "sense_fingerprint": "山上或河边又大又硬的石头，日常所见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。yán shí 即岩石，指山上或河边又大又硬的石头。"}, {"text": "演示", "is_correct": false, "explanation": "演示（yǎn shì）两个音节的声调都与岩石（yán shí）不同（第三声、第四声 对 第二声），意思是展示操作或说明。"}, {"text": "厌食", "is_correct": false, "explanation": "厌食（yàn shí）第一个音节声调不同（第四声 对 第二声），意思是食欲减退。"}, {"text": "严师", "is_correct": false, "explanation": "严师（yán shī）第二个音节声调不同（第一声 对 第二声），意思是要求严格的老师。"}, {"text": "严实", "is_correct": false, "explanation": "严实（yán shi）第二个音节为轻声，与岩石（yán shí）的第二声不同，意思是紧密、不透风。"}], "explanations": {"岩石": "正确。yán shí 即岩石，指山上或河边又大又硬的石头。", "演示": "演示（yǎn shì）两个音节的声调都与岩石（yán shí）不同（第三声、第四声 对 第二声），意思是展示操作或说明。", "厌食": "厌食（yàn shí）第一个音节声调不同（第四声 对 第二声），意思是食欲减退。", "严师": "严师（yán shī）第二个音节声调不同（第一声 对 第二声），意思是要求严格的老师。", "严实": "严实（yán shi）第二个音节为轻声，与岩石（yán shí）的第二声不同，意思是紧密、不透风。"}, "sentence_index": null, "correct_answer": "岩石"}, "level_3": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。“山上有一块又大又硬的岩石”，岩石指山上又大又硬的石头。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子没有软硬之分，不会是又大又硬的东西。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：量词“块”指成块的固体，雨不能说一块雨。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶薄而软，不会是又大又硬的东西。"}], "explanations": {"岩石": "正确。“山上有一块又大又硬的岩石”，岩石指山上又大又硬的石头。", "影子": "语义：影子没有软硬之分，不会是又大又硬的东西。", "雨": "搭配：量词“块”指成块的固体，雨不能说一块雨。", "树叶": "语义：树叶薄而软，不会是又大又硬的东西。"}, "sentence_index": 0, "correct_answer": "岩石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "岩石在天上慢慢飘动。", "explanation": "这里应该用〈白云〉。白云轻而蓬松，能在天上飘动；岩石重而坚硬，不会飘在天上。"}, {"text": "孩子们在夏天吃岩石。", "explanation": "这里应该用〈冰淇淋〉。岩石不能吃，夏天孩子们吃的应是冰淇淋。"}, {"text": "山上有一把岩石。", "explanation": "这里应该用〈块〉。“把”用于带柄的器具，岩石这类成块的实物要用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。yán shí 即岩石，指山上或河边又大又硬的石头。"}, {"text": "掩饰", "is_correct": false, "explanation": "掩饰（yǎn shì）两个音节的声调都不同（第三声、第四声 对 第二声），意思是遮盖真相或情绪。"}, {"text": "厌世", "is_correct": false, "explanation": "厌世（yàn shì）两个音节的声调都不同（第四声 对 第二声），意思是对生活感到厌倦。"}, {"text": "严师", "is_correct": false, "explanation": "严师（yán shī）第二个音节声调不同（第一声 对 第二声），意思是要求严格的老师。"}], "explanations": {"岩石": "正确。yán shí 即岩石，指山上或河边又大又硬的石头。", "掩饰": "掩饰（yǎn shì）两个音节的声调都不同（第三声、第四声 对 第二声），意思是遮盖真相或情绪。", "厌世": "厌世（yàn shì）两个音节的声调都不同（第四声 对 第二声），意思是对生活感到厌倦。", "严师": "严师（yán shī）第二个音节声调不同（第一声 对 第二声），意思是要求严格的老师。"}, "sentence_index": null, "correct_answer": "岩石"}, "level_3": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。“下雨以后，岩石上湿湿的”，岩石是露在外面、可以被雨淋湿的石头。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳在天上，不会因为下雨而湿。"}, {"text": "风", "is_correct": false, "explanation": "配价：“湿”的主语必须是能被打湿的物体，风不能被打湿。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以被打湿的表面，“天空上湿湿的”不合常理。"}], "explanations": {"岩石": "正确。“下雨以后，岩石上湿湿的”，岩石是露在外面、可以被雨淋湿的石头。", "太阳": "语义：太阳在天上，不会因为下雨而湿。", "风": "配价：“湿”的主语必须是能被打湿的物体，风不能被打湿。", "天空": "语义：天空不是可以被打湿的表面，“天空上湿湿的”不合常理。"}, "sentence_index": 6, "correct_answer": "岩石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "岩石在风里轻轻摇摆。", "explanation": "这里应该用〈花朵〉。花朵柔软轻盈，会在风里摇摆；岩石又大又硬，不会在风中摇摆。"}, {"text": "他在河边用岩石打水漂。", "explanation": "这里应该用〈石子〉。打水漂要用扁平小巧的石子，岩石又大又硬，扔不出去，不能用来打水漂。"}, {"text": "他手里拿着一条岩石。", "explanation": "这里应该用〈块〉。“条”用于细长的东西，岩石这类大块的实物要用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我坐在一只大岩石上看书。", "corrected_sentence": "我坐在一块大岩石上看书。", "error_description": "“岩石”用量词“块”。“只”多用于动物或成对的东西，不能用于岩石。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多岩石们从山上滚了下来。", "corrected_sentence": "很多岩石从山上滚了下来。", "error_description": "“岩石”是无生命的事物，不能加“们”表示复数，应直接说“很多岩石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
