INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "构成地壳的坚硬的矿物集合体，如花岗岩、石灰岩等。", "primary_collocate": null, "pronunciation": "yán shí", "ipa": "jɛn˧˥ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "地壳主要由岩石构成。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花岗岩是一种很硬的岩石。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地质学家在山上采集了岩石样本。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岩石经过很多年会慢慢变成沙子。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块岩石里有很多矿物。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山喷出的热岩浆冷却后会变成岩石。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究岩石来了解地球的历史。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石灰岩是岩石的一种，常见于南方。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一带的岩石主要是花岗岩和石灰岩。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种岩石很坚硬，不容易打碎。", "target_word": "岩石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "岩石层", "label": "复合"}, {"form": "岩石圈", "label": "复合"}], "register": "中性", "sense_fingerprint": "地质学意义上构成地壳的矿物集合体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。yán shí 即岩石，指构成地壳的坚硬矿物集合体。"}, {"text": "演示", "is_correct": false, "explanation": "演示（yǎn shì）两个音节的声调都与岩石（yán shí）不同（第三声、第四声 对 第二声），意思是展示操作或说明。"}, {"text": "厌食", "is_correct": false, "explanation": "厌食（yàn shí）第一个音节声调不同（第四声 对 第二声），意思是食欲减退。"}, {"text": "严师", "is_correct": false, "explanation": "严师（yán shī）第二个音节声调不同（第一声 对 第二声），意思是要求严格的老师。"}, {"text": "掩饰", "is_correct": false, "explanation": "掩饰（yǎn shì）两个音节的声调都不同（第三声、第四声 对 第二声），意思是遮盖真相或情绪。"}, {"text": "严实", "is_correct": false, "explanation": "严实（yán shi）第二个音节为轻声，与岩石（yán shí）的第二声不同，意思是紧密、不透风。"}], "explanations": {"岩石": "正确。yán shí 即岩石，指构成地壳的坚硬矿物集合体。", "演示": "演示（yǎn shì）两个音节的声调都与岩石（yán shí）不同（第三声、第四声 对 第二声），意思是展示操作或说明。", "厌食": "厌食（yàn shí）第一个音节声调不同（第四声 对 第二声），意思是食欲减退。", "严师": "严师（yán shī）第二个音节声调不同（第一声 对 第二声），意思是要求严格的老师。", "掩饰": "掩饰（yǎn shì）两个音节的声调都不同（第三声、第四声 对 第二声），意思是遮盖真相或情绪。", "严实": "严实（yán shi）第二个音节为轻声，与岩石（yán shí）的第二声不同，意思是紧密、不透风。"}, "sentence_index": null, "correct_answer": "岩石"}, "level_3": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。“地壳主要由岩石构成”，岩石即构成地壳的矿物集合体。"}, {"text": "空气", "is_correct": false, "explanation": "语义：地壳是坚硬的岩层，不可能主要由空气构成。"}, {"text": "水", "is_correct": false, "explanation": "语义：地壳的主体是岩石，不能说主要由水构成。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材来自树木，地壳不是由木材构成的。"}], "explanations": {"岩石": "正确。“地壳主要由岩石构成”，岩石即构成地壳的矿物集合体。", "空气": "语义：地壳是坚硬的岩层，不可能主要由空气构成。", "水": "语义：地壳的主体是岩石，不能说主要由水构成。", "木材": "语义：木材来自树木，地壳不是由木材构成的。"}, "sentence_index": 0, "correct_answer": "岩石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在河边捡了一只岩石。", "explanation": "这里应该用〈块〉。“只”多用于动物或成对的东西，岩石这类成块的实物要用“块”。"}, {"text": "孩子们在河边捡岩石打水漂。", "explanation": "这里应该用〈石子〉。打水漂要用扁平小巧的石子，岩石又大又硬，扔不出去，不能用来打水漂。"}, {"text": "屋子里飘满了岩石。", "explanation": "这里应该用〈灰尘〉。灰尘轻而细小，能飘在空中；岩石重而坚硬，不会飘满屋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。yán shí 即岩石，指构成地壳的坚硬矿物集合体。"}, {"text": "演示", "is_correct": false, "explanation": "演示（yǎn shì）两个音节的声调都与岩石（yán shí）不同（第三声、第四声 对 第二声），意思是展示操作或说明。"}, {"text": "厌世", "is_correct": false, "explanation": "厌世（yàn shì）两个音节的声调都不同（第四声 对 第二声），意思是对生活感到厌倦。"}, {"text": "验视", "is_correct": false, "explanation": "验视（yàn shì）两个音节的声调都与岩石（yán shí）不同（第四声、第四声 对 第二声、第二声），意思是检查、察看。"}], "explanations": {"岩石": "正确。yán shí 即岩石，指构成地壳的坚硬矿物集合体。", "演示": "演示（yǎn shì）两个音节的声调都与岩石（yán shí）不同（第三声、第四声 对 第二声），意思是展示操作或说明。", "厌世": "厌世（yàn shì）两个音节的声调都不同（第四声 对 第二声），意思是对生活感到厌倦。", "验视": "验视（yàn shì）两个音节的声调都与岩石（yán shí）不同（第四声、第四声 对 第二声、第二声），意思是检查、察看。"}, "sentence_index": null, "correct_answer": "岩石"}, "level_3": {"options": [{"text": "岩石", "is_correct": true, "explanation": "正确。“研究岩石”即研究构成地壳的矿物集合体，借此了解地球历史。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：糖果不能作为了解地球历史的研究对象。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包与地球历史无关，句子要表达的是通过研究了解地球的历史。"}, {"text": "歌曲", "is_correct": false, "explanation": "配价：“研究”的宾语应是能提供地质证据的实物或资料，歌曲不能充当。"}], "explanations": {"岩石": "正确。“研究岩石”即研究构成地壳的矿物集合体，借此了解地球历史。", "糖果": "语义：糖果不能作为了解地球历史的研究对象。", "面包": "语义：面包与地球历史无关，句子要表达的是通过研究了解地球的历史。", "歌曲": "配价：“研究”的宾语应是能提供地质证据的实物或资料，歌曲不能充当。"}, "sentence_index": 6, "correct_answer": "岩石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "岩石从天上慢慢飘下来。", "explanation": "这里应该用〈雪花〉。雪花轻，会从天上慢慢飘下；岩石重而坚硬，不会飘落。"}, {"text": "岩石在杯子里慢慢融化了。", "explanation": "这里应该用〈冰块〉。冰块在常温下会慢慢融化，岩石不会。"}, {"text": "他在路上搬回了一张岩石。", "explanation": "这里应该用〈块〉。“张”用于纸张、桌子等平面的东西，岩石这类成块的实物要用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
