INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海边有很多岩石们，颜色各不相同。", "corrected_sentence": "海边有很多岩石，颜色各不相同。", "error_description": "“岩石”是无生命的事物，不能加“们”表示复数，应直接说“很多岩石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
