INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学校规定的各门学科及教学安排。", "primary_collocate": null, "pronunciation": "kè chéng", "ipa": "kʰɤ˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学校的课程是教育部门定的。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学的课程里有语文和数学。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的课程安排得很合理。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要改革课程,让学生多做实验。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家规定,小学必须有体育课程。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中学的课程比小学难多了。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们学校的课程包括语文、数学和英语。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校新增加了一门艺术课程。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的课程太多,压力很大。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师根据课程要求准备教学内容。", "target_word": "课程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "課程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校规定的学科设置和教学安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "课程", "is_correct": true, "explanation": "正确答案。听到的是“课程”kè chéng，指学校规定的学科和教学安排。"}, {"text": "客场", "is_correct": false, "explanation": "chǎng（第三声）与 chéng（第二声）韵母和声调都不同，意思是客场（比赛在对方场地进行）。"}, {"text": "合成", "is_correct": false, "explanation": "hé（第二声）与 kè（第四声）声母和声调不同，意思是合成。"}, {"text": "可乘", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是可以利用的（如“可乘之机”）。"}], "explanations": {"课程": "正确答案。听到的是“课程”kè chéng，指学校规定的学科和教学安排。", "客场": "chǎng（第三声）与 chéng（第二声）韵母和声调都不同，意思是客场（比赛在对方场地进行）。", "合成": "hé（第二声）与 kè（第四声）声母和声调不同，意思是合成。", "可乘": "kě（第三声）与 kè（第四声）声调不同，意思是可以利用的（如“可乘之机”）。"}, "sentence_index": null, "correct_answer": "课程"}, "level_3": {"options": [{"text": "课程", "is_correct": true, "explanation": "正确答案。“学校的课程是教育部门定的”指学校规定的学科和教学安排。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是学校的学科设置，不能由教育部门规定，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以由教育部门制定的内容，“学校的空气是教育部门定的”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是个人物品，不是学科或教学安排，与“教育部门定的”这类规定不符。"}], "explanations": {"课程": "正确答案。“学校的课程是教育部门定的”指学校规定的学科和教学安排。", "天气": "语义：天气不是学校的学科设置，不能由教育部门规定，句子说不通。", "空气": "语义：空气不是可以由教育部门制定的内容，“学校的空气是教育部门定的”说不通。", "手机": "语义：手机是个人物品，不是学科或教学安排，与“教育部门定的”这类规定不符。"}, "sentence_index": 0, "correct_answer": "课程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把课程放进了冰箱。", "explanation": "这里应该用〈饮料〉。课程是学科和教学安排，不是东西，不能放进冰箱。"}, {"text": "学校食堂今天煮了新课程。", "explanation": "这里应该用〈菜〉。课程是学科和教学安排，不能下锅煮；食堂煮的是菜。"}, {"text": "老师今天布置了很多课程。", "explanation": "这里应该用〈作业〉。布置的是要完成的题目，“课程”是学科，不能布置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课程", "is_correct": true, "explanation": "正确答案。“他们学校的课程包括语文、数学和英语”指学校的学科设置。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不属于学校的教学内容，“包括语文、数学和英语”说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“包括”后面接的是学科，不接家具，“椅子包括语文”说不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是学科，不能与“语文、数学和英语”并列。"}], "explanations": {"课程": "正确答案。“他们学校的课程包括语文、数学和英语”指学校的学科设置。", "雨": "语义：雨不属于学校的教学内容，“包括语文、数学和英语”说不通。", "椅子": "搭配：“包括”后面接的是学科，不接家具，“椅子包括语文”说不通。", "水果": "语义：水果是食物，不是学科，不能与“语文、数学和英语”并列。"}, "sentence_index": 6, "correct_answer": "课程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的课程很好吃。", "explanation": "这里应该用〈菜〉。课程指学科和教学安排，不能指可以吃的菜。"}, {"text": "他每天给课程浇水。", "explanation": "这里应该用〈花草〉。浇水的是植物，课程不是植物，不能浇水。"}, {"text": "妈妈用课程做了一碗面条。", "explanation": "这里应该用〈面粉〉。课程不能当作食材，做面条要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校新增了一节体育课程。", "corrected_sentence": "学校新增了一门体育课程。", "error_description": "量词错误：“课程”应搭配量词“门”，不用“节”。错误形式是“一节体育课程”，正确形式是“一门体育课程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的课程们很多，学生的负担很重。", "corrected_sentence": "学校的课程很多，学生的负担很重。", "error_description": "词缀错误：“们”只用于指人的名词，不能加在“课程”后面。错误形式是“课程们”，正确形式是“课程”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
