INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来表示工程建筑或机械构造、尺寸的图样。", "primary_collocate": null, "pronunciation": "gōng chéng tú", "ipa": "kʊŋ˥ ʈʂʰɤŋ˧˥ tʰu˧˥", "syllable_count": 3, "sentences": [{"text": "工程师把新桥的工程图画好了。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看工程图，我们就知道楼有几层。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们照着工程图一步一步盖房子。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张工程图上写着每根梁的尺寸。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅看懂了机器的工程图。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在桌上打开一张大工程图。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把工程图交给施工队。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工程图改了三次才通过。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在学习怎么画工程图。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有工程图，工厂不能造这台机器。", "target_word": "工程图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "工程图纸", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示建筑或机械构造、尺寸的专业图样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程图", "is_correct": true, "explanation": "「工程图」是表示工程构造、尺寸的图样，正是工程师画的东西。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“画”的对象应是图样，照片是拍出来的，不能说“画好了照片”。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，不是工程构造的图样，不能“画好”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，与新桥的工程毫无关系。"}], "explanations": {"工程图": "「工程图」是表示工程构造、尺寸的图样，正是工程师画的东西。", "照片": "搭配：“画”的对象应是图样，照片是拍出来的，不能说“画好了照片”。", "诗歌": "语义：诗歌是文学作品，不是工程构造的图样，不能“画好”。", "蛋糕": "语义：蛋糕是食物，与新桥的工程毫无关系。"}, "sentence_index": 0, "correct_answer": "工程图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程图已经开工三年了。", "explanation": "这里应该用〈工程〉。工程指整个建设项目，“开工”的是工程，工程图只是图样。"}, {"text": "医生看了工程图才开药。", "explanation": "这里应该用〈病历〉。工程图画的是建筑或机械的构造，不记录病情；了解病情要看〈病历〉。"}, {"text": "我们看工程图学写字。", "explanation": "这里应该用〈字帖〉。学写字要看〈字帖〉；工程图画的是建筑或机械的构造，不用来学写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程图", "is_correct": true, "explanation": "「工程图」是施工用的图样，“交给施工队”的正是它。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能“交给”施工队。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，不能“交给”施工队。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“交给”通常接东西或文件，不能说把老师交给施工队。"}], "explanations": {"工程图": "「工程图」是施工用的图样，“交给施工队”的正是它。", "月亮": "语义：月亮是天体，不能“交给”施工队。", "空气": "语义：空气看不见、摸不着，不能“交给”施工队。", "老师": "搭配：“交给”通常接东西或文件，不能说把老师交给施工队。"}, "sentence_index": 6, "correct_answer": "工程图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张工程图写着每个月的花费。", "explanation": "这里应该用〈账单〉。工程图记录的是构造和尺寸，不记录花费；记录花费要用〈账单〉。"}, {"text": "妈妈照着工程图做了一桌菜。", "explanation": "这里应该用〈菜谱〉。工程图讲的是盖房子、造机器的构造，做菜要照〈菜谱〉。"}, {"text": "歌手照着工程图唱歌。", "explanation": "这里应该用〈乐谱〉。工程图讲的是建筑或机械的构造，照着唱歌要看〈乐谱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
